INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C1','math',6,2,'u3',2,'두 수에 같은 수를 곱해도 몫은 그대로 — 단위를 바꾸거나(cm→mm, m→cm) 두 수를 똑같이 10배·100배 해서 나누는 수가 소수인 나눗셈을 자연수의 나눗셈으로 바꾸기',ARRAY['6수01-15']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C2','math',6,2,'u3',2,'소수를 분모가 같은 분수로 바꾸어 나누기 — 두 소수를 분모가 10(100)인 분수로 함께 바꾼 뒤 분자끼리 나누기',ARRAY['6수01-15']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C3','math',6,2,'u3',3,'(소수 한 자리)÷(소수 한 자리) 세로셈 — 나누는 수가 자연수가 되도록 두 수의 소수점을 똑같이 한 칸 옮기고, 몫의 소수점은 옮긴 자리에서 올려 찍기',ARRAY['6수01-15']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C4','math',6,2,'u3',4,'(소수 두 자리)÷(소수 두 자리) — 옮기는 칸수는 나누는 수의 소수 자리 수가 정함을 알고 두 수의 소수점을 두 칸씩 옮겨 계산하기',ARRAY['6수01-15']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C5','math',6,2,'u3',5,'자릿수가 다른 (소수)÷(소수) — 나누는 수가 자연수가 되는 만큼 두 수를 옮기고, 빈 자리는 0으로 채우며, 나누어지는 수에 소수점이 남아도 그대로 계산하기',ARRAY['6수01-15']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C6','math',6,2,'u3',6,'(자연수)÷(소수) — 자연수를 8 = 8.0처럼 보고 소수점을 함께 옮겨 빈 자리를 0으로 채우며, 1보다 작은 수로 나누면 몫이 나누어지는 수보다 커짐을 알기',ARRAY['6수01-15']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C7','math',6,2,'u3',7,'몫을 반올림하여 나타내기 — 나누어떨어지지 않는 몫을 나타낼 자리의 한 자리 아래 숫자를 보고 반올림하여 일의 자리·소수 첫째·둘째 자리까지 나타내기',ARRAY['6수01-15']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u3-C8','math',6,2,'u3',8,'나누어 주고 남는 양 — 나누어 줄 수 있는 수는 몫의 자연수 부분으로 정하고, 남는 양은 전체에서 (한 몫 × 나누어 준 수)를 빼서 구하기',ARRAY['6수01-15']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X01','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5']::text[],'두 수 가운데 한 수만 10배·100배 하거나 한 수의 소수점만 옮긴다(3.6 ÷ 0.5를 3.6 ÷ 5로)','두 수의 소수점은 똑같이 옮겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X02','math',6,'u3',ARRAY['M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6']::text[],'옮기는 칸수를 잘못 정한다 — 나누어지는 수의 소수 자리 수에 맞추거나 더 많이·적게 옮긴다','칸수는 나누는 수가 정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X03','math',6,'u3',ARRAY['M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6']::text[],'몫의 소수점을 옮기기 전 원래 자리에 찍어 몫을 10배·100배 작게 쓴다','몫의 소수점은 옮긴 자리에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X04','math',6,'u3',ARRAY['M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6']::text[],'몫의 소수점을 빠뜨리거나 한 자리 뒤에 찍어 몫을 10배·100배 크게 쓴다','어림한 값과 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X05','math',6,'u3',ARRAY['M6-2-u3-C2','M6-2-u3-C4']::text[],'소수를 분수로 바꿀 때 분모를 서로 다르게(10과 100을 섞어) 쓴다','두 수를 같은 분모로 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X06','math',6,'u3',ARRAY['M6-2-u3-C2']::text[],'한 수만 분수로 바꾸고 다른 수는 소수 그대로 둔다','둘 다 분수로 바꿔야 분자끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X07','math',6,'u3',ARRAY['M6-2-u3-C5','M6-2-u3-C6']::text[],'소수점을 옮길 때 빈 자리를 0으로 채우지 않는다(5.4를 두 칸 옮겨 54로)','빈 자리는 0으로 채워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X08','math',6,'u3',ARRAY['M6-2-u3-C6']::text[],'(자연수)÷(소수)에서 자연수 쪽 소수점은 옮기지 않는다(8 ÷ 1.6을 8 ÷ 16으로)','8은 8.0 — 함께 옮겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X09','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C6']::text[],'「나누면 몫은 작아진다」고 여겨 1보다 작은 수로 나눌 때 몫이 커지는 것을 틀렸다고 본다','1보다 작은 수로 나누면 몫이 커져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X10','math',6,'u3',ARRAY['M6-2-u3-C7']::text[],'반올림할 때 나타낼 자리의 숫자를 보고 올리거나 버린다(한 자리 아래를 봐야 한다)','나타낼 자리 바로 아래 숫자를 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X11','math',6,'u3',ARRAY['M6-2-u3-C7']::text[],'반올림하지 않고 아랫자리를 그냥 버린다','5 이상이면 올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X12','math',6,'u3',ARRAY['M6-2-u3-C7']::text[],'어느 자리까지 나타낼지 잘못 읽는다(일의 자리·소수 첫째·둘째 자리를 바꾼다)','「어느 자리까지」에 밑줄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X13','math',6,'u3',ARRAY['M6-2-u3-C8']::text[],'나누어 줄 수 있는 사람(그릇) 수를 몫을 반올림해 정한다','모자라면 줄 수 없어요 — 자연수 부분만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X14','math',6,'u3',ARRAY['M6-2-u3-C8']::text[],'남는 양을 몫의 소수 부분으로 읽는다(4.33…에서 0.3 L가 남는다고 본다)','남는 양은 전체 − 나누어 준 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X15','math',6,'u3',ARRAY['M6-2-u3-C8']::text[],'남는 양 대신 전체 양이나 나누어 준 양을 답으로 쓴다','무엇을 묻는지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X16','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C3','M6-2-u3-C5','M6-2-u3-C6']::text[],'몇 배·몇 번을 구하는데 나눗셈 대신 곱셈·뺄셈을 한다','몇 배인지는 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X17','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C3','M6-2-u3-C6']::text[],'나누어지는 수와 나누는 수를 바꾸어 쓴다','「무엇을 얼마씩」 — 무엇이 앞') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X18','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C4']::text[],'단위를 바꿀 때 한쪽만 바꾸거나 배수를 잘못 쓴다(1 cm = 10 mm, 1 m = 100 cm)','두 수를 같은 단위로 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X19','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C2','M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6','M6-2-u3-C7','M6-2-u3-C8']::text[],'묻는 말을 거꾸로 읽는다 — 옳은↔잘못된, 큰↔작은, 같은↔다른','물음의 「잘못·가장·다른」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X20','math',6,'u3',ARRAY['M6-2-u3-C1','M6-2-u3-C2','M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C5','M6-2-u3-C6','M6-2-u3-C7','M6-2-u3-C8']::text[],'옮긴 뒤 자연수의 나눗셈·곱셈을 잘못 계산한다','곱셈으로 거꾸로 확인해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X21','math',6,'u3',ARRAY['M6-2-u3-C8']::text[],'나누어 줄 수 있는 사람 수를 계산기 몫 그대로 「4.333…명」「4.3명」처럼 소수로 쓴다 — 사람 수는 하나, 둘로 세는 수다','사람 수는 자연수 — 몫의 자연수 부분만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X22','math',6,'u3',ARRAY['M6-2-u3-C5','M6-2-u3-C6']::text[],'몫이 가장 작은(큰) 나눗셈을 만들 때 나누는 수를 가장 작게(크게) 만든다 — 나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아짐을 거꾸로 생각한다','나누는 수가 클수록 몫은 작아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u3-X23','math',6,'u3',ARRAY['M6-2-u3-C3','M6-2-u3-C4','M6-2-u3-C8']::text[],'몫이 자연수로 나누어떨어지지 않을 때 0을 내려 계산하지 않고 「7 … 1」처럼 나머지로 멈추거나, 필요한 만큼만 구한 값과 남는 양을 몫·나머지라고 부른다','0을 내려 끝까지 — 남는 양은 「나누어 주고 남는 양」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#1','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',1,'mc','auto','6학년 1학기에 배운 (소수)÷(자연수)예요. 0.72 ÷ 4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"mc","stem":"6학년 1학기에 배운 (소수)÷(자연수)예요. 0.72 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"0.018","mis":"M6-2-u3-X03"},{"t":"1.8","mis":"M6-2-u3-X04"},{"t":"0.0018","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 4는 자연수라 소수점을 옮기지 않아요.","나누어지는 수의 소수점을 그대로 위로 올려 찍어요.","0.72 ÷ 4 = 0.18이에요."],"variant_rule":{"alt":[{"stem":"6학년 1학기에 배운 (소수)÷(자연수)예요. 13 ÷ 5의 몫은 얼마인가요?","options":[{"t":"2.6","correct":true},{"t":"0.26","mis":"M6-2-u3-X03"},{"t":"26","mis":"M6-2-u3-X04"},{"t":"0.026","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 5는 자연수라 소수점을 옮기지 않아요.","나누어지는 수의 소수점을 그대로 위로 올려 찍어요.","13 ÷ 5 = 2.6이에요."]},{"stem":"6학년 1학기에 배운 (소수)÷(자연수)예요. 3.8 ÷ 2의 몫은 얼마인가요?","options":[{"t":"1.9","correct":true},{"t":"0.19","mis":"M6-2-u3-X03"},{"t":"19","mis":"M6-2-u3-X04"},{"t":"0.019","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 2는 자연수라 소수점을 옮기지 않아요.","나누어지는 수의 소수점을 그대로 위로 올려 찍어요.","3.8 ÷ 2 = 1.9예요."]},{"stem":"6학년 1학기에 배운 (소수)÷(자연수)예요. 2.52 ÷ 4의 몫은 얼마인가요?","options":[{"t":"0.63","correct":true},{"t":"0.063","mis":"M6-2-u3-X03"},{"t":"6.3","mis":"M6-2-u3-X04"},{"t":"0.0063","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 4는 자연수라 소수점을 옮기지 않아요.","나누어지는 수의 소수점을 그대로 위로 올려 찍어요.","2.52 ÷ 4 = 0.63이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#2','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C2',1,'sa','auto','⟨9/10⟩ ÷ ⟨3/10⟩은 분모가 같으니 분자끼리 나누어 9 ÷ 3과 같아요. 몫은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C2","difficulty":1,"kind":"sa","stem":"⟨9/10⟩ ÷ ⟨3/10⟩은 분모가 같으니 분자끼리 나누어 9 ÷ 3과 같아요. 몫은 얼마인가요?","answer":["3"],"explanation":["분모가 같은 두 분수는 분자끼리 나눌 수 있어요.","⟨9/10⟩ ÷ ⟨3/10⟩ = 9 ÷ 3이에요.","9 ÷ 3 = 3이에요."],"variant_rule":{"alt":[{"stem":"⟨78/100⟩ ÷ ⟨6/100⟩은 분모가 같으니 분자끼리 나누어 78 ÷ 6과 같아요. 몫은 얼마인가요?","answer":["13"],"explanation":["분모가 같은 두 분수는 분자끼리 나눌 수 있어요.","⟨78/100⟩ ÷ ⟨6/100⟩ = 78 ÷ 6이에요.","78 ÷ 6 = 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#3','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',1,'sa','auto','축하 장식을 만들려고 분홍색 리본 1.5 m를 0.3 m씩 잘라요. 리본은 몇 도막이 되나요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"축하 장식을 만들려고 분홍색 리본 1.5 m를 0.3 m씩 잘라요. 리본은 몇 도막이 되나요?","answer":["5"],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","1.5 ÷ 0.3은 15 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","15 ÷ 3 = 5예요."],"variant_rule":{"alt":[{"stem":"페인트 5.4 L를 통 한 개에 0.6 L씩 나누어 담으려고 해요. 필요한 통은 몇 개인가요?","answer":["9"],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","5.4 ÷ 0.6은 54 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","54 ÷ 6 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#4','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',1,'mc','auto','빨간색 화분의 강낭콩 싹의 길이는 2.4 cm, 노란색 화분의 강낭콩 싹의 길이는 0.8 cm예요. 강낭콩 싹의 길이는 노란색 화분의 강낭콩 싹의 길이의 몇 배인지 구하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X17','M6-2-u3-X16']::text[],true,'{"seq":4,"concept":"M6-2-u3-C1","difficulty":1,"kind":"mc","stem":"빨간색 화분의 강낭콩 싹의 길이는 2.4 cm, 노란색 화분의 강낭콩 싹의 길이는 0.8 cm예요. 강낭콩 싹의 길이는 노란색 화분의 강낭콩 싹의 길이의 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"2.4 ÷ 0.8","correct":true},{"t":"0.8 ÷ 2.4","mis":"M6-2-u3-X17"},{"t":"2.4 − 0.8","mis":"M6-2-u3-X16"},{"t":"2.4 × 0.8","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 나눗셈으로 구해요.","강낭콩 싹의 길이를 노란색 화분의 강낭콩 싹의 길이로 나눠요.","그래서 2.4 ÷ 0.8이에요."],"variant_rule":{"alt":[{"stem":" 엄마 범고래의 몸의 길이는 8.24 m, 아기 범고래의 몸의 길이는 4.12 m예요. 엄마 범고래의 몸의 길이는 아기 범고래의 몸의 길이의 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"8.24 ÷ 4.12","correct":true},{"t":"4.12 ÷ 8.24","mis":"M6-2-u3-X17"},{"t":"8.24 − 4.12","mis":"M6-2-u3-X16"},{"t":"8.24 × 4.12","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 나눗셈으로 구해요.","엄마 범고래의 몸의 길이를 아기 범고래의 몸의 길이로 나눠요.","그래서 8.24 ÷ 4.12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#5','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',2,'mc','auto','빨간색 화분의 강낭콩 싹의 길이는 2.4 cm, 노란색 화분의 강낭콩 싹의 길이는 0.8 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X18','M6-2-u3-X17']::text[],true,'{"seq":5,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"빨간색 화분의 강낭콩 싹의 길이는 2.4 cm, 노란색 화분의 강낭콩 싹의 길이는 0.8 cm예요. cm를 mm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"24 ÷ 8","correct":true},{"t":"24 ÷ 0.8","mis":"M6-2-u3-X18"},{"t":"2.4 ÷ 8","mis":"M6-2-u3-X18"},{"t":"8 ÷ 24","mis":"M6-2-u3-X17"}],"explanation":["1 cm는 10 mm예요.","2.4 cm는 24 mm, 0.8 cm는 8 mm가 돼요.","두 수를 같은 단위로 함께 바꾸면 24 ÷ 8이에요."],"variant_rule":{"alt":[{"stem":"엄마 범고래의 몸의 길이는 8.24 m, 아기 범고래의 몸의 길이는 4.12 m예요. m를 cm로 바꾸어 몇 배인지 구하는 식은 어느 것인가요?","options":[{"t":"824 ÷ 412","correct":true},{"t":"824 ÷ 4.12","mis":"M6-2-u3-X18"},{"t":"8.24 ÷ 412","mis":"M6-2-u3-X18"},{"t":"412 ÷ 824","mis":"M6-2-u3-X17"}],"explanation":["1 m는 100 cm예요.","8.24 m는 824 cm, 4.12 m는 412 cm가 돼요.","두 수를 같은 단위로 함께 바꾸면 824 ÷ 412예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#6','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',2,'sa','auto','빨간색 화분의 강낭콩 싹은 2.4 cm, 노란색 화분의 강낭콩 싹은 0.8 cm예요. 2.4에서 0.8을 몇 번 덜어 낼 수 있나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u3-C1","difficulty":2,"kind":"sa","stem":"빨간색 화분의 강낭콩 싹은 2.4 cm, 노란색 화분의 강낭콩 싹은 0.8 cm예요. 2.4에서 0.8을 몇 번 덜어 낼 수 있나요?","answer":["3"],"explanation":["2.4 − 0.8 = 1.6, 1.6 − 0.8 = 0.8이에요.","0.8 − 0.8 = 0 — 세 번 덜어 냈어요.","2.4 ÷ 0.8 = 3 — 3배예요."],"variant_rule":{"alt":[{"stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 8.24에서 4.12를 몇 번 덜어 낼 수 있나요?","answer":["2"],"explanation":["8.24 − 4.12 = 4.12예요.","4.12 − 4.12 = 0 — 두 번 덜어 냈어요.","8.24 ÷ 4.12 = 2 — 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#7','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C2',2,'mc','auto','8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":7,"concept":"M6-2-u3-C2","difficulty":2,"kind":"mc","stem":"8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨84/10⟩ ÷ ⟨21/10⟩","correct":true},{"t":"⟨84/10⟩ ÷ 2.1","mis":"M6-2-u3-X06"},{"t":"⟨84/10⟩ ÷ ⟨210/100⟩","mis":"M6-2-u3-X05"},{"t":"8.4 ÷ ⟨21/10⟩","mis":"M6-2-u3-X06"}],"explanation":["8.4는 ⟨84/10⟩, 2.1은 ⟨21/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨84/10⟩ ÷ ⟨21/10⟩이에요."],"variant_rule":{"alt":[{"stem":"7.7 ÷ 1.1을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨77/10⟩ ÷ ⟨11/10⟩","correct":true},{"t":"⟨77/10⟩ ÷ 1.1","mis":"M6-2-u3-X06"},{"t":"⟨77/10⟩ ÷ ⟨110/100⟩","mis":"M6-2-u3-X05"},{"t":"7.7 ÷ ⟨11/10⟩","mis":"M6-2-u3-X06"}],"explanation":["7.7은 ⟨77/10⟩, 1.1은 ⟨11/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨77/10⟩ ÷ ⟨11/10⟩이에요."]},{"stem":"4.2 ÷ 0.3을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨42/10⟩ ÷ ⟨3/10⟩","correct":true},{"t":"⟨42/10⟩ ÷ 0.3","mis":"M6-2-u3-X06"},{"t":"⟨42/10⟩ ÷ ⟨30/100⟩","mis":"M6-2-u3-X05"},{"t":"4.2 ÷ ⟨3/10⟩","mis":"M6-2-u3-X06"}],"explanation":["4.2는 ⟨42/10⟩, 0.3은 ⟨3/10⟩이에요.","두 수를 분모가 10인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨42/10⟩ ÷ ⟨3/10⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#8','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C2',2,'sa','auto','⟨84/10⟩ ÷ ⟨21/10⟩은 분자끼리 나누어 84 ÷ 21이 돼요. 8.4 ÷ 2.1의 몫은 얼마인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u3-C2","difficulty":2,"kind":"sa","stem":"⟨84/10⟩ ÷ ⟨21/10⟩은 분자끼리 나누어 84 ÷ 21이 돼요. 8.4 ÷ 2.1의 몫은 얼마인가요?","answer":["4"],"explanation":["8.4 ÷ 2.1은 ⟨84/10⟩ ÷ ⟨21/10⟩과 같아요.","분모가 같으니 분자끼리 84 ÷ 21이에요.","몫은 4예요."],"variant_rule":{"alt":[{"stem":"⟨77/10⟩ ÷ ⟨11/10⟩은 분자끼리 나누어 77 ÷ 11이 돼요. 7.7 ÷ 1.1의 몫은 얼마인가요?","answer":["7"],"explanation":["7.7 ÷ 1.1은 ⟨77/10⟩ ÷ ⟨11/10⟩과 같아요.","분모가 같으니 분자끼리 77 ÷ 11이에요.","몫은 7이에요."]},{"stem":"⟨42/10⟩ ÷ ⟨3/10⟩은 분자끼리 나누어 42 ÷ 3이 돼요. 4.2 ÷ 0.3의 몫은 얼마인가요?","answer":["14"],"explanation":["4.2 ÷ 0.3은 ⟨42/10⟩ ÷ ⟨3/10⟩과 같아요.","분모가 같으니 분자끼리 42 ÷ 3이에요.","몫은 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#9','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C1',2,'mc','auto','8.4 ÷ 2.1을 84 ÷ 21로 바꾸어 계산했어요. 두 수를 어떻게 바꾼 것인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":9,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"8.4 ÷ 2.1을 84 ÷ 21로 바꾸어 계산했어요. 두 수를 어떻게 바꾼 것인가요?","options":[{"t":"두 수 모두 10배","correct":true},{"t":"8.4만 10배","mis":"M6-2-u3-X01"},{"t":"2.1만 10배","mis":"M6-2-u3-X01"},{"t":"두 수 모두 100배","mis":"M6-2-u3-X02"}],"explanation":["8.4의 10배는 84, 2.1의 10배는 21이에요.","두 수에 똑같이 10을 곱했어요.","두 수에 같은 수를 곱하면 몫은 그대로예요."],"variant_rule":{"alt":[{"stem":"2.24 ÷ 0.08을 224 ÷ 8로 바꾸어 계산했어요. 두 수를 어떻게 바꾼 것인가요?","options":[{"t":"두 수 모두 100배","correct":true},{"t":"2.24만 100배","mis":"M6-2-u3-X01"},{"t":"0.08만 100배","mis":"M6-2-u3-X01"},{"t":"두 수 모두 10배","mis":"M6-2-u3-X02"}],"explanation":["2.24의 100배는 224, 0.08의 100배는 8이에요.","두 수에 똑같이 100을 곱했어요.","두 수에 같은 수를 곱하면 몫은 그대로예요."]},{"stem":"5.4 ÷ 0.45를 540 ÷ 45로 바꾸어 계산했어요. 두 수를 어떻게 바꾼 것인가요?","options":[{"t":"두 수 모두 100배","correct":true},{"t":"5.4만 100배","mis":"M6-2-u3-X01"},{"t":"0.45만 100배","mis":"M6-2-u3-X01"},{"t":"두 수 모두 10배","mis":"M6-2-u3-X02"}],"explanation":["5.4의 100배는 540, 0.45의 100배는 45예요.","두 수에 똑같이 100을 곱했어요.","두 수에 같은 수를 곱하면 몫은 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_basic#10','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_basic','lesson_basic','M6-2-u3-C2',3,'ox','auto','8.4 ÷ 2.1을 분수로 바꿀 때 8.4만 ⟨84/10⟩로 바꾸고 2.1은 소수 그대로 두어도 분자끼리 나눌 수 있어요.',ARRAY['M6-2-u3-X06']::text[],true,'{"seq":10,"concept":"M6-2-u3-C2","difficulty":3,"kind":"ox","stem":"8.4 ÷ 2.1을 분수로 바꿀 때 8.4만 ⟨84/10⟩로 바꾸고 2.1은 소수 그대로 두어도 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 소수를 분모가 같은 분수로 함께 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수와 소수는 그대로 분자끼리 나눌 수 있기 때문에","mis":"M6-2-u3-X06"}],"mis":"M6-2-u3-X06","explanation":["⟨84/10⟩ ÷ 2.1은 분자끼리 나눌 수 없어요.","2.1도 ⟨21/10⟩로 바꾸어야 해요.","⟨84/10⟩ ÷ ⟨21/10⟩ = 84 ÷ 21 = 4예요."],"variant_rule":{"alt":[{"stem":"2.24 ÷ 0.08을 ⟨224/100⟩ ÷ ⟨8/10⟩로 바꾸면 분자끼리 나눌 수 있어요.","answer":"X","reason_options":[{"t":"두 소수를 분모가 같은 분수로 바꿔야 분자끼리 나눌 수 있기 때문에","correct":true},{"t":"분수로 바꾸기만 하면 분모는 달라도 되기 때문에","mis":"M6-2-u3-X05"}],"explanation":["0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔요.","⟨224/100⟩ ÷ ⟨8/100⟩ = 224 ÷ 8 = 28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#1','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',2,'ox','auto','1.5 ÷ 3의 몫은 0.5예요. 그러니 1.5 ÷ 0.3의 몫도 0.5예요.',ARRAY['M6-2-u3-X09']::text[],false,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":2,"kind":"ox","stem":"1.5 ÷ 3의 몫은 0.5예요. 그러니 1.5 ÷ 0.3의 몫도 0.5예요.","answer":"X","reason_options":[{"t":"0.3은 3보다 작아 1.5 안에 더 여러 번 들어가서 몫이 커지기 때문에","correct":true},{"t":"나누는 수의 숫자가 같으면 몫도 같기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["1.5 ÷ 0.3은 두 수를 10배 한 15 ÷ 3과 같아요.","15 ÷ 3 = 5예요.","1.5 ÷ 0.3 = 5 — 리본은 5도막이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#2','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',2,'mc','auto','639 ÷ 3 = 213이에요. 그렇다면 63.9 ÷ 3의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":2,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"639 ÷ 3 = 213이에요. 그렇다면 63.9 ÷ 3의 몫은 얼마인가요?","options":[{"t":"21.3","correct":true},{"t":"2.13","mis":"M6-2-u3-X03"},{"t":"213","mis":"M6-2-u3-X04"},{"t":"0.213","mis":"M6-2-u3-X03"}],"explanation":["63.9는 639의 ⟨1/10⟩배예요.","나누는 수가 같으면 몫도 ⟨1/10⟩배가 돼요.","213의 ⟨1/10⟩배는 21.3이에요."],"asset":{"type":"expr_grid","rows":[["639 ÷ 3","=","213"],["63.9 ÷ 3","=",null]]},"variant_rule":{"alt":[{"stem":"639 ÷ 3 = 213이에요. 그렇다면 6.39 ÷ 3의 몫은 얼마인가요?","options":[{"t":"2.13","correct":true},{"t":"21.3","mis":"M6-2-u3-X04"},{"t":"213","mis":"M6-2-u3-X04"},{"t":"0.213","mis":"M6-2-u3-X03"}],"explanation":["6.39는 639의 ⟨1/100⟩배예요.","나누는 수가 같으면 몫도 ⟨1/100⟩배가 돼요.","213의 ⟨1/100⟩배는 2.13이에요."],"asset":{"type":"expr_grid","rows":[["639 ÷ 3","=","213"],["6.39 ÷ 3","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#3','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',3,'mc','auto','4.9 ÷ 0.7을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?',ARRAY['M6-2-u3-X06','M6-2-u3-X01','M6-2-u3-X05']::text[],true,'{"seq":3,"concept":"M6-2-u3-C2","difficulty":3,"kind":"mc","stem":"4.9 ÷ 0.7을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"49 ÷ 7","correct":true},{"t":"49 ÷ 0.7","mis":"M6-2-u3-X06"},{"t":"4.9 ÷ 7","mis":"M6-2-u3-X01"},{"t":"49 ÷ 70","mis":"M6-2-u3-X05"}],"explanation":["4.9 = ⟨49/10⟩, 0.7 = ⟨7/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 49 ÷ 7이에요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"72 ÷ 6","correct":true},{"t":"72 ÷ 0.6","mis":"M6-2-u3-X06"},{"t":"7.2 ÷ 6","mis":"M6-2-u3-X01"},{"t":"72 ÷ 60","mis":"M6-2-u3-X05"}],"explanation":["7.2 = ⟨72/10⟩, 0.6 = ⟨6/10⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 72 ÷ 6이에요."]},{"stem":"1.68 ÷ 0.07을 분모가 같은 분수로 바꾸어 계산해요. 분자끼리의 나눗셈은 무엇이 되나요?","options":[{"t":"168 ÷ 7","correct":true},{"t":"168 ÷ 0.07","mis":"M6-2-u3-X06"},{"t":"1.68 ÷ 7","mis":"M6-2-u3-X01"},{"t":"168 ÷ 70","mis":"M6-2-u3-X05"}],"explanation":["1.68 = ⟨168/100⟩, 0.07 = ⟨7/100⟩이에요.","분모가 같으니 분자끼리 나눠요.","그래서 168 ÷ 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#4','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',3,'mc','auto','cm를 mm로 바꾸어 2.4 ÷ 0.8을 24 ÷ 8로 계산해도 몫이 같은 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X18']::text[],true,'{"seq":4,"concept":"M6-2-u3-C1","difficulty":3,"kind":"mc","stem":"cm를 mm로 바꾸어 2.4 ÷ 0.8을 24 ÷ 8로 계산해도 몫이 같은 까닭은 무엇인가요?","options":[{"t":"두 수가 똑같이 10배가 되어서","correct":true},{"t":"나누어지는 수만 10배가 되어서","mis":"M6-2-u3-X01"},{"t":"나누는 수만 10배가 되어서","mis":"M6-2-u3-X01"},{"t":"두 수가 모두 작아져서","mis":"M6-2-u3-X18"}],"explanation":["1 cm는 10 mm라서 cm를 mm로 바꾸면 두 수가 모두 10배가 돼요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","그래서 24 ÷ 8 = 3이 2.4 ÷ 0.8의 몫이에요."],"variant_rule":{"alt":[{"stem":"m를 cm로 바꾸어 8.24 ÷ 4.12를 824 ÷ 412로 계산해도 몫이 같은 까닭은 무엇인가요?","options":[{"t":"두 수가 똑같이 100배가 되어서","correct":true},{"t":"나누어지는 수만 100배가 되어서","mis":"M6-2-u3-X01"},{"t":"나누는 수만 100배가 되어서","mis":"M6-2-u3-X01"},{"t":"두 수가 모두 10배가 되어서","mis":"M6-2-u3-X18"}],"explanation":["1 m는 100 cm라서 두 수가 모두 100배가 돼요.","두 수에 똑같은 수를 곱하면 몫은 그대로예요.","그래서 824 ÷ 412 = 2가 8.24 ÷ 4.12의 몫이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#5','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',3,'error','auto','8.4 ÷ 2.1을 계산하는 방법을 늘어놓았어요. 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X19']::text[],true,'{"seq":5,"concept":"M6-2-u3-C2","difficulty":3,"kind":"error","stem":"8.4 ÷ 2.1을 계산하는 방법을 늘어놓았어요. 잘못된 것은 어느 것인가요?","options":[{"t":"⟨84/10⟩ ÷ 2.1로 바꾸어 분자끼리 84 ÷ 2.1을 한다","correct":true,"mis_target":"M6-2-u3-X06"},{"t":"⟨84/10⟩ ÷ ⟨21/10⟩로 바꾸어 84 ÷ 21을 한다","mis":"M6-2-u3-X19"},{"t":"두 수에 똑같이 10을 곱해 84 ÷ 21을 한다","mis":"M6-2-u3-X19"},{"t":"두 수의 소수점을 똑같이 한 칸씩 옮긴다","mis":"M6-2-u3-X19"}],"explanation":["분수로 바꾸든, 10을 곱하든, 소수점을 옮기든 두 수를 똑같이 바꾸는 방법이에요.","한 수만 분수로 바꾸면 분자끼리 나눌 수 없어요.","바른 몫은 84 ÷ 21 = 4예요."],"variant_rule":{"alt":[{"stem":"2.24 ÷ 0.08을 계산하는 방법을 늘어놓았어요. 잘못된 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/10⟩로 바꾸어 분자끼리 224 ÷ 8을 한다","correct":true,"mis_target":"M6-2-u3-X05"},{"t":"⟨224/100⟩ ÷ ⟨8/100⟩로 바꾸어 224 ÷ 8을 한다","mis":"M6-2-u3-X19"},{"t":"두 수에 똑같이 100을 곱해 224 ÷ 8을 한다","mis":"M6-2-u3-X19"},{"t":"두 수의 소수점을 똑같이 두 칸씩 옮긴다","mis":"M6-2-u3-X19"}],"explanation":["0.08은 ⟨8/100⟩이에요.","분모가 같아야 분자끼리 나눌 수 있어요.","바른 몫은 224 ÷ 8 = 28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#6','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',3,'mc','auto','8.4 ÷ 2.1과 몫이 같은 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":6,"concept":"M6-2-u3-C1","difficulty":3,"kind":"mc","stem":"8.4 ÷ 2.1과 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"84 ÷ 21","correct":true},{"t":"8.4 ÷ 21","mis":"M6-2-u3-X01"},{"t":"84 ÷ 2.1","mis":"M6-2-u3-X01"},{"t":"840 ÷ 21","mis":"M6-2-u3-X02"}],"explanation":["두 수에 똑같은 수를 곱해야 몫이 그대로예요.","8.4 ÷ 2.1의 두 수에 똑같이 10을 곱하면 84 ÷ 21이에요.","한 수만 바꾼 식은 몫이 달라요."],"variant_rule":{"alt":[{"stem":"2.4 ÷ 0.8과 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"24 ÷ 8","correct":true},{"t":"2.4 ÷ 8","mis":"M6-2-u3-X01"},{"t":"24 ÷ 0.8","mis":"M6-2-u3-X01"},{"t":"240 ÷ 8","mis":"M6-2-u3-X02"}],"explanation":["두 수에 똑같은 수를 곱해야 몫이 그대로예요.","2.4 ÷ 0.8의 두 수에 똑같이 10을 곱하면 24 ÷ 8이에요.","한 수만 바꾼 식은 몫이 달라요."]},{"stem":"8.24 ÷ 4.12와 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"824 ÷ 412","correct":true},{"t":"8.24 ÷ 412","mis":"M6-2-u3-X01"},{"t":"824 ÷ 4.12","mis":"M6-2-u3-X01"},{"t":"8240 ÷ 412","mis":"M6-2-u3-X02"}],"explanation":["두 수에 똑같은 수를 곱해야 몫이 그대로예요.","8.24 ÷ 4.12의 두 수에 똑같이 100을 곱하면 824 ÷ 412예요.","한 수만 바꾼 식은 몫이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#7','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',3,'mc','auto','빨간색 화분의 강낭콩 싹은 2.4 cm, 노란색 화분의 강낭콩 싹은 0.8 cm예요. 몇 배인지 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":7,"concept":"M6-2-u3-C1","difficulty":3,"kind":"mc","stem":"빨간색 화분의 강낭콩 싹은 2.4 cm, 노란색 화분의 강낭콩 싹은 0.8 cm예요. 몇 배인지 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2.4에서 0.8을 한 번 빼 본다","correct":true},{"t":"cm를 mm로 바꾸어 24 ÷ 8을 계산한다","mis":"M6-2-u3-X19"},{"t":"⟨24/10⟩ ÷ ⟨8/10⟩을 계산한다","mis":"M6-2-u3-X19"},{"t":"2.4에서 0.8을 몇 번 덜어 낼 수 있는지 센다","mis":"M6-2-u3-X19"}],"explanation":["몇 배인지는 2.4 ÷ 0.8로 구해요.","단위 바꾸기·분수로 바꾸기·덜어 내기는 모두 같은 몫 3을 줘요.","한 번 빼 보는 것은 차이를 구할 뿐 몇 배인지는 알 수 없어요."],"variant_rule":{"alt":[{"stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 몇 배인지 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"8.24에서 4.12를 한 번 빼 본다","correct":true},{"t":"m를 cm로 바꾸어 824 ÷ 412를 계산한다","mis":"M6-2-u3-X19"},{"t":"⟨824/100⟩ ÷ ⟨412/100⟩를 계산한다","mis":"M6-2-u3-X19"},{"t":"8.24에서 4.12를 몇 번 덜어 낼 수 있는지 센다","mis":"M6-2-u3-X19"}],"explanation":["몇 배인지는 8.24 ÷ 4.12로 구해요.","단위 바꾸기·분수로 바꾸기·덜어 내기는 모두 같은 몫 2를 줘요.","한 번 빼 보는 것은 차이를 구할 뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#8','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',4,'sa','auto','보기: 1.28 ÷ 0.16 = ⟨128/100⟩ ÷ ⟨16/100⟩ = 128 ÷ 16 = 8. 보기와 같이 분수의 나눗셈으로 24.15 ÷ 1.05를 계산하면 몫은 얼마인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u3-C2","difficulty":4,"kind":"sa","stem":"보기: 1.28 ÷ 0.16 = ⟨128/100⟩ ÷ ⟨16/100⟩ = 128 ÷ 16 = 8. 보기와 같이 분수의 나눗셈으로 24.15 ÷ 1.05를 계산하면 몫은 얼마인가요?","answer":["23"],"explanation":["24.15 = ⟨2415/100⟩, 1.05 = ⟨105/100⟩예요.","분모가 같으니 분자끼리 2415 ÷ 105예요.","2415 ÷ 105 = 23이에요."],"variant_rule":{"alt":[{"stem":"보기: 1.56 ÷ 0.39 = ⟨156/100⟩ ÷ ⟨39/100⟩ = 156 ÷ 39 = 4. 보기와 같이 분수의 나눗셈으로 2.58 ÷ 0.43을 계산하면 몫은 얼마인가요?","answer":["6"],"explanation":["2.58 = ⟨258/100⟩, 0.43 = ⟨43/100⟩이에요.","분모가 같으니 분자끼리 258 ÷ 43이에요.","258 ÷ 43 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#9','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C1',4,'essay','teacher','빨간색 화분의 강낭콩 싹은 2.4 cm, 노란색 화분의 강낭콩 싹은 0.8 cm예요. 빨간색 화분의 싹이 노란색 화분의 싹의 몇 배인지 cm를 mm로 바꾸어 구하고, 그렇게 바꾸어도 몫이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C1","difficulty":4,"kind":"essay","stem":"빨간색 화분의 강낭콩 싹은 2.4 cm, 노란색 화분의 강낭콩 싹은 0.8 cm예요. 빨간색 화분의 싹이 노란색 화분의 싹의 몇 배인지 cm를 mm로 바꾸어 구하고, 그렇게 바꾸어도 몫이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 2.4 cm는 24 mm, 0.8 cm는 8 mm이므로 24 ÷ 8 = 3, 3배이다. 단위를 바꾸면 두 수가 똑같이 10배가 되는데, 나누는 수와 나누어지는 수에 0이 아닌 같은 수를 곱하면 몫은 변하지 않으므로 2.4 ÷ 0.8의 몫도 3이다.","scoring_points":["24 ÷ 8 = 3(3배)을 썼는가","두 수가 똑같이 10배가 되었음을 밝혔는가","같은 수를 곱해도 몫은 변하지 않는다는 까닭을 썼는가"]},"explanation":["2.4 cm는 24 mm, 0.8 cm는 8 mm예요.","두 수가 똑같이 10배가 되었어요.","그래서 몫은 그대로 — 24 ÷ 8 = 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L02_challenge#10','math',6,2,'u3','L02','tb_g6_2_math_u3_L02_challenge','lesson_challenge','M6-2-u3-C2',4,'essay','teacher','8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바꾸어 계산하고, 두 소수를 왜 같은 분모로 바꾸어야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C2","difficulty":4,"kind":"essay","stem":"8.4 ÷ 2.1을 분모가 같은 분수의 나눗셈으로 바꾸어 계산하고, 두 소수를 왜 같은 분모로 바꾸어야 하는지 설명해 보세요.","answer_guide":{"answer":"예: 8.4 = ⟨84/10⟩, 2.1 = ⟨21/10⟩이므로 ⟨84/10⟩ ÷ ⟨21/10⟩ = 84 ÷ 21 = 4이다. 분모가 같아야 ⟨1/10⟩이 몇 개인지 두 수를 견주어 분자끼리 나눌 수 있다.","scoring_points":["⟨84/10⟩ ÷ ⟨21/10⟩로 바꾸었는가","84 ÷ 21 = 4를 구했는가","분모가 같아야 분자끼리 나눌 수 있다는 까닭을 썼는가"]},"explanation":["8.4는 ⟨84/10⟩, 2.1은 ⟨21/10⟩이에요.","분모가 같으면 분자끼리 84 ÷ 21이에요.","몫은 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#1','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'sa','auto','8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"8.4 ÷ 2.1을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 2.1이 정해요.","2.1이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 0.5가 정해요.","0.5가 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]},{"stem":"24.5 ÷ 3.5를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 3.5가 정해요.","3.5가 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#2','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'mc','auto','8.4 ÷ 2.1에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":2,"concept":"M6-2-u3-C3","difficulty":1,"kind":"mc","stem":"8.4 ÷ 2.1에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"84 ÷ 21","correct":true},{"t":"8.4 ÷ 21","mis":"M6-2-u3-X01"},{"t":"84 ÷ 2.1","mis":"M6-2-u3-X01"},{"t":"840 ÷ 21","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 2.1이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 8.4도 똑같이 한 칸 옮겨요.","그래서 84 ÷ 21이 돼요."],"variant_rule":{"alt":[{"stem":"3.6 ÷ 0.5에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"36 ÷ 5","correct":true},{"t":"3.6 ÷ 5","mis":"M6-2-u3-X01"},{"t":"36 ÷ 0.5","mis":"M6-2-u3-X01"},{"t":"360 ÷ 5","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 0.5가 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 3.6도 똑같이 한 칸 옮겨요.","그래서 36 ÷ 5가 돼요."]},{"stem":"48.3 ÷ 2.3에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"483 ÷ 23","correct":true},{"t":"48.3 ÷ 23","mis":"M6-2-u3-X01"},{"t":"483 ÷ 2.3","mis":"M6-2-u3-X01"},{"t":"4830 ÷ 23","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 2.3이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 48.3도 똑같이 한 칸 옮겨요.","그래서 483 ÷ 23이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#3','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'sa','auto','4.9 ÷ 0.7을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 49 ÷ 7로 바꾸었어요. 4.9 ÷ 0.7의 몫은 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"4.9 ÷ 0.7을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 49 ÷ 7로 바꾸었어요. 4.9 ÷ 0.7의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 0.7이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.9 ÷ 0.7은 49 ÷ 7이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","49 ÷ 7 = 7이에요."],"asset":{"type":"ldiv","a":49,"b":7,"hide":["q"]},"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.6을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 72 ÷ 6으로 바꾸었어요. 7.2 ÷ 0.6의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","7.2 ÷ 0.6은 72 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","72 ÷ 6 = 12예요."],"asset":{"type":"ldiv","a":72,"b":6,"hide":["q"]}},{"stem":"48.3 ÷ 2.3을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 483 ÷ 23으로 바꾸었어요. 48.3 ÷ 2.3의 몫은 얼마인가요?","answer":["21"],"explanation":["나누는 수 2.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","48.3 ÷ 2.3은 483 ÷ 23이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","483 ÷ 23 = 21이에요."],"asset":{"type":"ldiv","a":483,"b":23,"hide":["q"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#4','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',1,'sa','auto','꿀 24.5 kg을 통 한 개에 3.5 kg씩 나누어 담으려고 해요. 필요한 통은 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"꿀 24.5 kg을 통 한 개에 3.5 kg씩 나누어 담으려고 해요. 필요한 통은 몇 개인가요?","answer":["7"],"explanation":["나누는 수 3.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","24.5 ÷ 3.5는 245 ÷ 35가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","245 ÷ 35 = 7이에요."],"variant_rule":{"alt":[{"stem":"수지는 주스 2.7 L를 컵 한 개에 0.3 L씩 담았어요. 주스를 담은 컵은 몇 개인가요?","answer":["9"],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","2.7 ÷ 0.3은 27 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","27 ÷ 3 = 9예요."]},{"stem":"은우는 주스 2.8 L를 컵 한 개에 0.4 L씩 담았어요. 주스를 담은 컵은 몇 개인가요?","answer":["7"],"explanation":["나누는 수 0.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","2.8 ÷ 0.4는 28 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","28 ÷ 4 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#5','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','3.6 ÷ 0.5의 몫은 얼마인가요?',ARRAY['M6-2-u3-X23','M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":5,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"3.6 ÷ 0.5의 몫은 얼마인가요?","options":[{"t":"7.2","correct":true},{"t":"7 … 1","mis":"M6-2-u3-X23"},{"t":"0.72","mis":"M6-2-u3-X03"},{"t":"72","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.6 ÷ 0.5는 36 ÷ 5가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","36 ÷ 5 = 7.2 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."],"variant_rule":{"alt":[{"stem":"9.3 ÷ 1.5의 몫은 얼마인가요?","options":[{"t":"6.2","correct":true},{"t":"6 … 3","mis":"M6-2-u3-X23"},{"t":"0.62","mis":"M6-2-u3-X03"},{"t":"62","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 1.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","9.3 ÷ 1.5는 93 ÷ 15가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","93 ÷ 15 = 6.2 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]},{"stem":"28.8 ÷ 4.5의 몫은 얼마인가요?","options":[{"t":"6.4","correct":true},{"t":"6 … 18","mis":"M6-2-u3-X23"},{"t":"0.64","mis":"M6-2-u3-X03"},{"t":"64","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 4.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","28.8 ÷ 4.5는 288 ÷ 45가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","288 ÷ 45 = 6.4 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#6','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','3.6 ÷ 0.5를 36 ÷ 5로 바꾸어 세로로 계산하니 몫이 자연수로 나누어떨어지지 않아요. 어떻게 계산해야 하나요?',ARRAY['M6-2-u3-X23','M6-2-u3-X11','M6-2-u3-X01']::text[],true,'{"seq":6,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"3.6 ÷ 0.5를 36 ÷ 5로 바꾸어 세로로 계산하니 몫이 자연수로 나누어떨어지지 않아요. 어떻게 계산해야 하나요?","options":[{"t":"36 뒤에 0을 내려 계속 나눈다","correct":true},{"t":"몫 7, 나머지 1로 쓰고 멈춘다","mis":"M6-2-u3-X23"},{"t":"몫을 반올림해 7로 쓴다","mis":"M6-2-u3-X11"},{"t":"나누는 수 5에 0을 하나 더 붙인다","mis":"M6-2-u3-X01"}],"explanation":["36 ÷ 5는 7을 쓰고 1이 남아요.","0을 내려 10 ÷ 5 = 2를 이어서 써요.","몫의 소수점은 옮긴 자리에서 찍어 7.2예요."],"variant_rule":{"alt":[{"stem":"9.3 ÷ 1.5를 93 ÷ 15로 바꾸어 세로로 계산하니 몫이 자연수로 나누어떨어지지 않아요. 어떻게 계산해야 하나요?","options":[{"t":"93 뒤에 0을 내려 계속 나눈다","correct":true},{"t":"몫 6, 나머지 3으로 쓰고 멈춘다","mis":"M6-2-u3-X23"},{"t":"몫을 반올림해 6으로 쓴다","mis":"M6-2-u3-X11"},{"t":"나누는 수 15에 0을 하나 더 붙인다","mis":"M6-2-u3-X01"}],"explanation":["93 ÷ 15는 6을 쓰고 3이 남아요.","0을 내려 30 ÷ 15 = 2를 이어서 써요.","몫의 소수점은 옮긴 자리에서 찍어 6.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#7','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','세로셈에서 몫의 소수점은 어디에서 위로 올려 찍나요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":7,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"세로셈에서 몫의 소수점은 어디에서 위로 올려 찍나요?","options":[{"t":"옮긴 소수점의 위치","correct":true},{"t":"나누어지는 수의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"나누는 수의 원래 소수점 자리","mis":"M6-2-u3-X03"},{"t":"몫의 맨 뒤","mis":"M6-2-u3-X04"}],"explanation":["두 수의 소수점을 옮기면 자연수의 나눗셈처럼 계산해요.","몫은 옮긴 나눗셈의 몫과 같아요.","그래서 몫의 소수점은 옮긴 소수점의 위치에서 올려 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#8','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'mc','auto','9.3 ÷ 1.5 ○ 6 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u3-X20','M6-2-u3-X23']::text[],true,'{"seq":8,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"9.3 ÷ 1.5 ○ 6 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M6-2-u3-X20"},{"t":"=","mis":"M6-2-u3-X23"}],"explanation":["9.3 ÷ 1.5 = 6.2예요.","6.2와 6을 견주어요.","그래서 9.3 ÷ 1.5 > 6이에요."],"variant_rule":{"alt":[{"stem":"7 ○ 28.8 ÷ 4.5 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M6-2-u3-X20"},{"t":"=","mis":"M6-2-u3-X23"}],"explanation":["28.8 ÷ 4.5 = 6.4예요.","7과 6.4를 견주어요.","그래서 7 > 28.8 ÷ 4.5예요."]},{"stem":"9.8 ÷ 0.7 ○ 6.4 ÷ 0.4 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M6-2-u3-X20"},{"t":"=","mis":"M6-2-u3-X23"}],"explanation":["9.8 ÷ 0.7 = 14 · 6.4 ÷ 0.4 = 16이에요.","14와 16을 견주어요.","그래서 9.8 ÷ 0.7 < 6.4 ÷ 0.4예요."]},{"stem":"20.8 ÷ 2.6 ○ 25.5 ÷ 3.4 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M6-2-u3-X20"},{"t":"=","mis":"M6-2-u3-X23"}],"explanation":["20.8 ÷ 2.6 = 8 · 25.5 ÷ 3.4 = 7.5예요.","8과 7.5를 견주어요.","그래서 20.8 ÷ 2.6 > 25.5 ÷ 3.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#9','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-2-u3-C3","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"4.9 ÷ 0.7","r":"7"},{"l":"3.6 ÷ 0.5","r":"7.2"},{"l":"48.3 ÷ 2.3","r":"21"}],"mis":"M6-2-u3-X03","explanation":["4.9 ÷ 0.7 = 49 ÷ 7 = 7이에요.","3.6 ÷ 0.5 = 36 ÷ 5 = 7.2예요.","48.3 ÷ 2.3 = 483 ÷ 23 = 21이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"7.2 ÷ 0.6","r":"12"},{"l":"9.3 ÷ 1.5","r":"6.2"},{"l":"28.8 ÷ 4.5","r":"6.4"}],"explanation":["7.2 ÷ 0.6 = 72 ÷ 6 = 12예요.","9.3 ÷ 1.5 = 93 ÷ 15 = 6.2예요.","28.8 ÷ 4.5 = 288 ÷ 45 = 6.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_basic#10','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_basic','lesson_basic','M6-2-u3-C3',3,'mc','auto','두 친구가 주스를 컵에 나누어 담았어요. 주스를 담은 컵의 수가 더 많은 친구는 누구인가요?',ARRAY['M6-2-u3-X20']::text[],false,'{"seq":10,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"두 친구가 주스를 컵에 나누어 담았어요. 주스를 담은 컵의 수가 더 많은 친구는 누구인가요?","options":[{"t":"수지","correct":true},{"t":"은우","mis":"M6-2-u3-X20"},{"t":"두 친구가 같아요","mis":"M6-2-u3-X20"}],"explanation":["수지: 2.7 ÷ 0.3 = 27 ÷ 3 = 9(컵)이에요.","은우: 2.8 ÷ 0.4 = 28 ÷ 4 = 7(컵)이에요.","9 > 7 — 수지가 더 많아요."],"asset":{"type":"speech","turns":[{"who":"수지","text":"주스 2.7 L를 컵 한 개에 0.3 L씩 담았어요."},{"who":"은우","text":"주스 2.8 L를 컵 한 개에 0.4 L씩 담았어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#1','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',2,'mc','auto','2.5, 0.8, 3.6 가운데 가장 큰 수를 가장 작은 수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u3-X04','M6-2-u3-X03','M6-2-u3-X19']::text[],true,'{"seq":1,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"2.5, 0.8, 3.6 가운데 가장 큰 수를 가장 작은 수로 나눈 몫은 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"45","mis":"M6-2-u3-X04"},{"t":"0.45","mis":"M6-2-u3-X03"},{"t":"3.125","mis":"M6-2-u3-X19"}],"explanation":["가장 큰 수는 3.6, 가장 작은 수는 0.8이에요.","3.6 ÷ 0.8 = 36 ÷ 8이에요.","36 ÷ 8 = 4.5예요."],"variant_rule":{"alt":[{"stem":"4.2와 0.06 가운데 큰 수를 작은 수로 나눈 몫은 얼마인가요?","options":[{"t":"70","correct":true},{"t":"7","mis":"M6-2-u3-X07"},{"t":"0.7","mis":"M6-2-u3-X03"},{"t":"700","mis":"M6-2-u3-X04"}],"explanation":["큰 수는 4.2, 작은 수는 0.06이에요.","0.06이 자연수가 되도록 두 칸씩 옮기면 420 ÷ 6이에요 — 빈 자리는 0으로.","420 ÷ 6 = 70이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#2','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',2,'sa','auto','9.8 ÷ 0.7의 몫은 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C3","difficulty":2,"kind":"sa","stem":"9.8 ÷ 0.7의 몫은 얼마인가요?","answer":["14"],"explanation":["나누는 수 0.7이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","9.8 ÷ 0.7은 98 ÷ 7이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","98 ÷ 7 = 14예요."],"variant_rule":{"alt":[{"stem":"6.4 ÷ 0.4의 몫은 얼마인가요?","answer":["16"],"explanation":["나누는 수 0.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","6.4 ÷ 0.4는 64 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","64 ÷ 4 = 16이에요."]},{"stem":"7.7 ÷ 1.1의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 1.1이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","7.7 ÷ 1.1은 77 ÷ 11이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","77 ÷ 11 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#3','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'mc','auto','3.6 ÷ 0.5의 몫을 0.72라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02','M6-2-u3-X04']::text[],true,'{"seq":3,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"3.6 ÷ 0.5의 몫을 0.72라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["3.6 ÷ 0.5 = 36 ÷ 5 = 7.2예요.","0.72는 7.2보다 10배 작은 수예요.","몫의 소수점을 옮기기 전 자리에서 찍으면 이렇게 돼요."],"variant_rule":{"alt":[{"stem":"28.8 ÷ 4.5의 몫을 0.64라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수를 자연수로 바꾸지 않아서","mis":"M6-2-u3-X01"},{"t":"두 수의 소수점을 서로 다르게 옮겨서","mis":"M6-2-u3-X02"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["28.8 ÷ 4.5 = 288 ÷ 45 = 6.4예요.","0.64는 6.4보다 10배 작은 수예요.","몫의 소수점을 옮기기 전 자리에서 찍으면 이렇게 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#4','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'mc','auto','계산하기 전에 몫을 어림해요. 9.3 ÷ 1.5의 몫과 가장 가까운 수는 어느 것인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":4,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"계산하기 전에 몫을 어림해요. 9.3 ÷ 1.5의 몫과 가장 가까운 수는 어느 것인가요?","options":[{"t":"6","correct":true},{"t":"0.6","mis":"M6-2-u3-X03"},{"t":"60","mis":"M6-2-u3-X04"},{"t":"0.06","mis":"M6-2-u3-X03"}],"explanation":["1.5를 여섯 번 더하면 9예요.","9.3은 9보다 조금 크니 몫은 6쯤이에요.","계산하면 6.2 — 어림과 견주면 소수점 자리 실수를 잡을 수 있어요."],"variant_rule":{"alt":[{"stem":"계산하기 전에 몫을 어림해요. 24.5 ÷ 3.5의 몫과 가장 가까운 수는 어느 것인가요?","options":[{"t":"7","correct":true},{"t":"0.7","mis":"M6-2-u3-X03"},{"t":"70","mis":"M6-2-u3-X04"},{"t":"0.07","mis":"M6-2-u3-X03"}],"explanation":["3.5를 일곱 번 더하면 24.5예요.","그래서 몫은 7쯤이에요.","계산하면 7 — 어림과 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#5','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u3-X20']::text[],true,'{"seq":5,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"3.6 ÷ 0.5","correct":true},{"t":"9.3 ÷ 1.5","mis":"M6-2-u3-X20"},{"t":"28.8 ÷ 4.5","mis":"M6-2-u3-X20"},{"t":"4.9 ÷ 0.7","mis":"M6-2-u3-X20"}],"explanation":["3.6 ÷ 0.5 = 7.2, 9.3 ÷ 1.5 = 6.2예요.","28.8 ÷ 4.5 = 6.4, 4.9 ÷ 0.7 = 7이에요.","그래서 3.6 ÷ 0.5가 가장 커요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"6.4 ÷ 0.4","correct":true},{"t":"9.8 ÷ 0.7","mis":"M6-2-u3-X20"},{"t":"20.8 ÷ 2.6","mis":"M6-2-u3-X20"},{"t":"25.5 ÷ 3.4","mis":"M6-2-u3-X20"}],"explanation":["6.4 ÷ 0.4 = 16, 9.8 ÷ 0.7 = 14예요.","20.8 ÷ 2.6 = 8, 25.5 ÷ 3.4 = 7.5예요.","그래서 6.4 ÷ 0.4가 가장 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#6','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'error','auto','3.6 ÷ 0.5를 세로로 계산하는 과정을 늘어놓았어요. 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X19']::text[],true,'{"seq":6,"concept":"M6-2-u3-C3","difficulty":3,"kind":"error","stem":"3.6 ÷ 0.5를 세로로 계산하는 과정을 늘어놓았어요. 잘못된 것은 어느 것인가요?","options":[{"t":"0.5만 5로 바꾸고 3.6은 그대로 둔다","correct":true,"mis_target":"M6-2-u3-X01"},{"t":"두 수의 소수점을 오른쪽으로 한 칸씩 옮긴다","mis":"M6-2-u3-X19"},{"t":"나누어떨어지지 않으면 0을 내려 계산한다","mis":"M6-2-u3-X19"},{"t":"몫의 소수점은 옮긴 자리에서 올려 찍는다","mis":"M6-2-u3-X19"}],"explanation":["0.5만 옮기면 3.6 ÷ 5 — 처음 식과 다른 나눗셈이에요.","두 수의 소수점은 같은 칸수만큼 옮겨요.","바르게 하면 36 ÷ 5 = 7.2예요."],"variant_rule":{"alt":[{"stem":"24.5 ÷ 3.5를 세로로 계산하는 과정을 늘어놓았어요. 잘못된 것은 어느 것인가요?","options":[{"t":"3.5만 35로 바꾸고 24.5는 그대로 둔다","correct":true,"mis_target":"M6-2-u3-X01"},{"t":"두 수의 소수점을 오른쪽으로 한 칸씩 옮긴다","mis":"M6-2-u3-X19"},{"t":"245 ÷ 35를 자연수의 나눗셈처럼 계산한다","mis":"M6-2-u3-X19"},{"t":"몫의 소수점은 옮긴 자리에서 올려 찍는다","mis":"M6-2-u3-X19"}],"explanation":["3.5만 옮기면 24.5 ÷ 35 — 처음 식과 다른 나눗셈이에요.","두 수의 소수점은 같은 칸수만큼 옮겨요.","바르게 하면 245 ÷ 35 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#7','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',3,'mc','auto','㉠ 20.8 ÷ 2.6과 ㉡ 13.3 ÷ 1.9 가운데 몫이 더 큰 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X20']::text[],true,'{"seq":7,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"㉠ 20.8 ÷ 2.6과 ㉡ 13.3 ÷ 1.9 가운데 몫이 더 큰 나눗셈은 어느 것인가요?","options":[{"t":"㉠ 20.8 ÷ 2.6","correct":true},{"t":"㉡ 13.3 ÷ 1.9","mis":"M6-2-u3-X20"},{"t":"두 몫이 같아요","mis":"M6-2-u3-X20"}],"explanation":["㉠ 20.8 ÷ 2.6 = 208 ÷ 26 = 8이에요.","㉡ 13.3 ÷ 1.9 = 133 ÷ 19 = 7이에요.","8 > 7 — ㉠이 더 커요."],"variant_rule":{"alt":[{"stem":"㉠ 6.8 ÷ 0.4와 ㉡ 11.2 ÷ 0.8 가운데 몫이 더 큰 나눗셈은 어느 것인가요?","options":[{"t":"㉠ 6.8 ÷ 0.4","correct":true},{"t":"㉡ 11.2 ÷ 0.8","mis":"M6-2-u3-X20"},{"t":"두 몫이 같아요","mis":"M6-2-u3-X20"}],"explanation":["㉠ 6.8 ÷ 0.4 = 68 ÷ 4 = 17이에요.","㉡ 11.2 ÷ 0.8 = 112 ÷ 8 = 14예요.","17 > 14 — ㉠이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#8','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',4,'mc','auto','□ ÷ 0.5 = 7.2예요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X17']::text[],true,'{"seq":8,"concept":"M6-2-u3-C3","difficulty":4,"kind":"mc","stem":"□ ÷ 0.5 = 7.2예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"3.6","correct":true},{"t":"0.36","mis":"M6-2-u3-X03"},{"t":"36","mis":"M6-2-u3-X04"},{"t":"14.4","mis":"M6-2-u3-X17"}],"explanation":["□ ÷ 0.5 = 7.2이면 □ = 7.2 × 0.5예요.","7.2 × 0.5 = 3.6이에요.","3.6 ÷ 0.5 = 36 ÷ 5 = 7.2로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 3.5 = 7이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"24.5","correct":true},{"t":"2.45","mis":"M6-2-u3-X03"},{"t":"245","mis":"M6-2-u3-X04"},{"t":"0.5","mis":"M6-2-u3-X17"}],"explanation":["□ = 7 × 3.5예요.","7 × 3.5 = 24.5예요.","24.5 ÷ 3.5 = 245 ÷ 35 = 7로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#9','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',4,'essay','teacher','3.6 ÷ 0.5를 세로로 계산하는 과정을 소수점 옮기기, 0을 내려 계산하기, 몫의 소수점 찍기를 넣어 차례대로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C3","difficulty":4,"kind":"essay","stem":"3.6 ÷ 0.5를 세로로 계산하는 과정을 소수점 옮기기, 0을 내려 계산하기, 몫의 소수점 찍기를 넣어 차례대로 설명해 보세요.","answer_guide":{"answer":"예: 나누는 수 0.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨 36 ÷ 5로 만든다. 몫이 자연수로 나누어떨어지지 않으므로 0을 내려 계산하고, 몫의 소수점은 옮긴 소수점의 위치에서 올려 찍어 7.2이다.","scoring_points":["두 수의 소수점을 똑같이 한 칸 옮겼는가","0을 내려 계산했는가","몫의 소수점을 옮긴 자리에서 찍어 7.2를 구했는가"]},"explanation":["두 수를 한 칸씩 옮기면 36 ÷ 5예요.","나누어떨어지지 않으면 0을 내려 계산해요.","몫의 소수점은 옮긴 자리에서 — 7.2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L03_challenge#10','math',6,2,'u3','L03','tb_g6_2_math_u3_L03_challenge','lesson_challenge','M6-2-u3-C3',4,'essay','teacher','수지는 주스 2.7 L를 컵 한 개에 0.3 L씩, 은우는 주스 2.8 L를 컵 한 개에 0.4 L씩 담았어요. 주스를 담은 컵의 수가 더 많은 친구는 누구인지 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C3","difficulty":4,"kind":"essay","stem":"수지는 주스 2.7 L를 컵 한 개에 0.3 L씩, 은우는 주스 2.8 L를 컵 한 개에 0.4 L씩 담았어요. 주스를 담은 컵의 수가 더 많은 친구는 누구인지 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 수지는 2.7 ÷ 0.3 = 9이므로 컵 9개에 담았고, 은우는 2.8 ÷ 0.4 = 7이므로 컵 7개에 담았다. 9 > 7이므로 컵의 수가 더 많은 친구는 수지이다.","scoring_points":["2.7 ÷ 0.3 = 9를 구했는가","2.8 ÷ 0.4 = 7을 구했는가","두 수를 견주어 수지라고 답했는가"]},"explanation":["수지: 2.7 ÷ 0.3 = 9예요.","은우: 2.8 ÷ 0.4 = 7이에요.","9 > 7 — 수지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#1','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',1,'sa','auto','2.24 ÷ 0.08을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"2.24 ÷ 0.08을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.08이 정해요.","0.08이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"0.56 ÷ 0.16을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.16이 정해요.","0.16이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."]},{"stem":"6.54 ÷ 0.06을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.06이 정해요.","0.06이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#2','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',1,'sa','auto','엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 8.24 m는 824 cm, 4.12 m는 412 cm예요. 엄마 범고래의 몸길이는 아기 범고래의 몸길이의 몇 배인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 8.24 m는 824 cm, 4.12 m는 412 cm예요. 엄마 범고래의 몸길이는 아기 범고래의 몸길이의 몇 배인가요?","answer":["2"],"explanation":["몇 배인지는 8.24 ÷ 4.12로 구해요.","m를 cm로 바꾸면 824 ÷ 412예요.","412를 두 번 더하면 824 — 2배예요."],"variant_rule":{"alt":[{"stem":"우유 3.42 L를 한 명에게 0.38 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람은 몇 명인가요?","answer":["9"],"explanation":["나누는 수 0.38이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","3.42 ÷ 0.38은 342 ÷ 38이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","342 ÷ 38 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#3','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',1,'mc','auto','2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":3,"concept":"M6-2-u3-C4","difficulty":1,"kind":"mc","stem":"2.24 ÷ 0.08을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨224/100⟩ ÷ ⟨8/100⟩","correct":true},{"t":"⟨224/100⟩ ÷ 0.08","mis":"M6-2-u3-X06"},{"t":"⟨224/100⟩ ÷ ⟨0/10⟩","mis":"M6-2-u3-X05"},{"t":"2.24 ÷ ⟨8/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.24는 ⟨224/100⟩, 0.08은 ⟨8/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨224/100⟩ ÷ ⟨8/100⟩이에요."],"variant_rule":{"alt":[{"stem":"1.68 ÷ 0.07을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨168/100⟩ ÷ ⟨7/100⟩","correct":true},{"t":"⟨168/100⟩ ÷ 0.07","mis":"M6-2-u3-X06"},{"t":"⟨168/100⟩ ÷ ⟨0/10⟩","mis":"M6-2-u3-X05"},{"t":"1.68 ÷ ⟨7/100⟩","mis":"M6-2-u3-X06"}],"explanation":["1.68은 ⟨168/100⟩, 0.07은 ⟨7/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨168/100⟩ ÷ ⟨7/100⟩이에요."]},{"stem":"0.32 ÷ 0.04를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨32/100⟩ ÷ ⟨4/100⟩","correct":true},{"t":"⟨32/100⟩ ÷ 0.04","mis":"M6-2-u3-X06"},{"t":"⟨32/100⟩ ÷ ⟨0/10⟩","mis":"M6-2-u3-X05"},{"t":"0.32 ÷ ⟨4/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.32는 ⟨32/100⟩, 0.04는 ⟨4/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨32/100⟩ ÷ ⟨4/100⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#4','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',1,'sa','auto','2.24 ÷ 0.08을 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 224 ÷ 8로 바꾸었어요. 2.24 ÷ 0.08의 몫은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"2.24 ÷ 0.08을 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 224 ÷ 8로 바꾸었어요. 2.24 ÷ 0.08의 몫은 얼마인가요?","answer":["28"],"explanation":["나누는 수 0.08이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","2.24 ÷ 0.08은 224 ÷ 8이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","224 ÷ 8 = 28이에요."],"asset":{"type":"ldiv","a":224,"b":8,"hide":["q"]},"variant_rule":{"alt":[{"stem":"9.54 ÷ 0.18을 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 954 ÷ 18로 바꾸었어요. 9.54 ÷ 0.18의 몫은 얼마인가요?","answer":["53"],"explanation":["나누는 수 0.18이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","9.54 ÷ 0.18은 954 ÷ 18이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","954 ÷ 18 = 53이에요."],"asset":{"type":"ldiv","a":954,"b":18,"hide":["q"]}},{"stem":"6.54 ÷ 0.06을 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 654 ÷ 6으로 바꾸었어요. 6.54 ÷ 0.06의 몫은 얼마인가요?","answer":["109"],"explanation":["나누는 수 0.06이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","6.54 ÷ 0.06은 654 ÷ 6이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","654 ÷ 6 = 109예요."],"asset":{"type":"ldiv","a":654,"b":6,"hide":["q"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#5','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'mc','auto','0.56 ÷ 0.16의 몫은 얼마인가요?',ARRAY['M6-2-u3-X23','M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":5,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"0.56 ÷ 0.16의 몫은 얼마인가요?","options":[{"t":"3.5","correct":true},{"t":"3 … 8","mis":"M6-2-u3-X23"},{"t":"0.35","mis":"M6-2-u3-X03"},{"t":"35","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.16이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.56 ÷ 0.16은 56 ÷ 16이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","56 ÷ 16 = 3.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."],"variant_rule":{"alt":[{"stem":"0.77 ÷ 0.14의 몫은 얼마인가요?","options":[{"t":"5.5","correct":true},{"t":"5 … 7","mis":"M6-2-u3-X23"},{"t":"0.55","mis":"M6-2-u3-X03"},{"t":"55","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.14가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.77 ÷ 0.14는 77 ÷ 14가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","77 ÷ 14 = 5.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]},{"stem":"4.94 ÷ 0.76의 몫은 얼마인가요?","options":[{"t":"6.5","correct":true},{"t":"6 … 38","mis":"M6-2-u3-X23"},{"t":"0.65","mis":"M6-2-u3-X03"},{"t":"65","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.76이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","4.94 ÷ 0.76은 494 ÷ 76이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","494 ÷ 76 = 6.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#6','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'mc','auto','소수의 나눗셈에서 소수점을 옮기는 칸수는 무엇이 정하나요?',ARRAY['M6-2-u3-X02']::text[],true,'{"seq":6,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"소수의 나눗셈에서 소수점을 옮기는 칸수는 무엇이 정하나요?","options":[{"t":"나누는 수의 소수 자리 수","correct":true},{"t":"나누어지는 수의 소수 자리 수","mis":"M6-2-u3-X02"},{"t":"몫의 자리 수","mis":"M6-2-u3-X02"},{"t":"언제나 한 칸","mis":"M6-2-u3-X02"}],"explanation":["나누는 수가 자연수가 되어야 자연수의 나눗셈처럼 계산할 수 있어요.","0.08이 자연수가 되려면 두 칸을 옮겨야 해요.","그래서 칸수는 나누는 수의 소수 자리 수가 정해요."],"variant_rule":{"alt":[{"stem":"2.24 ÷ 0.08에서 두 수의 소수점을 두 칸씩 옮기는 까닭은 무엇인가요?","options":[{"t":"0.08이 자연수가 되려면 두 칸 옮겨야 해서","correct":true},{"t":"2.24가 소수 두 자리 수라서","mis":"M6-2-u3-X02"},{"t":"몫이 두 자리 수라서","mis":"M6-2-u3-X02"},{"t":"언제나 두 칸씩 옮기기 때문에","mis":"M6-2-u3-X02"}],"explanation":["옮기는 칸수는 나누는 수가 정해요.","0.08은 두 칸 옮겨야 8이 돼요.","그래서 2.24도 두 칸 옮겨 224 ÷ 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#7','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'match','auto','계산 결과를 찾아 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u3-C4","difficulty":2,"kind":"match","stem":"계산 결과를 찾아 이으세요.","pairs":[{"l":"0.77 ÷ 0.14","r":"5.5"},{"l":"0.54 ÷ 0.05","r":"10.8"},{"l":"4.94 ÷ 0.76","r":"6.5"}],"mis":"M6-2-u3-X03","explanation":["0.77 ÷ 0.14 = 77 ÷ 14 = 5.5예요.","0.54 ÷ 0.05 = 54 ÷ 5 = 10.8이에요.","4.94 ÷ 0.76 = 494 ÷ 76 = 6.5예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 계산 결과를 찾아 이으세요.","pairs":[{"l":"0.72 ÷ 0.09","r":"8"},{"l":"3.36 ÷ 0.28","r":"12"},{"l":"0.78 ÷ 0.12","r":"6.5"}],"explanation":["0.72 ÷ 0.09 = 72 ÷ 9 = 8이에요.","3.36 ÷ 0.28 = 336 ÷ 28 = 12예요.","0.78 ÷ 0.12 = 78 ÷ 12 = 6.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#8','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'sa','auto','8.47 ÷ 1.21의 몫은 얼마인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u3-C4","difficulty":2,"kind":"sa","stem":"8.47 ÷ 1.21의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 1.21이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","8.47 ÷ 1.21은 847 ÷ 121이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","847 ÷ 121 = 7이에요."],"variant_rule":{"alt":[{"stem":"1.68 ÷ 0.07의 몫은 얼마인가요?","answer":["24"],"explanation":["나누는 수 0.07이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","1.68 ÷ 0.07은 168 ÷ 7이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","168 ÷ 7 = 24예요."]},{"stem":"3.36 ÷ 0.28의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.28이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","3.36 ÷ 0.28은 336 ÷ 28이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","336 ÷ 28 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#9','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',2,'sa','auto','상자 한 개를 포장하는 데 끈 0.31 m가 필요해요. 끈 4.34 m를 사용하여 포장할 수 있는 상자는 몇 개인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u3-C4","difficulty":2,"kind":"sa","stem":"상자 한 개를 포장하는 데 끈 0.31 m가 필요해요. 끈 4.34 m를 사용하여 포장할 수 있는 상자는 몇 개인가요?","answer":["14"],"explanation":["나누는 수 0.31이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","4.34 ÷ 0.31은 434 ÷ 31이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","434 ÷ 31 = 14예요."],"variant_rule":{"alt":[{"stem":"넓이가 4.62 cm²인 직사각형의 가로가 0.66 cm일 때 세로는 몇 cm인가요?","answer":["7"],"explanation":["나누는 수 0.66이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","4.62 ÷ 0.66은 462 ÷ 66이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","462 ÷ 66 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_basic#10','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_basic','lesson_basic','M6-2-u3-C4',3,'mc','auto','양치하는 동안 소비하는 물의 양을 조사했더니 양치 컵을 사용하지 않을 때 5.89 L, 양치 컵을 사용할 때 0.62 L였어요. 양치 컵을 사용하지 않을 때 소비하는 물의 양은 사용할 때의 몇 배인가요?',ARRAY['M6-2-u3-X04','M6-2-u3-X03','M6-2-u3-X16']::text[],false,'{"seq":10,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"양치하는 동안 소비하는 물의 양을 조사했더니 양치 컵을 사용하지 않을 때 5.89 L, 양치 컵을 사용할 때 0.62 L였어요. 양치 컵을 사용하지 않을 때 소비하는 물의 양은 사용할 때의 몇 배인가요?","options":[{"t":"9.5배","correct":true},{"t":"95배","mis":"M6-2-u3-X04"},{"t":"0.95배","mis":"M6-2-u3-X03"},{"t":"5.27배","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 5.89 ÷ 0.62로 구해요.","두 칸씩 옮기면 589 ÷ 62예요.","589 ÷ 62 = 9.5 — 9.5배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#1','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',2,'mc','auto','0.54 ÷ 0.05의 몫은 얼마인가요?',ARRAY['M6-2-u3-X23','M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":1,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"0.54 ÷ 0.05의 몫은 얼마인가요?","options":[{"t":"10.8","correct":true},{"t":"10 … 4","mis":"M6-2-u3-X23"},{"t":"1.08","mis":"M6-2-u3-X03"},{"t":"108","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.05가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.54 ÷ 0.05는 54 ÷ 5가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","54 ÷ 5 = 10.8 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."],"variant_rule":{"alt":[{"stem":"0.78 ÷ 0.12의 몫은 얼마인가요?","options":[{"t":"6.5","correct":true},{"t":"6 … 6","mis":"M6-2-u3-X23"},{"t":"0.65","mis":"M6-2-u3-X03"},{"t":"65","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.12가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.78 ÷ 0.12는 78 ÷ 12가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","78 ÷ 12 = 6.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]},{"stem":"5.89 ÷ 0.62의 몫은 얼마인가요?","options":[{"t":"9.5","correct":true},{"t":"9 … 31","mis":"M6-2-u3-X23"},{"t":"0.95","mis":"M6-2-u3-X03"},{"t":"95","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.62가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","5.89 ÷ 0.62는 589 ÷ 62가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","589 ÷ 62 = 9.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#2','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',2,'sa','auto','우유 3.42 L를 한 명에게 0.38 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람은 몇 명인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C4","difficulty":2,"kind":"sa","stem":"우유 3.42 L를 한 명에게 0.38 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람은 몇 명인가요?","answer":["9"],"explanation":["나누는 수 0.38이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","3.42 ÷ 0.38은 342 ÷ 38이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","342 ÷ 38 = 9예요."],"variant_rule":{"alt":[{"stem":"넓이가 4.62 cm²인 직사각형의 가로가 0.66 cm일 때 세로는 몇 cm인가요?","answer":["7"],"explanation":["나누는 수 0.66이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","4.62 ÷ 0.66은 462 ÷ 66이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","462 ÷ 66 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#3','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'mc','auto','0.56 ÷ 0.16의 몫을 0.35라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X02','M6-2-u3-X01','M6-2-u3-X04']::text[],true,'{"seq":3,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"0.56 ÷ 0.16의 몫을 0.35라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 자리에서 찍어서","correct":true},{"t":"두 수를 한 칸씩만 옮겨서","mis":"M6-2-u3-X02"},{"t":"나누는 수만 옮겨서","mis":"M6-2-u3-X01"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["0.56 ÷ 0.16 = 56 ÷ 16 = 3.5예요.","0.35는 3.5보다 10배 작아요.","몫의 소수점은 옮긴 자리에서 찍어야 해요."],"variant_rule":{"alt":[{"stem":"0.77 ÷ 0.14의 몫을 55라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 빠뜨려서","correct":true},{"t":"두 수를 한 칸씩만 옮겨서","mis":"M6-2-u3-X02"},{"t":"나누는 수만 옮겨서","mis":"M6-2-u3-X01"},{"t":"몫의 소수점을 옮기기 전 자리에서 찍어서","mis":"M6-2-u3-X03"}],"explanation":["0.77 ÷ 0.14 = 77 ÷ 14 = 5.5예요.","55는 5.5보다 10배 커요.","몫의 소수점을 빠뜨리면 이렇게 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#4','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'mc','auto','몫이 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":4,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"몫이 다른 하나는 어느 것인가요?","options":[{"t":"2.24 ÷ 0.8","correct":true},{"t":"2.24 ÷ 0.08","mis":"M6-2-u3-X19"},{"t":"224 ÷ 8","mis":"M6-2-u3-X19"},{"t":"22.4 ÷ 0.8","mis":"M6-2-u3-X19"}],"explanation":["2.24 ÷ 0.08, 224 ÷ 8, 22.4 ÷ 0.8은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 28이에요.","2.24 ÷ 0.8은 나누어지는 수만 바뀐 셈이라 몫이 2.8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 몫이 다른 하나는 어느 것인가요?","options":[{"t":"0.56 ÷ 1.6","correct":true},{"t":"0.56 ÷ 0.16","mis":"M6-2-u3-X19"},{"t":"56 ÷ 16","mis":"M6-2-u3-X19"},{"t":"5.6 ÷ 1.6","mis":"M6-2-u3-X19"}],"explanation":["0.56 ÷ 0.16, 56 ÷ 16, 5.6 ÷ 1.6은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 3.5예요.","0.56 ÷ 1.6은 몫이 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#5','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'mc','auto','0.77 ÷ 0.14를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],true,'{"seq":5,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"0.77 ÷ 0.14를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨77/100⟩ ÷ ⟨14/100⟩","correct":true},{"t":"⟨77/100⟩ ÷ 0.14","mis":"M6-2-u3-X06"},{"t":"⟨77/100⟩ ÷ ⟨1/10⟩","mis":"M6-2-u3-X05"},{"t":"0.77 ÷ ⟨14/100⟩","mis":"M6-2-u3-X06"}],"explanation":["0.77은 ⟨77/100⟩, 0.14는 ⟨14/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨77/100⟩ ÷ ⟨14/100⟩예요."],"variant_rule":{"alt":[{"stem":"6.54 ÷ 0.06을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨654/100⟩ ÷ ⟨6/100⟩","correct":true},{"t":"⟨654/100⟩ ÷ 0.06","mis":"M6-2-u3-X06"},{"t":"⟨654/100⟩ ÷ ⟨0/10⟩","mis":"M6-2-u3-X05"},{"t":"6.54 ÷ ⟨6/100⟩","mis":"M6-2-u3-X06"}],"explanation":["6.54는 ⟨654/100⟩, 0.06은 ⟨6/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨654/100⟩ ÷ ⟨6/100⟩이에요."]},{"stem":"3.36 ÷ 0.28을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨336/100⟩ ÷ ⟨28/100⟩","correct":true},{"t":"⟨336/100⟩ ÷ 0.28","mis":"M6-2-u3-X06"},{"t":"⟨336/100⟩ ÷ ⟨2/10⟩","mis":"M6-2-u3-X05"},{"t":"3.36 ÷ ⟨28/100⟩","mis":"M6-2-u3-X06"}],"explanation":["3.36은 ⟨336/100⟩, 0.28은 ⟨28/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨336/100⟩ ÷ ⟨28/100⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#6','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'mc','auto','6.54 ÷ 0.06의 몫은 얼마인가요?',ARRAY['M6-2-u3-X20','M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":6,"concept":"M6-2-u3-C4","difficulty":3,"kind":"mc","stem":"6.54 ÷ 0.06의 몫은 얼마인가요?","options":[{"t":"109","correct":true},{"t":"19","mis":"M6-2-u3-X20"},{"t":"10.9","mis":"M6-2-u3-X03"},{"t":"1090","mis":"M6-2-u3-X04"}],"explanation":["0.06이 자연수가 되려면 두 칸 옮겨요.","6.54도 두 칸 옮기면 654 ÷ 6이에요.","654 ÷ 6 = 109예요 — 가운데 자리의 0을 빠뜨리지 않아요."],"variant_rule":{"alt":[{"stem":"7.2 ÷ 0.08의 몫은 얼마인가요?","options":[{"t":"90","correct":true},{"t":"9","mis":"M6-2-u3-X07"},{"t":"0.9","mis":"M6-2-u3-X03"},{"t":"900","mis":"M6-2-u3-X04"}],"explanation":["0.08이 자연수가 되려면 두 칸 옮겨요.","7.2도 두 칸 옮기면 720 ÷ 8 — 빈 자리는 0으로 채워요.","720 ÷ 8 = 90이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#7','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',3,'sa','auto','0.32 ÷ 0.04 = ⟨32/100⟩ ÷ ⟨4/100⟩ = 32 ÷ 4예요. 0.32 ÷ 0.04의 몫은 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u3-C4","difficulty":3,"kind":"sa","stem":"0.32 ÷ 0.04 = ⟨32/100⟩ ÷ ⟨4/100⟩ = 32 ÷ 4예요. 0.32 ÷ 0.04의 몫은 얼마인가요?","answer":["8"],"explanation":["0.32 = ⟨32/100⟩, 0.04 = ⟨4/100⟩예요.","분모가 같으니 분자끼리 32 ÷ 4예요.","32 ÷ 4 = 8이에요."],"variant_rule":{"alt":[{"stem":"1.68 ÷ 0.07 = ⟨168/100⟩ ÷ ⟨7/100⟩ = 168 ÷ 7이에요. 1.68 ÷ 0.07의 몫은 얼마인가요?","answer":["24"],"explanation":["1.68 = ⟨168/100⟩, 0.07 = ⟨7/100⟩이에요.","분모가 같으니 분자끼리 168 ÷ 7이에요.","168 ÷ 7 = 24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#8','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',4,'mc','auto','□ ÷ 0.08 = 28이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X04','M6-2-u3-X03','M6-2-u3-X17']::text[],true,'{"seq":8,"concept":"M6-2-u3-C4","difficulty":4,"kind":"mc","stem":"□ ÷ 0.08 = 28이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"2.24","correct":true},{"t":"22.4","mis":"M6-2-u3-X04"},{"t":"0.224","mis":"M6-2-u3-X03"},{"t":"350","mis":"M6-2-u3-X17"}],"explanation":["□ = 28 × 0.08이에요.","28 × 0.08 = 2.24예요.","2.24 ÷ 0.08 = 224 ÷ 8 = 28로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ 0.38 = 9예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"3.42","correct":true},{"t":"34.2","mis":"M6-2-u3-X04"},{"t":"0.342","mis":"M6-2-u3-X03"},{"t":"23.68…","mis":"M6-2-u3-X17"}],"explanation":["□ = 9 × 0.38이에요.","9 × 0.38 = 3.42예요.","3.42 ÷ 0.38 = 342 ÷ 38 = 9로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#9','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',4,'essay','teacher','2.24 ÷ 0.08을 계산할 때 소수점을 두 칸씩 옮기는 까닭을 설명하고 몫을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C4","difficulty":4,"kind":"essay","stem":"2.24 ÷ 0.08을 계산할 때 소수점을 두 칸씩 옮기는 까닭을 설명하고 몫을 구해 보세요.","answer_guide":{"answer":"예: 소수점을 옮기는 칸수는 나누는 수가 정한다. 나누는 수 0.08이 자연수 8이 되려면 두 칸 옮겨야 하므로 2.24도 똑같이 두 칸 옮겨 224 ÷ 8 = 28이다.","scoring_points":["칸수는 나누는 수가 정함을 밝혔는가","0.08이 자연수가 되려면 두 칸임을 썼는가","224 ÷ 8 = 28을 구했는가"]},"explanation":["칸수는 나누는 수 0.08이 정해요.","0.08 → 8은 두 칸이에요.","224 ÷ 8 = 28이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L04_challenge#10','math',6,2,'u3','L04','tb_g6_2_math_u3_L04_challenge','lesson_challenge','M6-2-u3-C4',4,'essay','teacher','엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 몇 배인지 m를 cm로 바꾸는 방법과 분수로 바꾸는 방법 두 가지로 구하고, 두 방법의 같은 점을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C4","difficulty":4,"kind":"essay","stem":"엄마 범고래의 몸길이는 8.24 m, 아기 범고래의 몸길이는 4.12 m예요. 몇 배인지 m를 cm로 바꾸는 방법과 분수로 바꾸는 방법 두 가지로 구하고, 두 방법의 같은 점을 써 보세요.","answer_guide":{"answer":"예: 8.24 m = 824 cm, 4.12 m = 412 cm이므로 824 ÷ 412 = 2. 분수로 바꾸면 ⟨824/100⟩ ÷ ⟨412/100⟩ = 824 ÷ 412 = 2. 두 방법 모두 두 수를 똑같이 100배 하여 자연수의 나눗셈 824 ÷ 412로 바꾼다.","scoring_points":["단위를 바꾸어 824 ÷ 412 = 2를 구했는가","⟨824/100⟩ ÷ ⟨412/100⟩로 바꾸었는가","두 수를 똑같이 100배 한다는 같은 점을 썼는가"]},"explanation":["m → cm는 두 수를 100배 해요.","분수로 바꾸면 분모 100, 분자끼리 824 ÷ 412예요.","두 방법 모두 몫은 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#1','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',1,'sa','auto','주말농장에서 딴 방울토마토 5.4 kg을 한 상자에 0.45 kg씩 담아 친구들에게 나누어 주려고 해요. 상자는 몇 개 필요한가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"주말농장에서 딴 방울토마토 5.4 kg을 한 상자에 0.45 kg씩 담아 친구들에게 나누어 주려고 해요. 상자는 몇 개 필요한가요?","answer":["12"],"explanation":["나누는 수 0.45가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","5.4 ÷ 0.45는 540 ÷ 45가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","540 ÷ 45 = 12예요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.03의 몫은 얼마인가요?","answer":["280"],"explanation":["나누는 수 0.03이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","8.4 ÷ 0.03은 840 ÷ 3이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","840 ÷ 3 = 280이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#2','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',1,'sa','auto','5.4 ÷ 0.45를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"5.4 ÷ 0.45를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.45가 정해요.","0.45가 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.03을 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["2"],"explanation":["옮기는 칸수는 나누는 수 0.03이 정해요.","0.03이 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","그래서 두 수 모두 두 칸씩 옮겨요."]},{"stem":"3.08 ÷ 1.4를 세로로 계산할 때 두 수의 소수점을 오른쪽으로 몇 칸씩 옮겨야 하나요?","answer":["1"],"explanation":["옮기는 칸수는 나누는 수 1.4가 정해요.","1.4가 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","그래서 두 수 모두 한 칸씩 옮겨요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#3','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',1,'mc','auto','5.4 ÷ 0.45에서 5.4의 소수점을 오른쪽으로 두 칸 옮기면 얼마가 되나요?',ARRAY['M6-2-u3-X07','M6-2-u3-X02']::text[],true,'{"seq":3,"concept":"M6-2-u3-C5","difficulty":1,"kind":"mc","stem":"5.4 ÷ 0.45에서 5.4의 소수점을 오른쪽으로 두 칸 옮기면 얼마가 되나요?","options":[{"t":"540","correct":true},{"t":"54","mis":"M6-2-u3-X07"},{"t":"5.40","mis":"M6-2-u3-X07"},{"t":"5400","mis":"M6-2-u3-X02"}],"explanation":["5.4를 한 칸 옮기면 54예요.","한 칸 더 옮기면 빈 자리를 0으로 채워 540이에요.","소수 한 자리 수에 100배 하면 끝에 0을 적어요."],"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.03에서 8.4의 소수점을 오른쪽으로 두 칸 옮기면 얼마가 되나요?","options":[{"t":"840","correct":true},{"t":"84","mis":"M6-2-u3-X07"},{"t":"8.40","mis":"M6-2-u3-X07"},{"t":"8400","mis":"M6-2-u3-X02"}],"explanation":["8.4를 한 칸 옮기면 84예요.","한 칸 더 옮기면 빈 자리를 0으로 채워 840이에요.","소수 한 자리 수에 100배 하면 끝에 0을 적어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#4','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',1,'sa','auto','5.4 ÷ 0.45를 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 540 ÷ 45로 바꾸었어요. 5.4 ÷ 0.45의 몫은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"5.4 ÷ 0.45를 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 540 ÷ 45로 바꾸었어요. 5.4 ÷ 0.45의 몫은 얼마인가요?","answer":["12"],"explanation":["나누는 수 0.45가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","5.4 ÷ 0.45는 540 ÷ 45가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","540 ÷ 45 = 12예요."],"asset":{"type":"ldiv","a":540,"b":45,"hide":["q"]},"variant_rule":{"alt":[{"stem":"8.4 ÷ 0.03을 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 840 ÷ 3으로 바꾸었어요. 8.4 ÷ 0.03의 몫은 얼마인가요?","answer":["280"],"explanation":["나누는 수 0.03이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","8.4 ÷ 0.03은 840 ÷ 3이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","840 ÷ 3 = 280이에요."],"asset":{"type":"ldiv","a":840,"b":3,"hide":["q"]}},{"stem":"18.3 ÷ 0.3을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 183 ÷ 3으로 바꾸었어요. 18.3 ÷ 0.3의 몫은 얼마인가요?","answer":["61"],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","18.3 ÷ 0.3은 183 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","183 ÷ 3 = 61이에요."],"asset":{"type":"ldiv","a":183,"b":3,"hide":["q"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#5','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'mc','auto','방울토마토 5.4 kg을 한 상자에 0.45 kg씩 담아요. 0.45의 10배는 4.5예요. 필요한 상자는 몇 개쯤일까요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X20']::text[],false,'{"seq":5,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"방울토마토 5.4 kg을 한 상자에 0.45 kg씩 담아요. 0.45의 10배는 4.5예요. 필요한 상자는 몇 개쯤일까요?","options":[{"t":"10개쯤","correct":true},{"t":"1개쯤","mis":"M6-2-u3-X03"},{"t":"100개쯤","mis":"M6-2-u3-X04"},{"t":"5개쯤","mis":"M6-2-u3-X20"}],"explanation":["0.45 kg씩 10상자면 4.5 kg이에요.","5.4 kg은 4.5 kg보다 조금 많아요.","그래서 10개쯤 — 계산하면 12개로 어림과 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#6','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'mc','auto','8.64 ÷ 2.4를 (소수)÷(자연수)로 바꾸어 계산하려고 해요. 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":6,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"8.64 ÷ 2.4를 (소수)÷(자연수)로 바꾸어 계산하려고 해요. 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"86.4 ÷ 24","correct":true},{"t":"8.64 ÷ 24","mis":"M6-2-u3-X01"},{"t":"864 ÷ 24","mis":"M6-2-u3-X02"},{"t":"86.4 ÷ 240","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 2.4가 자연수가 되도록 두 수를 똑같이 10배 해요.","8.64의 10배는 86.4, 2.4의 10배는 24예요.","그래서 86.4 ÷ 24 — 몫은 3.6이에요."],"variant_rule":{"alt":[{"stem":"8.64 ÷ 2.4를 (자연수)÷(자연수)로 바꾸어 계산하려고 해요. 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"864 ÷ 240","correct":true},{"t":"864 ÷ 24","mis":"M6-2-u3-X02"},{"t":"8640 ÷ 24","mis":"M6-2-u3-X02"},{"t":"864 ÷ 2.4","mis":"M6-2-u3-X01"}],"explanation":["두 수가 모두 자연수가 되려면 똑같이 100배 해요.","8.64의 100배는 864, 2.4의 100배는 240이에요.","그래서 864 ÷ 240 — 몫은 3.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#7','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'mc','auto','8.64 ÷ 2.4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":7,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"8.64 ÷ 2.4의 몫은 얼마인가요?","options":[{"t":"3.6","correct":true},{"t":"0.36","mis":"M6-2-u3-X03"},{"t":"36","mis":"M6-2-u3-X04"},{"t":"0.036","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 2.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","8.64 ÷ 2.4는 86.4 ÷ 24가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","86.4 ÷ 24 = 3.6 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."],"variant_rule":{"alt":[{"stem":"3.08 ÷ 1.4의 몫은 얼마인가요?","options":[{"t":"2.2","correct":true},{"t":"0.22","mis":"M6-2-u3-X03"},{"t":"22","mis":"M6-2-u3-X04"},{"t":"0.022","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.08 ÷ 1.4는 30.8 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","30.8 ÷ 14 = 2.2 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]},{"stem":"2.55 ÷ 1.5의 몫은 얼마인가요?","options":[{"t":"1.7","correct":true},{"t":"0.17","mis":"M6-2-u3-X03"},{"t":"17","mis":"M6-2-u3-X04"},{"t":"0.017","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 1.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","2.55 ÷ 1.5는 25.5 ÷ 15가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","25.5 ÷ 15 = 1.7 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#8','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'ox','auto','8.64 ÷ 2.4는 864 ÷ 240으로 계산해도, 86.4 ÷ 24로 계산해도 몫이 같아요.',ARRAY['M6-2-u3-X02']::text[],false,'{"seq":8,"concept":"M6-2-u3-C5","difficulty":2,"kind":"ox","stem":"8.64 ÷ 2.4는 864 ÷ 240으로 계산해도, 86.4 ÷ 24로 계산해도 몫이 같아요.","answer":"O","reason_options":[{"t":"두 수에 똑같이 100을 곱하든 10을 곱하든 몫은 변하지 않기 때문에","correct":true},{"t":"소수점을 옮기는 방법이 다르면 몫도 달라지기 때문에","mis":"M6-2-u3-X02"}],"mis":"M6-2-u3-X02","explanation":["864 ÷ 240은 두 수를 100배, 86.4 ÷ 24는 10배 한 식이에요.","두 수에 같은 수를 곱하면 몫은 그대로예요.","두 방법 모두 몫은 3.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#9','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',2,'sa','auto','4.8 ÷ 0.08을 계산하면 몫은 얼마인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u3-C5","difficulty":2,"kind":"sa","stem":"4.8 ÷ 0.08을 계산하면 몫은 얼마인가요?","answer":["60"],"explanation":["나누는 수 0.08이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","4.8 ÷ 0.08은 480 ÷ 8이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","480 ÷ 8 = 60이에요."],"variant_rule":{"alt":[{"stem":"4.25 ÷ 0.05를 계산하면 몫은 얼마인가요?","answer":["85"],"explanation":["나누는 수 0.05가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","4.25 ÷ 0.05는 425 ÷ 5가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","425 ÷ 5 = 85예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_basic#10','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_basic','lesson_basic','M6-2-u3-C5',3,'mc','auto','두 친구가 3.51 ÷ 0.9의 몫을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u3-X19','M6-2-u3-X01']::text[],false,'{"seq":10,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"두 친구가 3.51 ÷ 0.9의 몫을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"혜리","correct":true},{"t":"선재","mis":"M6-2-u3-X19"},{"t":"두 친구 모두","mis":"M6-2-u3-X01"}],"explanation":["3.51 ÷ 0.9의 두 수에 똑같이 10을 곱하면 35.1 ÷ 9예요.","351 ÷ 9는 3.51만 100배, 0.9는 10배 한 식이라 몫이 달라요.","그래서 잘못 말한 친구는 혜리예요(바른 식은 35.1 ÷ 9, 351 ÷ 90)."],"asset":{"type":"speech","turns":[{"who":"혜리","text":"3.51 ÷ 0.9의 몫은 351 ÷ 9의 몫과 같아요."},{"who":"선재","text":"3.51 ÷ 0.9의 몫은 35.1 ÷ 9의 몫과 같아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#1','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',2,'mc','auto','2.55 ÷ 0.3의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],true,'{"seq":1,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"2.55 ÷ 0.3의 몫은 얼마인가요?","options":[{"t":"8.5","correct":true},{"t":"0.85","mis":"M6-2-u3-X03"},{"t":"85","mis":"M6-2-u3-X04"},{"t":"0.085","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","2.55 ÷ 0.3은 25.5 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","25.5 ÷ 3 = 8.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."],"variant_rule":{"alt":[{"stem":"7.36 ÷ 3.2의 몫은 얼마인가요?","options":[{"t":"2.3","correct":true},{"t":"0.23","mis":"M6-2-u3-X03"},{"t":"23","mis":"M6-2-u3-X04"},{"t":"0.023","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 3.2가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","7.36 ÷ 3.2는 73.6 ÷ 32가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","73.6 ÷ 32 = 2.3 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]},{"stem":"3.51 ÷ 0.9의 몫은 얼마인가요?","options":[{"t":"3.9","correct":true},{"t":"0.39","mis":"M6-2-u3-X03"},{"t":"39","mis":"M6-2-u3-X04"},{"t":"0.039","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.9가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.51 ÷ 0.9는 35.1 ÷ 9가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","35.1 ÷ 9 = 3.9 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#2','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',2,'mc','auto','빨간색 테이프의 길이는 7.36 m, 파란색 테이프의 길이는 3.2 m예요. 빨간색 테이프의 길이는 파란색 테이프의 길이의 몇 배인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],false,'{"seq":2,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"빨간색 테이프의 길이는 7.36 m, 파란색 테이프의 길이는 3.2 m예요. 빨간색 테이프의 길이는 파란색 테이프의 길이의 몇 배인가요?","options":[{"t":"2.3배","correct":true},{"t":"0.23배","mis":"M6-2-u3-X03"},{"t":"23배","mis":"M6-2-u3-X04"},{"t":"4.16배","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 7.36 ÷ 3.2로 구해요.","3.2가 자연수가 되도록 한 칸씩 옮기면 73.6 ÷ 32예요.","73.6 ÷ 32 = 2.3 — 2.3배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#3','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'mc','auto','몫이 1.45인 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X20']::text[],true,'{"seq":3,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"몫이 1.45인 나눗셈은 어느 것인가요?","options":[{"t":"5.22 ÷ 3.6","correct":true},{"t":"3.6 ÷ 0.09","mis":"M6-2-u3-X20"},{"t":"7.5 ÷ 0.25","mis":"M6-2-u3-X20"},{"t":"8.84 ÷ 1.7","mis":"M6-2-u3-X20"}],"explanation":["3.6 ÷ 0.09 = 40, 7.5 ÷ 0.25 = 30이에요.","8.84 ÷ 1.7 = 5.2예요.","5.22 ÷ 3.6 = 52.2 ÷ 36 = 1.45예요."],"variant_rule":{"alt":[{"stem":"몫이 5.2인 나눗셈은 어느 것인가요?","options":[{"t":"8.84 ÷ 1.7","correct":true},{"t":"3.6 ÷ 0.09","mis":"M6-2-u3-X20"},{"t":"7.5 ÷ 0.25","mis":"M6-2-u3-X20"},{"t":"5.22 ÷ 3.6","mis":"M6-2-u3-X20"}],"explanation":["3.6 ÷ 0.09 = 40, 7.5 ÷ 0.25 = 30이에요.","5.22 ÷ 3.6 = 1.45예요.","8.84 ÷ 1.7 = 88.4 ÷ 17 = 5.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#4','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'mc','auto','몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],true,'{"seq":4,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"8.64 ÷ 0.24","correct":true},{"t":"8.64 ÷ 2.4","mis":"M6-2-u3-X19"},{"t":"86.4 ÷ 24","mis":"M6-2-u3-X19"},{"t":"864 ÷ 240","mis":"M6-2-u3-X19"}],"explanation":["8.64 ÷ 2.4, 86.4 ÷ 24, 864 ÷ 240은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 3.6이에요.","8.64 ÷ 0.24는 나누는 수만 바뀌어 몫이 36이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"351 ÷ 9","correct":true},{"t":"3.51 ÷ 0.9","mis":"M6-2-u3-X19"},{"t":"35.1 ÷ 9","mis":"M6-2-u3-X19"},{"t":"351 ÷ 90","mis":"M6-2-u3-X19"}],"explanation":["3.51 ÷ 0.9, 35.1 ÷ 9, 351 ÷ 90은 두 수에 똑같은 수를 곱한 사이예요.","세 식의 몫은 모두 3.9예요.","351 ÷ 9는 몫이 39예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#5','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'mc','auto','8.4 ÷ 0.03의 몫을 28이라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X03','M6-2-u3-X02']::text[],true,'{"seq":5,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"8.4 ÷ 0.03의 몫을 28이라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"8.4를 두 칸 옮길 때 빈 자리를 0으로 채우지 않아서","correct":true},{"t":"나누는 수만 옮겨서","mis":"M6-2-u3-X01"},{"t":"몫의 소수점을 옮기기 전 자리에서 찍어서","mis":"M6-2-u3-X03"},{"t":"두 수를 한 칸씩만 옮겨서","mis":"M6-2-u3-X02"}],"explanation":["0.03이 자연수가 되려면 두 칸 옮겨요.","8.4도 두 칸 옮기면 840 — 빈 자리는 0으로 채워요.","840 ÷ 3 = 280이에요(84 ÷ 3 = 28은 0을 빠뜨린 셈)."],"variant_rule":{"alt":[{"stem":"3.08 ÷ 1.4의 몫을 22라고 답한 친구가 있어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 빠뜨려서","correct":true},{"t":"나누는 수만 옮겨서","mis":"M6-2-u3-X01"},{"t":"몫의 소수점을 옮기기 전 자리에서 찍어서","mis":"M6-2-u3-X03"},{"t":"빈 자리를 0으로 채우지 않아서","mis":"M6-2-u3-X07"}],"explanation":["1.4가 자연수가 되도록 한 칸씩 옮기면 30.8 ÷ 14예요.","30.8 ÷ 14 = 2.2예요.","22는 2.2보다 10배 커요 — 몫의 소수점을 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#6','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'mc','auto','8.4 ÷ 0.03을 세로로 계산하려고 해요. 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X07','M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":6,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"8.4 ÷ 0.03을 세로로 계산하려고 해요. 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"840 ÷ 3","correct":true},{"t":"84 ÷ 3","mis":"M6-2-u3-X07"},{"t":"8.4 ÷ 3","mis":"M6-2-u3-X01"},{"t":"8400 ÷ 3","mis":"M6-2-u3-X02"}],"explanation":["0.03이 자연수가 되려면 두 칸 옮겨요.","8.4도 두 칸 옮기면 840 — 빈 자리는 0으로 채워요.","그래서 840 ÷ 3이에요."],"variant_rule":{"alt":[{"stem":"5.4 ÷ 0.45를 세로로 계산하려고 해요. 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"540 ÷ 45","correct":true},{"t":"54 ÷ 45","mis":"M6-2-u3-X07"},{"t":"5.4 ÷ 45","mis":"M6-2-u3-X01"},{"t":"5400 ÷ 45","mis":"M6-2-u3-X02"}],"explanation":["0.45가 자연수가 되려면 두 칸 옮겨요.","5.4도 두 칸 옮기면 540 — 빈 자리는 0으로 채워요.","그래서 540 ÷ 45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#7','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',3,'ox','auto','5.4 ÷ 0.45에서 5.4를 100배 하면 54예요.',ARRAY['M6-2-u3-X07']::text[],false,'{"seq":7,"concept":"M6-2-u3-C5","difficulty":3,"kind":"ox","stem":"5.4 ÷ 0.45에서 5.4를 100배 하면 54예요.","answer":"X","reason_options":[{"t":"5.4의 100배는 끝에 0을 적어 540이기 때문에","correct":true},{"t":"소수점을 옮기면 끝의 0은 쓰지 않기 때문에","mis":"M6-2-u3-X07"}],"mis":"M6-2-u3-X07","explanation":["5.4의 10배는 54예요.","100배는 54의 10배 — 540이에요.","그래서 540 ÷ 45 = 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#8','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',4,'mc','auto','네 나눗셈을 몫이 큰 것부터 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['M6-2-u3-X19','M6-2-u3-X20']::text[],false,'{"seq":8,"concept":"M6-2-u3-C5","difficulty":4,"kind":"mc","stem":"네 나눗셈을 몫이 큰 것부터 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"3.6 ÷ 0.09, 7.5 ÷ 0.25, 8.84 ÷ 1.7, 5.22 ÷ 3.6","correct":true},{"t":"5.22 ÷ 3.6, 8.84 ÷ 1.7, 7.5 ÷ 0.25, 3.6 ÷ 0.09","mis":"M6-2-u3-X19"},{"t":"7.5 ÷ 0.25, 3.6 ÷ 0.09, 8.84 ÷ 1.7, 5.22 ÷ 3.6","mis":"M6-2-u3-X20"},{"t":"3.6 ÷ 0.09, 7.5 ÷ 0.25, 5.22 ÷ 3.6, 8.84 ÷ 1.7","mis":"M6-2-u3-X20"}],"explanation":["3.6 ÷ 0.09 = 40, 7.5 ÷ 0.25 = 30이에요.","8.84 ÷ 1.7 = 5.2, 5.22 ÷ 3.6 = 1.45예요.","40 > 30 > 5.2 > 1.45 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#9','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',4,'essay','teacher','8.64 ÷ 2.4를 (자연수)÷(자연수)로 바꾸어 계산하는 방법과 (소수)÷(자연수)로 바꾸어 계산하는 방법을 쓰고, 두 방법과 계산 결과를 견주어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"8.64 ÷ 2.4를 (자연수)÷(자연수)로 바꾸어 계산하는 방법과 (소수)÷(자연수)로 바꾸어 계산하는 방법을 쓰고, 두 방법과 계산 결과를 견주어 보세요.","answer_guide":{"answer":"예: 두 수를 100배 하면 864 ÷ 240 = 3.6, 두 수를 10배 하면 86.4 ÷ 24 = 3.6이다. 첫 번째는 두 수가 모두 자연수가 되도록, 두 번째는 나누는 수만 자연수가 되도록 소수점을 옮겼고, 두 몫은 3.6으로 같다.","scoring_points":["864 ÷ 240 = 3.6을 썼는가","86.4 ÷ 24 = 3.6을 썼는가","옮긴 칸수는 달라도 몫이 같음을 견주었는가"]},"explanation":["100배: 864 ÷ 240 = 3.6이에요.","10배: 86.4 ÷ 24 = 3.6이에요.","두 수에 똑같이 곱했으니 몫은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L05_challenge#10','math',6,2,'u3','L05','tb_g6_2_math_u3_L05_challenge','lesson_challenge','M6-2-u3-C5',4,'essay','teacher','혜리는 「3.51 ÷ 0.9의 몫은 351 ÷ 9의 몫과 같아요.」라고 말했어요. 혜리의 말이 맞는지 따져 보고, 3.51 ÷ 0.9와 몫이 같은 나눗셈을 하나 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"혜리는 「3.51 ÷ 0.9의 몫은 351 ÷ 9의 몫과 같아요.」라고 말했어요. 혜리의 말이 맞는지 따져 보고, 3.51 ÷ 0.9와 몫이 같은 나눗셈을 하나 써 보세요.","answer_guide":{"answer":"예: 맞지 않다. 3.51은 100배, 0.9는 10배 하여 두 수에 같은 수를 곱하지 않았다. 나누는 수와 나누어지는 수에 0이 아닌 같은 수를 곱해야 몫이 같으므로 35.1 ÷ 9나 351 ÷ 90이 3.51 ÷ 0.9와 몫이 같다(몫 3.9).","scoring_points":["혜리의 말이 틀렸다고 했는가","두 수에 같은 수를 곱하지 않았다는 까닭을 썼는가","35.1 ÷ 9 또는 351 ÷ 90을 썼는가"]},"explanation":["351 ÷ 9 = 39, 3.51 ÷ 0.9 = 3.9예요.","두 수에 같은 수를 곱해야 몫이 같아요.","35.1 ÷ 9 = 3.9로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#1','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',1,'sa','auto','직사각형 모양 태양 전지판의 넓이는 8 m²이고, 세로는 1.6 m예요. 태양 전지판의 가로는 몇 m인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"직사각형 모양 태양 전지판의 넓이는 8 m²이고, 세로는 1.6 m예요. 태양 전지판의 가로는 몇 m인가요?","answer":["5"],"explanation":["8은 8.0과 같아요 — 나누는 수 1.6이 자연수가 되도록 두 수의 소수점을 한 칸씩 옮기고 빈 자리는 0으로 채워요.","8 ÷ 1.6은 80 ÷ 16이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","80 ÷ 16 = 5예요."],"variant_rule":{"alt":[{"stem":"7 ÷ 1.75의 몫은 얼마인가요?","answer":["4"],"explanation":["7은 7.00과 같아요 — 나누는 수 1.75가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 1.75는 700 ÷ 175가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","700 ÷ 175 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#2','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',1,'mc','auto','8 ÷ 1.6을 세로로 계산할 때 8은 어떻게 생각하고 소수점을 옮기나요?',ARRAY['M6-2-u3-X08','M6-2-u3-X03','M6-2-u3-X02']::text[],true,'{"seq":2,"concept":"M6-2-u3-C6","difficulty":1,"kind":"mc","stem":"8 ÷ 1.6을 세로로 계산할 때 8은 어떻게 생각하고 소수점을 옮기나요?","options":[{"t":"8.0으로 생각하고 한 칸 옮겨 80","correct":true},{"t":"8은 소수점이 없으니 그대로 둔다","mis":"M6-2-u3-X08"},{"t":"0.8로 생각한다","mis":"M6-2-u3-X03"},{"t":"8.00으로 생각하고 두 칸 옮겨 800","mis":"M6-2-u3-X02"}],"explanation":["1.6이 자연수가 되려면 한 칸 옮겨요.","8은 8.0과 같아서 한 칸 옮기면 80 — 빈 자리는 0이에요.","80 ÷ 16 = 5예요."],"variant_rule":{"alt":[{"stem":"7 ÷ 1.75를 세로로 계산할 때 7은 어떻게 생각하고 소수점을 옮기나요?","options":[{"t":"7.00으로 생각하고 두 칸 옮겨 700","correct":true},{"t":"7은 소수점이 없으니 그대로 둔다","mis":"M6-2-u3-X08"},{"t":"0.07로 생각한다","mis":"M6-2-u3-X03"},{"t":"7.0으로 생각하고 한 칸 옮겨 70","mis":"M6-2-u3-X02"}],"explanation":["1.75가 자연수가 되려면 두 칸 옮겨요.","7은 7.00과 같아서 두 칸 옮기면 700이에요.","700 ÷ 175 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#3','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',1,'mc','auto','8 ÷ 1.6에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?',ARRAY['M6-2-u3-X08','M6-2-u3-X01','M6-2-u3-X02']::text[],true,'{"seq":3,"concept":"M6-2-u3-C6","difficulty":1,"kind":"mc","stem":"8 ÷ 1.6에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"80 ÷ 16","correct":true},{"t":"8 ÷ 16","mis":"M6-2-u3-X08"},{"t":"80 ÷ 1.6","mis":"M6-2-u3-X01"},{"t":"800 ÷ 16","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 1.6이 자연수가 되려면 한 칸 옮겨야 해요.","나누어지는 수 8도 똑같이 한 칸 옮겨요 — 빈 자리는 0으로.","그래서 80 ÷ 16이 돼요."],"variant_rule":{"alt":[{"stem":"7 ÷ 1.75에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"700 ÷ 175","correct":true},{"t":"7 ÷ 175","mis":"M6-2-u3-X08"},{"t":"700 ÷ 1.75","mis":"M6-2-u3-X01"},{"t":"70 ÷ 175","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 1.75가 자연수가 되려면 두 칸 옮겨야 해요.","나누어지는 수 7도 똑같이 두 칸 옮겨요 — 빈 자리는 0으로.","그래서 700 ÷ 175가 돼요."]},{"stem":"16 ÷ 0.25에서 나누는 수가 자연수가 되도록 두 수의 소수점을 옮기면 어떤 나눗셈이 되나요?","options":[{"t":"1600 ÷ 25","correct":true},{"t":"16 ÷ 25","mis":"M6-2-u3-X08"},{"t":"1600 ÷ 0.25","mis":"M6-2-u3-X01"},{"t":"160 ÷ 25","mis":"M6-2-u3-X02"}],"explanation":["나누는 수 0.25가 자연수가 되려면 두 칸 옮겨야 해요.","나누어지는 수 16도 똑같이 두 칸 옮겨요 — 빈 자리는 0으로.","그래서 1600 ÷ 25가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#4','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',1,'sa','auto','8 ÷ 1.6을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 80 ÷ 16으로 바꾸었어요. 8 ÷ 1.6의 몫은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"8 ÷ 1.6을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 80 ÷ 16으로 바꾸었어요. 8 ÷ 1.6의 몫은 얼마인가요?","answer":["5"],"explanation":["8은 8.0과 같아요 — 나누는 수 1.6이 자연수가 되도록 두 수의 소수점을 한 칸씩 옮기고 빈 자리는 0으로 채워요.","8 ÷ 1.6은 80 ÷ 16이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","80 ÷ 16 = 5예요."],"asset":{"type":"ldiv","a":80,"b":16,"hide":["q"]},"variant_rule":{"alt":[{"stem":"36 ÷ 0.6을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 360 ÷ 6으로 바꾸었어요. 36 ÷ 0.6의 몫은 얼마인가요?","answer":["60"],"explanation":["36은 36.0과 같아요 — 나누는 수 0.6이 자연수가 되도록 두 수의 소수점을 한 칸씩 옮기고 빈 자리는 0으로 채워요.","36 ÷ 0.6은 360 ÷ 6이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","360 ÷ 6 = 60이에요."],"asset":{"type":"ldiv","a":360,"b":6,"hide":["q"]}},{"stem":"39 ÷ 1.5를 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 390 ÷ 15로 바꾸었어요. 39 ÷ 1.5의 몫은 얼마인가요?","answer":["26"],"explanation":["39는 39.0과 같아요 — 나누는 수 1.5가 자연수가 되도록 두 수의 소수점을 한 칸씩 옮기고 빈 자리는 0으로 채워요.","39 ÷ 1.5는 390 ÷ 15가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","390 ÷ 15 = 26이에요."],"asset":{"type":"ldiv","a":390,"b":15,"hide":["q"]}},{"stem":"16 ÷ 0.25를 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 1600 ÷ 25로 바꾸었어요. 16 ÷ 0.25의 몫은 얼마인가요?","answer":["64"],"explanation":["16은 16.00과 같아요 — 나누는 수 0.25가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","16 ÷ 0.25는 1600 ÷ 25가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","1600 ÷ 25 = 64예요."],"asset":{"type":"ldiv","a":1600,"b":25,"hide":["q"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#5','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'mc','auto','태양 전지판의 가로를 8 ÷ 1.6으로 구해요. 계산하기 전에 어림하면 가로는 어떨까요?',ARRAY['M6-2-u3-X09','M6-2-u3-X20']::text[],false,'{"seq":5,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"태양 전지판의 가로를 8 ÷ 1.6으로 구해요. 계산하기 전에 어림하면 가로는 어떨까요?","options":[{"t":"4 m보다 클 것 같아요","correct":true},{"t":"4 m보다 작을 것 같아요","mis":"M6-2-u3-X09"},{"t":"1 m보다 작을 것 같아요","mis":"M6-2-u3-X09"},{"t":"8 m보다 클 것 같아요","mis":"M6-2-u3-X20"}],"explanation":["8 ÷ 2 = 4예요.","1.6은 2보다 작은 수라서 몫은 4보다 커요.","계산하면 5 m — 어림과 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#6','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'mc','auto','영훈이네 집에 고구마는 5 kg 있고 감자는 0.4 kg 있어요. 고구마의 양은 감자의 양의 몇 배인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X17']::text[],false,'{"seq":6,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"영훈이네 집에 고구마는 5 kg 있고 감자는 0.4 kg 있어요. 고구마의 양은 감자의 양의 몇 배인가요?","options":[{"t":"12.5배","correct":true},{"t":"1.25배","mis":"M6-2-u3-X03"},{"t":"125배","mis":"M6-2-u3-X04"},{"t":"0.08배","mis":"M6-2-u3-X17"}],"explanation":["몇 배인지는 5 ÷ 0.4로 구해요.","5를 5.0으로 보고 한 칸씩 옮기면 50 ÷ 4예요.","50 ÷ 4 = 12.5 — 12.5배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#7','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'sa','auto','7 ÷ 1.75의 몫은 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u3-C6","difficulty":2,"kind":"sa","stem":"7 ÷ 1.75의 몫은 얼마인가요?","answer":["4"],"explanation":["7은 7.00과 같아요 — 나누는 수 1.75가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","7 ÷ 1.75는 700 ÷ 175가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","700 ÷ 175 = 4예요."],"variant_rule":{"alt":[{"stem":"16 ÷ 0.25의 몫은 얼마인가요?","answer":["64"],"explanation":["16은 16.00과 같아요 — 나누는 수 0.25가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","16 ÷ 0.25는 1600 ÷ 25가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","1600 ÷ 25 = 64예요."]},{"stem":"21 ÷ 0.35의 몫은 얼마인가요?","answer":["60"],"explanation":["21은 21.00과 같아요 — 나누는 수 0.35가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","21 ÷ 0.35는 2100 ÷ 35가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","2100 ÷ 35 = 60이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#8','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'mc','auto','61 ÷ 1.22 ○ 40 ÷ 1.25 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u3-X20','M6-2-u3-X23']::text[],true,'{"seq":8,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"61 ÷ 1.22 ○ 40 ÷ 1.25 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M6-2-u3-X20"},{"t":"=","mis":"M6-2-u3-X23"}],"explanation":["61 ÷ 1.22 = 50 · 40 ÷ 1.25 = 32예요.","50과 32를 견주어요.","그래서 61 ÷ 1.22 > 40 ÷ 1.25예요."],"variant_rule":{"alt":[{"stem":"33 ÷ 6.6 ○ 14 ÷ 2.8 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":"=","correct":true},{"t":">","mis":"M6-2-u3-X20"},{"t":"<","mis":"M6-2-u3-X20"}],"explanation":["33 ÷ 6.6 = 5 · 14 ÷ 2.8 = 5예요.","5와 5를 견주어요.","그래서 33 ÷ 6.6 = 14 ÷ 2.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#9','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',2,'ox','auto','16 ÷ 0.25의 몫은 16보다 작아요.',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":9,"concept":"M6-2-u3-C6","difficulty":2,"kind":"ox","stem":"16 ÷ 0.25의 몫은 16보다 작아요.","answer":"X","reason_options":[{"t":"0.25는 1보다 작아서 16 안에 16번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["16 ÷ 0.25 = 1600 ÷ 25 = 64예요.","64는 16보다 커요.","1보다 작은 수로 나누면 몫이 나누어지는 수보다 커져요."],"variant_rule":{"alt":[{"stem":"36 ÷ 0.6의 몫은 36보다 작아요.","answer":"X","reason_options":[{"t":"0.6은 1보다 작아서 36 안에 36번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"explanation":["36 ÷ 0.6 = 360 ÷ 6 = 60이에요.","60은 36보다 커요.","1보다 작은 수로 나누면 몫이 나누어지는 수보다 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_basic#10','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_basic','lesson_basic','M6-2-u3-C6',3,'mc','auto','52 ÷ 0.8의 몫을 6.5라고 계산한 친구가 있어요. 바르게 계산한 몫은 얼마인가요?',ARRAY['M6-2-u3-X08','M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":10,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"52 ÷ 0.8의 몫을 6.5라고 계산한 친구가 있어요. 바르게 계산한 몫은 얼마인가요?","options":[{"t":"65","correct":true},{"t":"6.5","mis":"M6-2-u3-X08"},{"t":"0.65","mis":"M6-2-u3-X03"},{"t":"650","mis":"M6-2-u3-X04"}],"explanation":["0.8이 자연수가 되려면 한 칸 옮겨요.","52도 52.0으로 보고 한 칸 옮기면 520 ÷ 8이에요.","520 ÷ 8 = 65예요(6.5는 52를 옮기지 않은 52 ÷ 8의 몫)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#1','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',2,'sa','auto','빈 용기를 가져가 샴푸 1.5 L를 5400원에 샀어요. 샴푸 1 L의 가격은 얼마인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u3-C6","difficulty":2,"kind":"sa","stem":"빈 용기를 가져가 샴푸 1.5 L를 5400원에 샀어요. 샴푸 1 L의 가격은 얼마인가요?","answer":["3600"],"explanation":["1 L의 가격은 (샴푸 가격) ÷ (샴푸의 양)으로 구해요.","5400 ÷ 1.5는 두 수를 10배 한 54000 ÷ 15와 같아요.","54000 ÷ 15 = 3600 — 3600원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#2','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',2,'sa','auto','넓이가 37 cm²인 평행사변형의 밑변의 길이가 7.4 cm일 때 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C6","difficulty":2,"kind":"sa","stem":"넓이가 37 cm²인 평행사변형의 밑변의 길이가 7.4 cm일 때 높이는 몇 cm인가요?","answer":["5"],"explanation":["37은 37.0과 같아요 — 나누는 수 7.4가 자연수가 되도록 두 수의 소수점을 한 칸씩 옮기고 빈 자리는 0으로 채워요.","37 ÷ 7.4는 370 ÷ 74가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","370 ÷ 74 = 5예요."],"variant_rule":{"alt":[{"stem":"넓이가 49.5 cm²인 평행사변형의 밑변의 길이가 8.25 cm일 때 높이는 몇 cm인가요?","answer":["6"],"explanation":["나누는 수 8.25가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","49.5 ÷ 8.25는 4950 ÷ 825가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","4950 ÷ 825 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#3','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'mc','auto','몫이 나누어지는 수보다 커지는 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X09']::text[],true,'{"seq":3,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"몫이 나누어지는 수보다 커지는 나눗셈은 어느 것인가요?","options":[{"t":"36 ÷ 0.6","correct":true},{"t":"39 ÷ 1.5","mis":"M6-2-u3-X09"},{"t":"7 ÷ 1.75","mis":"M6-2-u3-X09"},{"t":"8 ÷ 1.6","mis":"M6-2-u3-X09"}],"explanation":["나누는 수가 1보다 작으면 몫이 나누어지는 수보다 커져요.","36 ÷ 0.6 = 60 — 36보다 커요.","39 ÷ 1.5 = 26, 7 ÷ 1.75 = 4, 8 ÷ 1.6 = 5는 모두 나누어지는 수보다 작아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 몫이 나누어지는 수보다 커지는 나눗셈은 어느 것인가요?","options":[{"t":"16 ÷ 0.25","correct":true},{"t":"39 ÷ 1.5","mis":"M6-2-u3-X09"},{"t":"7 ÷ 1.75","mis":"M6-2-u3-X09"},{"t":"8 ÷ 1.6","mis":"M6-2-u3-X09"}],"explanation":["나누는 수가 1보다 작으면 몫이 나누어지는 수보다 커져요.","16 ÷ 0.25 = 64 — 16보다 커요.","나누는 수가 1보다 큰 세 나눗셈은 몫이 나누어지는 수보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#4','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'mc','auto','7 ÷ 1.75를 자연수의 나눗셈으로 바꾸려면 두 수에 똑같이 얼마를 곱해야 하나요?',ARRAY['M6-2-u3-X02','M6-2-u3-X08']::text[],true,'{"seq":4,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"7 ÷ 1.75를 자연수의 나눗셈으로 바꾸려면 두 수에 똑같이 얼마를 곱해야 하나요?","options":[{"t":"100","correct":true},{"t":"10","mis":"M6-2-u3-X02"},{"t":"1","mis":"M6-2-u3-X08"},{"t":"1000","mis":"M6-2-u3-X02"}],"explanation":["1.75가 자연수가 되려면 소수점을 두 칸 옮겨야 해요.","두 칸 옮기는 것은 100을 곱하는 것이에요.","7 × 100 = 700, 1.75 × 100 = 175 — 700 ÷ 175 = 4예요."],"variant_rule":{"alt":[{"stem":"8 ÷ 1.6을 자연수의 나눗셈으로 바꾸려면 두 수에 똑같이 얼마를 곱해야 하나요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M6-2-u3-X02"},{"t":"16","mis":"M6-2-u3-X20"},{"t":"2","mis":"M6-2-u3-X20"}],"explanation":["1.6이 자연수가 되려면 소수점을 한 칸 옮겨야 해요.","한 칸 옮기는 것은 10을 곱하는 것이에요.","80 ÷ 16 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#5','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'mc','auto','52 ÷ 0.8의 몫을 6.5라고 계산한 친구가 있어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M6-2-u3-X04','M6-2-u3-X02','M6-2-u3-X17']::text[],false,'{"seq":5,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"52 ÷ 0.8의 몫을 6.5라고 계산한 친구가 있어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"52의 소수점은 옮기지 않고 0.8만 8로 바꾸어서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"},{"t":"두 수를 두 칸씩 옮겨서","mis":"M6-2-u3-X02"},{"t":"0.8 대신 52를 옮겨서","mis":"M6-2-u3-X17"}],"explanation":["52 ÷ 8 = 6.5 — 0.8만 옮긴 셈이에요.","52도 52.0으로 보고 한 칸 옮겨 520이에요.","520 ÷ 8 = 65가 바른 몫이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#6','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'mc','auto','몫이 나머지와 다른 하나는 어느 것인가요?',ARRAY['M6-2-u3-X20']::text[],false,'{"seq":6,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"몫이 나머지와 다른 하나는 어느 것인가요?","options":[{"t":"61 ÷ 1.22","correct":true},{"t":"33 ÷ 6.6","mis":"M6-2-u3-X20"},{"t":"14 ÷ 2.8","mis":"M6-2-u3-X20"},{"t":"8 ÷ 1.6","mis":"M6-2-u3-X20"}],"explanation":["33 ÷ 6.6 = 330 ÷ 66 = 5, 14 ÷ 2.8 = 140 ÷ 28 = 5예요.","8 ÷ 1.6 = 80 ÷ 16 = 5예요.","61 ÷ 1.22 = 6100 ÷ 122 = 50 — 혼자 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#7','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',3,'sa','auto','21 ÷ 0.35의 몫은 얼마인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u3-C6","difficulty":3,"kind":"sa","stem":"21 ÷ 0.35의 몫은 얼마인가요?","answer":["60"],"explanation":["21은 21.00과 같아요 — 나누는 수 0.35가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","21 ÷ 0.35는 2100 ÷ 35가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","2100 ÷ 35 = 60이에요."],"variant_rule":{"alt":[{"stem":"39 ÷ 1.5의 몫은 얼마인가요?","answer":["26"],"explanation":["39는 39.0과 같아요 — 나누는 수 1.5가 자연수가 되도록 두 수의 소수점을 한 칸씩 옮기고 빈 자리는 0으로 채워요.","39 ÷ 1.5는 390 ÷ 15가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","390 ÷ 15 = 26이에요."]},{"stem":"9 ÷ 2.25의 몫은 얼마인가요?","answer":["4"],"explanation":["9는 9.00과 같아요 — 나누는 수 2.25가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 2.25는 900 ÷ 225가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","900 ÷ 225 = 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#8','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',4,'mc','auto','5 ÷ □ = 12.5예요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X17']::text[],true,'{"seq":8,"concept":"M6-2-u3-C6","difficulty":4,"kind":"mc","stem":"5 ÷ □ = 12.5예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"4","mis":"M6-2-u3-X03"},{"t":"0.04","mis":"M6-2-u3-X04"},{"t":"2.5","mis":"M6-2-u3-X17"}],"explanation":["5 ÷ □ = 12.5이면 □ = 5 ÷ 12.5예요.","5 ÷ 12.5 = 50 ÷ 125 = 0.4예요.","5 ÷ 0.4 = 50 ÷ 4 = 12.5로 맞아요."],"variant_rule":{"alt":[{"stem":"16 ÷ □ = 64예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"2.5","mis":"M6-2-u3-X03"},{"t":"0.025","mis":"M6-2-u3-X04"},{"t":"4","mis":"M6-2-u3-X17"}],"explanation":["16 ÷ □ = 64이면 □ = 16 ÷ 64예요.","16 ÷ 64 = 0.25예요.","16 ÷ 0.25 = 1600 ÷ 25 = 64로 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#9','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',4,'essay','teacher','직사각형 모양 태양 전지판의 넓이는 8 m², 세로는 1.6 m예요. 가로를 구하는 식을 쓰고, 먼저 어림한 뒤 계산하여 어림한 값과 견주어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C6","difficulty":4,"kind":"essay","stem":"직사각형 모양 태양 전지판의 넓이는 8 m², 세로는 1.6 m예요. 가로를 구하는 식을 쓰고, 먼저 어림한 뒤 계산하여 어림한 값과 견주어 보세요.","answer_guide":{"answer":"예: 가로 = 넓이 ÷ 세로이므로 8 ÷ 1.6이다. 8을 2보다 작은 수로 나누므로 8 ÷ 2 = 4보다 클 것이라고 어림한다. 8을 8.0으로 보고 두 수의 소수점을 한 칸씩 옮기면 80 ÷ 16 = 5이므로 가로는 5 m이고, 4 m보다 클 것이라는 어림과 비슷하다.","scoring_points":["8 ÷ 1.6 식을 세웠는가","4 m보다 크다고 어림했는가","80 ÷ 16 = 5를 구해 어림과 견주었는가"]},"explanation":["가로 = 8 ÷ 1.6이에요.","어림: 8 ÷ 2 = 4보다 커요.","80 ÷ 16 = 5 — 5 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L06_challenge#10','math',6,2,'u3','L06','tb_g6_2_math_u3_L06_challenge','lesson_challenge','M6-2-u3-C6',4,'essay','teacher','52 ÷ 0.8을 6.5라고 계산한 친구에게 잘못된 곳을 알려 주고, 바르게 계산하는 과정을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C6","difficulty":4,"kind":"essay","stem":"52 ÷ 0.8을 6.5라고 계산한 친구에게 잘못된 곳을 알려 주고, 바르게 계산하는 과정을 써 보세요.","answer_guide":{"answer":"예: 0.8만 8로 바꾸고 52는 그대로 두어 52 ÷ 8을 계산했다. 나누는 수와 나누어지는 수의 소수점을 똑같이 옮겨야 하므로 52를 52.0으로 보고 한 칸 옮겨 520 ÷ 8 = 65이다.","scoring_points":["52를 옮기지 않은 잘못을 찾았는가","두 수를 똑같이 한 칸 옮겨 520 ÷ 8로 바꾸었는가","65를 구했는가"]},"explanation":["6.5는 52 ÷ 8의 몫이에요.","52도 한 칸 옮겨 520이에요.","520 ÷ 8 = 65예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#1','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',1,'mc','auto','1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":1,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.17","correct":true},{"t":"0.16","mis":"M6-2-u3-X11"},{"t":"0.167","mis":"M6-2-u3-X12"},{"t":"0.2","mis":"M6-2-u3-X12"}],"explanation":["1 ÷ 6 = 0.1666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 0.17이에요."],"variant_rule":{"alt":[{"stem":"6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.77","correct":true},{"t":"4.76","mis":"M6-2-u3-X11"},{"t":"4.769","mis":"M6-2-u3-X12"},{"t":"4.8","mis":"M6-2-u3-X12"}],"explanation":["6.2 ÷ 1.3 = 4.7692…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 9이므로 올려요 — 4.77이에요."]},{"stem":"3.38 ÷ 0.9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.76","correct":true},{"t":"3.75","mis":"M6-2-u3-X11"},{"t":"3.756","mis":"M6-2-u3-X12"},{"t":"3.8","mis":"M6-2-u3-X12"}],"explanation":["3.38 ÷ 0.9 = 3.7555…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 3.76이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#2','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',1,'sa','auto','3.7 ÷ 0.7의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u3-C7","difficulty":1,"kind":"sa","stem":"3.7 ÷ 0.7의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?","answer":["5"],"explanation":["3.7 ÷ 0.7 = 5.285…예요.","일의 자리까지 나타내려면 소수 첫째 자리 숫자를 봐요.","소수 첫째 자리 숫자가 2이므로 버려요 — 5예요."],"variant_rule":{"alt":[{"stem":"11 ÷ 3의 몫을 반올림하여 일의 자리까지 나타내면 얼마인가요?","answer":["4"],"explanation":["11 ÷ 3 = 3.666…이에요.","일의 자리까지 나타내려면 소수 첫째 자리 숫자를 봐요.","소수 첫째 자리 숫자가 6이므로 올려요 — 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#3','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',1,'mc','auto','3.7 ÷ 0.7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":3,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"3.7 ÷ 0.7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"5.3","correct":true},{"t":"5.2","mis":"M6-2-u3-X11"},{"t":"5.29","mis":"M6-2-u3-X12"},{"t":"5","mis":"M6-2-u3-X12"}],"explanation":["3.7 ÷ 0.7 = 5.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 8이므로 올려요 — 5.3이에요."],"variant_rule":{"alt":[{"stem":"11 ÷ 3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.7","correct":true},{"t":"3.6","mis":"M6-2-u3-X11"},{"t":"3.67","mis":"M6-2-u3-X12"},{"t":"4","mis":"M6-2-u3-X12"}],"explanation":["11 ÷ 3 = 3.666…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 6이므로 올려요 — 3.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#4','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',1,'mc','auto','흙 공 6개의 무게가 1 kg이에요. 1 ÷ 5 = 0.2인 것을 떠올리면 흙 공 1개의 무게 1 ÷ 6은 얼마쯤일까요?',ARRAY['M6-2-u3-X09','M6-2-u3-X17']::text[],false,'{"seq":4,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"흙 공 6개의 무게가 1 kg이에요. 1 ÷ 5 = 0.2인 것을 떠올리면 흙 공 1개의 무게 1 ÷ 6은 얼마쯤일까요?","options":[{"t":"0.2보다 작아요","correct":true},{"t":"0.2보다 커요","mis":"M6-2-u3-X09"},{"t":"1보다 커요","mis":"M6-2-u3-X09"},{"t":"6쯤이에요","mis":"M6-2-u3-X17"}],"explanation":["1 ÷ 5 = 0.2예요.","6은 5보다 크니 1 ÷ 6은 0.2보다 작아요.","계산하면 0.166… — 어림과 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#5','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'mc','auto','3.7 ÷ 0.7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":5,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"3.7 ÷ 0.7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"5.29","correct":true},{"t":"5.28","mis":"M6-2-u3-X11"},{"t":"5.286","mis":"M6-2-u3-X12"},{"t":"5.3","mis":"M6-2-u3-X12"}],"explanation":["3.7 ÷ 0.7 = 5.2857…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 5이므로 올려요 — 5.29예요."],"variant_rule":{"alt":[{"stem":"8.3 ÷ 3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.77","correct":true},{"t":"2.76","mis":"M6-2-u3-X11"},{"t":"2.767","mis":"M6-2-u3-X12"},{"t":"2.8","mis":"M6-2-u3-X12"}],"explanation":["8.3 ÷ 3 = 2.7666…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 6이므로 올려요 — 2.77이에요."]},{"stem":"5 ÷ 6.3의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.79","correct":true},{"t":"0.794","mis":"M6-2-u3-X12"},{"t":"0.8","mis":"M6-2-u3-X12"},{"t":"0.793","mis":"M6-2-u3-X11"}],"explanation":["5 ÷ 6.3 = 0.7936…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 3이므로 버려요 — 0.79예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#6','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'sa','auto','몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u3-C7","difficulty":2,"kind":"sa","stem":"몫을 반올림하여 소수 둘째 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["3"],"explanation":["반올림은 나타낼 자리 바로 아래 자리 숫자를 봐요.","소수 둘째 자리 바로 아래는 소수 셋째 자리예요.","그 숫자가 5 이상이면 올리고, 4 이하면 버려요."],"variant_rule":{"alt":[{"stem":"몫을 반올림하여 일의 자리까지 나타내려면 소수 몇째 자리 숫자를 보아야 하나요?","answer":["1"],"explanation":["반올림은 나타낼 자리 바로 아래 자리 숫자를 봐요.","일의 자리 바로 아래는 소수 첫째 자리예요.","그 숫자가 5 이상이면 올리고, 4 이하면 버려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#7','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'mc','auto','포도주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마실 수 있는 포도주스는 몇 L인지 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X12','M6-2-u3-X10','M6-2-u3-X17']::text[],true,'{"seq":7,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"포도주스 3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마실 수 있는 포도주스는 몇 L인지 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.4 L","correct":true},{"t":"0.42 L","mis":"M6-2-u3-X12"},{"t":"0.5 L","mis":"M6-2-u3-X10"},{"t":"2.3 L","mis":"M6-2-u3-X17"}],"explanation":["3 ÷ 7 = 0.428…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자 2를 봐요.","2는 버려요 — 0.4 L예요."],"variant_rule":{"alt":[{"stem":"주스 4.3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마실 수 있는 주스는 몇 L인지 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.61 L","mis":"M6-2-u3-X12"},{"t":"0.7 L","mis":"M6-2-u3-X10"},{"t":"1.6 L","mis":"M6-2-u3-X17"}],"explanation":["4.3 ÷ 7 = 0.614…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자 1을 봐요.","1은 버려요 — 0.6 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#8','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'mc','auto','1 ÷ 6처럼 몫이 간단한 소수로 구해지지 않을 때 몫은 어떻게 나타내면 좋을까요?',ARRAY['M6-2-u3-X12','M6-2-u3-X11','M6-2-u3-X17']::text[],false,'{"seq":8,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"1 ÷ 6처럼 몫이 간단한 소수로 구해지지 않을 때 몫은 어떻게 나타내면 좋을까요?","options":[{"t":"반올림하여 나타내요","correct":true},{"t":"몫을 끝없이 다 써요","mis":"M6-2-u3-X12"},{"t":"소수점 아래는 모두 버리고 0이라고 써요","mis":"M6-2-u3-X11"},{"t":"나누어지는 수와 나누는 수를 바꾸어 나눠요","mis":"M6-2-u3-X17"}],"explanation":["1 ÷ 6 = 0.166…처럼 6이 끝없이 이어져요.","이럴 때는 몫을 반올림하여 정한 자리까지 나타내요.","1 ÷ 6을 소수 둘째 자리까지 나타내면 0.17이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#9','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',2,'mc','auto','흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 둘째 자리까지 나타내면 몇 kg인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12','M6-2-u3-X17']::text[],false,'{"seq":9,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 반올림하여 소수 둘째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"0.17 kg","correct":true},{"t":"0.16 kg","mis":"M6-2-u3-X11"},{"t":"0.2 kg","mis":"M6-2-u3-X12"},{"t":"6 kg","mis":"M6-2-u3-X17"}],"explanation":["흙 공 1개의 무게는 1 ÷ 6 = 0.166… (kg)이에요.","소수 셋째 자리 숫자 6을 보고 올려요.","0.17 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_basic#10','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_basic','lesson_basic','M6-2-u3-C7',3,'mc','auto','17 ÷ 4.6의 몫을 반올림하여 소수 첫째 자리까지 나타낸 수 ○ 17 ÷ 4.6 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],true,'{"seq":10,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"17 ÷ 4.6의 몫을 반올림하여 소수 첫째 자리까지 나타낸 수 ○ 17 ÷ 4.6 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M6-2-u3-X11"},{"t":"=","mis":"M6-2-u3-X12"}],"explanation":["17 ÷ 4.6 = 3.695…예요.","소수 둘째 자리 숫자 9를 보고 올리면 3.7이에요.","3.7은 3.695…보다 커요 — >예요."],"variant_rule":{"alt":[{"stem":"5 ÷ 1.2의 몫을 반올림하여 소수 첫째 자리까지 나타낸 수 ○ 5 ÷ 1.2 — ○ 안에 >, =, < 중에서 알맞은 것은 어느 것인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M6-2-u3-X11"},{"t":"=","mis":"M6-2-u3-X12"}],"explanation":["5 ÷ 1.2 = 4.166…이에요.","소수 둘째 자리 숫자 6을 보고 올리면 4.2예요.","4.2는 4.166…보다 커요 — >예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#1','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',2,'mc','auto','집에서 도서관까지 거리는 3.5 km, 집에서 공원까지 거리는 1.7 km예요. 집에서 도서관까지 거리는 집에서 공원까지 거리의 몇 배인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12','M6-2-u3-X16']::text[],false,'{"seq":1,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"집에서 도서관까지 거리는 3.5 km, 집에서 공원까지 거리는 1.7 km예요. 집에서 도서관까지 거리는 집에서 공원까지 거리의 몇 배인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.06배","correct":true},{"t":"2.05배","mis":"M6-2-u3-X11"},{"t":"2.1배","mis":"M6-2-u3-X12"},{"t":"1.8배","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 3.5 ÷ 1.7로 구해요.","3.5 ÷ 1.7 = 2.058…이에요.","소수 셋째 자리 숫자 8을 보고 올려 2.06배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#2','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',2,'mc','auto','2.9 ÷ 1.4의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X12']::text[],true,'{"seq":2,"concept":"M6-2-u3-C7","difficulty":2,"kind":"mc","stem":"2.9 ÷ 1.4의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.07","correct":true},{"t":"2.071","mis":"M6-2-u3-X12"},{"t":"2.1","mis":"M6-2-u3-X12"},{"t":"2.0714","mis":"M6-2-u3-X12"}],"explanation":["2.9 ÷ 1.4 = 2.0714…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 1이므로 버려요 — 2.07이에요."],"variant_rule":{"alt":[{"stem":"35 ÷ 9의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.89","correct":true},{"t":"3.88","mis":"M6-2-u3-X11"},{"t":"3.889","mis":"M6-2-u3-X12"},{"t":"3.9","mis":"M6-2-u3-X12"}],"explanation":["35 ÷ 9 = 3.8888…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 8이므로 올려요 — 3.89예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#3','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'mc','auto','1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?',ARRAY['M6-2-u3-X10','M6-2-u3-X12','M6-2-u3-X03']::text[],true,'{"seq":3,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"1 ÷ 6의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 0.16이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["1 ÷ 6 = 0.166…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자 6을 봐요.","5 이상이라 올려 0.17이에요."],"variant_rule":{"alt":[{"stem":"6.2 ÷ 1.3의 몫을 반올림하여 소수 둘째 자리까지 나타낸 친구가 4.76이라고 답했어요. 잘못된 까닭은 무엇인가요?","options":[{"t":"소수 셋째 자리 숫자가 5 이상인데 올리지 않고 버려서","correct":true},{"t":"소수 둘째 자리 숫자를 보고 판단해서","mis":"M6-2-u3-X10"},{"t":"소수 첫째 자리까지 나타내서","mis":"M6-2-u3-X12"},{"t":"몫의 소수점을 잘못 찍어서","mis":"M6-2-u3-X03"}],"explanation":["6.2 ÷ 1.3 = 4.769…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자 9를 봐요.","5 이상이라 올려 4.77이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#4','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'mc','auto','6.2 ÷ 1.3 = 4.769…예요. 몫을 반올림하여 4.8로 나타냈다면 어느 자리까지 나타낸 것인가요?',ARRAY['M6-2-u3-X12']::text[],true,'{"seq":4,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"6.2 ÷ 1.3 = 4.769…예요. 몫을 반올림하여 4.8로 나타냈다면 어느 자리까지 나타낸 것인가요?","options":[{"t":"소수 첫째 자리","correct":true},{"t":"일의 자리","mis":"M6-2-u3-X12"},{"t":"소수 둘째 자리","mis":"M6-2-u3-X12"},{"t":"소수 셋째 자리","mis":"M6-2-u3-X12"}],"explanation":["일의 자리까지면 5, 소수 둘째 자리까지면 4.77이에요.","소수 첫째 자리까지면 소수 둘째 자리 숫자 6을 보고 올려 4.8이에요.","나타낼 자리가 다르면 답이 달라져요."],"variant_rule":{"alt":[{"stem":"3.7 ÷ 0.7 = 5.285…예요. 몫을 반올림하여 5.29로 나타냈다면 어느 자리까지 나타낸 것인가요?","options":[{"t":"소수 둘째 자리","correct":true},{"t":"일의 자리","mis":"M6-2-u3-X12"},{"t":"소수 첫째 자리","mis":"M6-2-u3-X12"},{"t":"소수 셋째 자리","mis":"M6-2-u3-X12"}],"explanation":["일의 자리까지면 5, 소수 첫째 자리까지면 5.3이에요.","소수 둘째 자리까지면 소수 셋째 자리 숫자 5를 보고 올려 5.29예요.","나타낼 자리가 다르면 답이 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#5','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'mc','auto','어떤 수를 0.6으로 나누어야 할 것을 잘못하여 곱했더니 4.2가 되었어요. 바르게 계산한 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X16']::text[],false,'{"seq":5,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"어떤 수를 0.6으로 나누어야 할 것을 잘못하여 곱했더니 4.2가 되었어요. 바르게 계산한 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"11.7","correct":true},{"t":"11.6","mis":"M6-2-u3-X11"},{"t":"7","mis":"M6-2-u3-X16"},{"t":"2.5","mis":"M6-2-u3-X16"}],"explanation":["어떤 수 × 0.6 = 4.2이므로 어떤 수는 4.2 ÷ 0.6 = 7이에요.","바르게 계산하면 7 ÷ 0.6 = 11.66…이에요.","소수 둘째 자리 숫자 6을 보고 올려 11.7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#6','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'mc','auto','16과 7 가운데 큰 수를 작은 수로 나눈 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12','M6-2-u3-X17']::text[],true,'{"seq":6,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"16과 7 가운데 큰 수를 작은 수로 나눈 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.3","correct":true},{"t":"2.2","mis":"M6-2-u3-X11"},{"t":"2.29","mis":"M6-2-u3-X12"},{"t":"0.4","mis":"M6-2-u3-X17"}],"explanation":["16 ÷ 7 = 2.285…예요.","소수 둘째 자리 숫자 8을 보고 올려요.","2.3이에요."],"variant_rule":{"alt":[{"stem":"43과 6 가운데 큰 수를 작은 수로 나눈 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"7.17","correct":true},{"t":"7.16","mis":"M6-2-u3-X11"},{"t":"7.2","mis":"M6-2-u3-X12"},{"t":"0.14","mis":"M6-2-u3-X17"}],"explanation":["43 ÷ 6 = 7.166…이에요.","소수 셋째 자리 숫자 6을 보고 올려요.","7.17이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#7','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',3,'mc','auto','17.1 ÷ 2.3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X12']::text[],true,'{"seq":7,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"17.1 ÷ 2.3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"7.4","correct":true},{"t":"7.43","mis":"M6-2-u3-X12"},{"t":"7","mis":"M6-2-u3-X12"},{"t":"7.434","mis":"M6-2-u3-X12"}],"explanation":["17.1 ÷ 2.3 = 7.434…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 3이므로 버려요 — 7.4예요."],"variant_rule":{"alt":[{"stem":"40 ÷ 22의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.82","correct":true},{"t":"1.81","mis":"M6-2-u3-X11"},{"t":"1.818","mis":"M6-2-u3-X12"},{"t":"1.8","mis":"M6-2-u3-X12"}],"explanation":["40 ÷ 22 = 1.8181…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 8이므로 올려요 — 1.82예요."]},{"stem":"2 ÷ 0.7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.86","correct":true},{"t":"2.85","mis":"M6-2-u3-X11"},{"t":"2.857","mis":"M6-2-u3-X12"},{"t":"2.9","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 0.7 = 2.8571…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 7이므로 올려요 — 2.86이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#8','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',4,'mc','auto','23.1 ÷ 4.7의 몫을 반올림하여 소수 첫째 자리까지 나타낸 수와 소수 둘째 자리까지 나타낸 수의 차는 얼마인가요?',ARRAY['M6-2-u3-X12','M6-2-u3-X11']::text[],false,'{"seq":8,"concept":"M6-2-u3-C7","difficulty":4,"kind":"mc","stem":"23.1 ÷ 4.7의 몫을 반올림하여 소수 첫째 자리까지 나타낸 수와 소수 둘째 자리까지 나타낸 수의 차는 얼마인가요?","options":[{"t":"0.01","correct":true},{"t":"0.1","mis":"M6-2-u3-X12"},{"t":"0.02","mis":"M6-2-u3-X11"},{"t":"0","mis":"M6-2-u3-X12"}],"explanation":["23.1 ÷ 4.7 = 4.914…예요.","소수 첫째 자리까지는 4.9, 소수 둘째 자리까지는 4.91이에요.","4.91 − 4.9 = 0.01이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#9','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',4,'essay','teacher','흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 먼저 어림하고, 1 ÷ 6을 계산하여 몫을 반올림하여 소수 첫째 자리까지, 소수 둘째 자리까지 나타내 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C7","difficulty":4,"kind":"essay","stem":"흙 공 6개의 무게가 1 kg이에요. 흙 공 1개의 무게를 먼저 어림하고, 1 ÷ 6을 계산하여 몫을 반올림하여 소수 첫째 자리까지, 소수 둘째 자리까지 나타내 보세요.","answer_guide":{"answer":"예: 1 ÷ 5 = 0.2이므로 1 ÷ 6은 0.2보다 작을 것이다. 1 ÷ 6 = 0.166…이므로 소수 첫째 자리까지 나타내면 소수 둘째 자리 숫자 6을 보고 올려 0.2 kg, 소수 둘째 자리까지 나타내면 소수 셋째 자리 숫자 6을 보고 올려 0.17 kg이다.","scoring_points":["0.2보다 작다고 어림했는가","0.166…을 구했는가","0.2와 0.17을 바르게 나타냈는가"]},"explanation":["어림: 1 ÷ 5 = 0.2보다 작아요.","1 ÷ 6 = 0.166…이에요.","소수 첫째 0.2 · 소수 둘째 0.17이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L07_challenge#10','math',6,2,'u3','L07','tb_g6_2_math_u3_L07_challenge','lesson_challenge','M6-2-u3-C7',4,'essay','teacher','3.7 ÷ 0.7의 몫을 반올림하여 일의 자리까지, 소수 첫째 자리까지, 소수 둘째 자리까지 나타내고, 문제를 풀 때 무엇을 조심해야 하는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C7","difficulty":4,"kind":"essay","stem":"3.7 ÷ 0.7의 몫을 반올림하여 일의 자리까지, 소수 첫째 자리까지, 소수 둘째 자리까지 나타내고, 문제를 풀 때 무엇을 조심해야 하는지 써 보세요.","answer_guide":{"answer":"예: 3.7 ÷ 0.7 = 5.285…이므로 일의 자리까지 5, 소수 첫째 자리까지 5.3, 소수 둘째 자리까지 5.29이다. 나타내려는 자리가 다르면 답이 달라지므로 문제를 잘 읽고 어느 자리에서 반올림할지 살펴야 한다.","scoring_points":["5.285…를 구했는가","5, 5.3, 5.29를 바르게 나타냈는가","나타낼 자리에 따라 답이 달라짐을 썼는가"]},"explanation":["3.7 ÷ 0.7 = 5.285…예요.","일의 자리 5 · 소수 첫째 5.3 · 소수 둘째 5.29예요.","어느 자리까지인지 먼저 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#1','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',1,'mc','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수를 구하기 위한 식은 어느 것인가요?',ARRAY['M6-2-u3-X17','M6-2-u3-X16']::text[],true,'{"seq":1,"concept":"M6-2-u3-C8","difficulty":1,"kind":"mc","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수를 구하기 위한 식은 어느 것인가요?","options":[{"t":"7.8 ÷ 1.8","correct":true},{"t":"1.8 ÷ 7.8","mis":"M6-2-u3-X17"},{"t":"7.8 − 1.8","mis":"M6-2-u3-X16"},{"t":"7.8 × 1.8","mis":"M6-2-u3-X16"}],"explanation":["7.8 L에서 1.8 L씩 몇 번 덜어 낼 수 있는지 구해요.","그래서 나눗셈을 해요.","식은 7.8 ÷ 1.8이에요."],"variant_rule":{"alt":[{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수를 구하기 위한 식은 어느 것인가요?","options":[{"t":"10.2 ÷ 1.4","correct":true},{"t":"1.4 ÷ 10.2","mis":"M6-2-u3-X17"},{"t":"10.2 − 1.4","mis":"M6-2-u3-X16"},{"t":"10.2 × 1.4","mis":"M6-2-u3-X16"}],"explanation":["10.2 L에서 1.4 L씩 몇 번 덜어 낼 수 있는지 구해요.","그래서 나눗셈을 해요.","식은 10.2 ÷ 1.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#2','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',1,'mc','auto','7.8 ÷ 1.8을 계산기로 계산하면 화면에 어떤 수가 나오나요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X20']::text[],false,'{"seq":2,"concept":"M6-2-u3-C8","difficulty":1,"kind":"mc","stem":"7.8 ÷ 1.8을 계산기로 계산하면 화면에 어떤 수가 나오나요?","options":[{"t":"4.3333…","correct":true},{"t":"0.4333…","mis":"M6-2-u3-X03"},{"t":"43.333…","mis":"M6-2-u3-X04"},{"t":"4.6","mis":"M6-2-u3-X20"}],"explanation":["1.8이 자연수가 되도록 한 칸씩 옮기면 78 ÷ 18이에요.","78 ÷ 18 = 4.333…으로 3이 끝없이 이어져요.","계산기에는 4.3333…이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#3','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',1,'sa','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u3-C8","difficulty":1,"kind":"sa","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["4"],"explanation":["7.8 ÷ 1.8을 계산하면 4.333…이에요.","1.8 L씩 4번 주면 7.2 L — 5번 주려면 9 L가 있어야 해서 모자라요.","그래서 4명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["7"],"explanation":["10.2 ÷ 1.4를 계산하면 7.285…예요.","1.4 L씩 7번 주면 9.8 L — 8번 주려면 11.2 L가 있어야 해서 모자라요.","그래서 7명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#4','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',1,'mc','auto','7.8 ÷ 1.8을 계산기로 계산한 4.3333…을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X21','M6-2-u3-X13']::text[],false,'{"seq":4,"concept":"M6-2-u3-C8","difficulty":1,"kind":"mc","stem":"7.8 ÷ 1.8을 계산기로 계산한 4.3333…을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"나누어 줄 수 있는 사람 수가 4명이에요","correct":true},{"t":"나누어 주고 남는 당근주스가 0.3333… L예요","mis":"M6-2-u3-X14"},{"t":"4.3명에게 나누어 줄 수 있어요","mis":"M6-2-u3-X21"},{"t":"5명에게 나누어 줄 수 있어요","mis":"M6-2-u3-X13"}],"explanation":["4.3333…의 자연수 부분 4가 나누어 줄 수 있는 사람 수예요.","사람 수는 4.3명처럼 소수로 쓸 수 없어요.","소수 부분은 남는 당근주스의 양이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#5','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'mc','auto','당근주스를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?',ARRAY['M6-2-u3-X15','M6-2-u3-X13','M6-2-u3-X16']::text[],true,'{"seq":5,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?","options":[{"t":"7.2 L","correct":true},{"t":"7.8 L","mis":"M6-2-u3-X15"},{"t":"9 L","mis":"M6-2-u3-X13"},{"t":"5.8 L","mis":"M6-2-u3-X16"}],"explanation":["한 명에게 1.8 L씩 4명이에요.","나누어 준 양은 곱셈으로 구해요.","1.8 × 4 = 7.2 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 준 당근주스는 모두 몇 L인가요?","options":[{"t":"9.8 L","correct":true},{"t":"10.2 L","mis":"M6-2-u3-X15"},{"t":"11.2 L","mis":"M6-2-u3-X13"},{"t":"8.4 L","mis":"M6-2-u3-X16"}],"explanation":["한 명에게 1.4 L씩 7명이에요.","나누어 준 양은 곱셈으로 구해요.","1.4 × 7 = 9.8 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#6','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'mc','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":6,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"1.8 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","7.8 − 7.2 = 0.6 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.4 L","correct":true},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"1.4 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","10.2 − 9.8 = 0.4 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#7','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'ox','auto','7.8 ÷ 1.8 = 4.333…이므로 당근주스를 4.3명에게 나누어 줄 수 있어요.',ARRAY['M6-2-u3-X21']::text[],false,'{"seq":7,"concept":"M6-2-u3-C8","difficulty":2,"kind":"ox","stem":"7.8 ÷ 1.8 = 4.333…이므로 당근주스를 4.3명에게 나누어 줄 수 있어요.","answer":"X","reason_options":[{"t":"나누어 줄 수 있는 사람 수는 하나, 둘로 세는 수라 4명이라고 해야 하기 때문에","correct":true},{"t":"계산기가 알려 준 몫을 그대로 쓰면 되기 때문에","mis":"M6-2-u3-X21"}],"mis":"M6-2-u3-X21","explanation":["사람 수는 4.3명처럼 나타낼 수 없어요.","1.8 L씩 4명에게 주면 7.2 L — 한 명 더 주기엔 모자라요.","그래서 4명에게 나누어 줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#8','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'mc','auto','당근주스를 4명에게 1.8 L씩 나누어 주고 0.6 L가 남았어요. 바르게 구했는지 확인하는 식은 어느 것인가요?',ARRAY['M6-2-u3-X16','M6-2-u3-X15']::text[],true,'{"seq":8,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스를 4명에게 1.8 L씩 나누어 주고 0.6 L가 남았어요. 바르게 구했는지 확인하는 식은 어느 것인가요?","options":[{"t":"1.8 × 4 + 0.6","correct":true},{"t":"1.8 + 4 + 0.6","mis":"M6-2-u3-X16"},{"t":"0.6 × 4 + 1.8","mis":"M6-2-u3-X15"},{"t":"1.8 × 4 − 0.6","mis":"M6-2-u3-X16"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","나누어 준 양과 남는 양을 더하면 처음 양이 돼요.","7.2 + 0.6 = 7.8 (L) — 바르게 구했어요."],"variant_rule":{"alt":[{"stem":"당근주스를 7명에게 1.4 L씩 나누어 주고 0.4 L가 남았어요. 바르게 구했는지 확인하는 식은 어느 것인가요?","options":[{"t":"1.4 × 7 + 0.4","correct":true},{"t":"1.4 + 7 + 0.4","mis":"M6-2-u3-X16"},{"t":"0.4 × 7 + 1.4","mis":"M6-2-u3-X15"},{"t":"1.4 × 7 − 0.4","mis":"M6-2-u3-X16"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","나누어 준 양과 남는 양을 더하면 처음 양이 돼요.","9.8 + 0.4 = 10.2 (L) — 바르게 구했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#9','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',2,'mc','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 줄 때, 5명에게는 나누어 줄 수 없는 까닭은 무엇인가요?',ARRAY['M6-2-u3-X13','M6-2-u3-X15','M6-2-u3-X20']::text[],false,'{"seq":9,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 줄 때, 5명에게는 나누어 줄 수 없는 까닭은 무엇인가요?","options":[{"t":"5명에게 주려면 9 L가 있어야 하는데 7.8 L뿐이라서","correct":true},{"t":"계산기 몫이 4.3333…이라 반올림해야 해서","mis":"M6-2-u3-X13"},{"t":"남는 0.6 L도 한 명에게 줄 수 있어서","mis":"M6-2-u3-X15"},{"t":"1.8 L는 소수라서","mis":"M6-2-u3-X20"}],"explanation":["1.8 × 5 = 9 (L)예요.","7.8 L는 9 L보다 적어요.","그래서 나누어 줄 수 있는 사람은 4명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_basic#10','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_basic','lesson_basic','M6-2-u3-C8',3,'mc','auto','조건을 바꾸었어요. 당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 당근주스의 양은 어느 것인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X13','M6-2-u3-X21']::text[],false,'{"seq":10,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"조건을 바꾸었어요. 당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 당근주스의 양은 어느 것인가요?","options":[{"t":"7명, 0.4 L","correct":true},{"t":"7명, 0.2 L","mis":"M6-2-u3-X14"},{"t":"8명, 0.4 L","mis":"M6-2-u3-X13"},{"t":"7.2명, 0 L","mis":"M6-2-u3-X21"}],"explanation":["10.2 ÷ 1.4 = 7.285…이므로 7명이에요.","나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 10.2 − 9.8 = 0.4 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#1','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',2,'sa','auto','물 4 L를 한 명에게 1.3 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u3-C8","difficulty":2,"kind":"sa","stem":"물 4 L를 한 명에게 1.3 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["3"],"explanation":["4 ÷ 1.3을 계산하면 3.076…이에요.","1.3 L씩 3번 주면 3.9 L — 4번 주려면 5.2 L가 있어야 해서 모자라요.","그래서 3명에게 나누어 줄 수 있어요."],"variant_rule":{"alt":[{"stem":"물 4 L를 한 명에게 1.33 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["3"],"explanation":["4 ÷ 1.33을 계산하면 3.007…이에요.","1.33 L씩 3번 주면 3.99 L — 4번 주려면 5.32 L가 있어야 해서 모자라요.","그래서 3명에게 나누어 줄 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#2','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',2,'mc','auto','물 4 L를 한 명에게 1.3 L씩 3명에게 나누어 주었어요. 나누어 주고 남는 물는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],true,'{"seq":2,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"물 4 L를 한 명에게 1.3 L씩 3명에게 나누어 주었어요. 나누어 주고 남는 물는 몇 L인가요?","options":[{"t":"0.1 L","correct":true},{"t":"0.0 L","mis":"M6-2-u3-X14"},{"t":"3.9 L","mis":"M6-2-u3-X15"},{"t":"1.3 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.3 × 3 = 3.9 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","4 − 3.9 = 0.1 (L)예요."],"variant_rule":{"alt":[{"stem":"물 4 L를 한 명에게 1.33 L씩 3명에게 나누어 주었어요. 나누어 주고 남는 물는 몇 L인가요?","options":[{"t":"0.01 L","correct":true},{"t":"0.0 L","mis":"M6-2-u3-X14"},{"t":"3.99 L","mis":"M6-2-u3-X15"},{"t":"1.33 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.33 × 3 = 3.99 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","4 − 3.99 = 0.01 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#3','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'mc','auto','7.8 ÷ 1.8을 계산기로 계산하니 4.3333…이 나왔어요. 한 친구가 「남는 당근주스는 0.3333… L예요.」라고 말했어요. 바르게 고친 것은 어느 것인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],false,'{"seq":3,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"7.8 ÷ 1.8을 계산기로 계산하니 4.3333…이 나왔어요. 한 친구가 「남는 당근주스는 0.3333… L예요.」라고 말했어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"남는 양은 7.8 − 1.8 × 4 = 0.6 (L)예요","correct":true},{"t":"남는 양은 0.3 L로 반올림해야 해요","mis":"M6-2-u3-X14"},{"t":"남는 양은 1.8 × 4 = 7.2 (L)예요","mis":"M6-2-u3-X15"},{"t":"남는 양은 4.3333… L예요","mis":"M6-2-u3-X15"}],"explanation":["몫의 소수 부분은 남는 당근주스의 양이 아니에요.","나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 7.8 − 7.2 = 0.6 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#4','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'mc','auto','당근주스를 한 명에게 1.8 L씩 4명에게 나누어 주었더니 0.6 L가 남았어요. 처음 당근주스는 몇 L였나요?',ARRAY['M6-2-u3-X15','M6-2-u3-X16']::text[],true,'{"seq":4,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"당근주스를 한 명에게 1.8 L씩 4명에게 나누어 주었더니 0.6 L가 남았어요. 처음 당근주스는 몇 L였나요?","options":[{"t":"7.8 L","correct":true},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"6.6 L","mis":"M6-2-u3-X16"},{"t":"2.4 L","mis":"M6-2-u3-X16"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","처음 양 = 나누어 준 양 + 남는 양이에요.","7.2 + 0.6 = 7.8 (L)예요."],"variant_rule":{"alt":[{"stem":"당근주스를 한 명에게 1.4 L씩 7명에게 나누어 주었더니 0.4 L가 남았어요. 처음 당근주스는 몇 L였나요?","options":[{"t":"10.2 L","correct":true},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"9.4 L","mis":"M6-2-u3-X16"},{"t":"1.8 L","mis":"M6-2-u3-X16"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","처음 양 = 나누어 준 양 + 남는 양이에요.","9.8 + 0.4 = 10.2 (L)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#5','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'mc','auto','물 4 L를 한 명에게 1.3 L씩 나누어 주면 몇 명에게 주고 몇 L가 남나요?',ARRAY['M6-2-u3-X14','M6-2-u3-X21','M6-2-u3-X13']::text[],false,'{"seq":5,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"물 4 L를 한 명에게 1.3 L씩 나누어 주면 몇 명에게 주고 몇 L가 남나요?","options":[{"t":"3명, 0.1 L","correct":true},{"t":"3명, 0.07 L","mis":"M6-2-u3-X14"},{"t":"3.07명, 0 L","mis":"M6-2-u3-X21"},{"t":"4명, 0 L","mis":"M6-2-u3-X13"}],"explanation":["4 ÷ 1.3 = 3.07…이므로 3명이에요.","나누어 준 양은 1.3 × 3 = 3.9 (L)예요.","남는 양은 4 − 3.9 = 0.1 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#6','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'mc','auto','물 4 L를 3명에게 한 명당 1 L씩, 1.3 L씩, 1.33 L씩 나누어 줄 때 남는 물의 양을 차례로 쓴 것은 어느 것인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15','M6-2-u3-X23']::text[],false,'{"seq":6,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"물 4 L를 3명에게 한 명당 1 L씩, 1.3 L씩, 1.33 L씩 나누어 줄 때 남는 물의 양을 차례로 쓴 것은 어느 것인가요?","options":[{"t":"1 L, 0.1 L, 0.01 L","correct":true},{"t":"1 L, 0.3 L, 0.33 L","mis":"M6-2-u3-X14"},{"t":"3 L, 3.9 L, 3.99 L","mis":"M6-2-u3-X15"},{"t":"0 L, 0 L, 0 L","mis":"M6-2-u3-X23"}],"explanation":["1 × 3 = 3이므로 4 − 3 = 1 (L)가 남아요.","1.3 × 3 = 3.9이므로 4 − 3.9 = 0.1 (L)가 남아요.","1.33 × 3 = 3.99이므로 4 − 3.99 = 0.01 (L)가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#7','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',3,'ox','auto','4 ÷ 3에서 몫은 1이고 나머지는 1이라고 해도 되고, 몫은 1.3이고 나머지는 0.1이라고 해도 돼요.',ARRAY['M6-2-u3-X23']::text[],false,'{"seq":7,"concept":"M6-2-u3-C8","difficulty":3,"kind":"ox","stem":"4 ÷ 3에서 몫은 1이고 나머지는 1이라고 해도 되고, 몫은 1.3이고 나머지는 0.1이라고 해도 돼요.","answer":"X","reason_options":[{"t":"1, 1.3은 몫을 필요한 만큼만 구한 값이고 1, 0.1은 나누어 주고 남는 양이기 때문에","correct":true},{"t":"어디까지 구하느냐에 따라 몫과 나머지가 여러 가지이기 때문에","mis":"M6-2-u3-X23"}],"mis":"M6-2-u3-X23","explanation":["4 ÷ 3의 몫은 나눗셈을 한 값 하나예요.","1, 1.3은 몫을 필요한 만큼만 구한 값이에요.","소수의 나눗셈에서는 「나머지」 대신 「나누어 주고 남는 양」이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#8','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',4,'mc','auto','물 4 L를 3명에게 한 명당 1.33 L씩 나누어 주었어요. 남는 물은 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],false,'{"seq":8,"concept":"M6-2-u3-C8","difficulty":4,"kind":"mc","stem":"물 4 L를 3명에게 한 명당 1.33 L씩 나누어 주었어요. 남는 물은 몇 L인가요?","options":[{"t":"0.01 L","correct":true},{"t":"0.1 L","mis":"M6-2-u3-X14"},{"t":"0.33 L","mis":"M6-2-u3-X14"},{"t":"3.99 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 물은 1.33 × 3 = 3.99 (L)예요.","남는 물은 처음 양에서 나누어 준 양을 빼요.","4 − 3.99 = 0.01 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#9','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',4,'essay','teacher','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 당근주스의 양을 구하는 과정을 쓰고, 「4.3명」이라고 답하면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 당근주스의 양을 구하는 과정을 쓰고, 「4.3명」이라고 답하면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 7.8 ÷ 1.8 = 4.333…이므로 나누어 줄 수 있는 사람은 4명이다. 나누어 준 양은 1.8 × 4 = 7.2 (L)이고 남는 양은 7.8 − 7.2 = 0.6 (L)이다. 사람 수는 하나, 둘로 세는 수라 4.3명처럼 나타낼 수 없고, 몫의 소수 부분은 남는 양도 아니다.","scoring_points":["4명을 구했는가","남는 양 0.6 L를 구했는가","사람 수는 소수로 나타낼 수 없다는 까닭을 썼는가"]},"explanation":["7.8 ÷ 1.8 = 4.333… — 4명이에요.","7.8 − 1.8 × 4 = 0.6 (L)예요.","사람 수는 자연수로 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_L08_challenge#10','math',6,2,'u3','L08','tb_g6_2_math_u3_L08_challenge','lesson_challenge','M6-2-u3-C8',4,'essay','teacher','당근주스 문제의 조건을 바꾸어 「당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 합니다.」라는 문제를 만들었어요. 나누어 줄 수 있는 사람 수와 남는 양을 구하고 바르게 구했는지 확인해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"당근주스 문제의 조건을 바꾸어 「당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 합니다.」라는 문제를 만들었어요. 나누어 줄 수 있는 사람 수와 남는 양을 구하고 바르게 구했는지 확인해 보세요.","answer_guide":{"answer":"예: 10.2 ÷ 1.4 = 7.285…이므로 7명에게 나누어 줄 수 있다. 나누어 준 양은 1.4 × 7 = 9.8 (L)이고 남는 양은 10.2 − 9.8 = 0.4 (L)이다. 확인: 9.8 + 0.4 = 10.2 (L)이다.","scoring_points":["7명을 구했는가","남는 양 0.4 L를 구했는가","나누어 준 양 + 남는 양 = 처음 양으로 확인했는가"]},"explanation":["10.2 ÷ 1.4 = 7.285… — 7명이에요.","10.2 − 9.8 = 0.4 (L)예요.","9.8 + 0.4 = 10.2로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#1','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C1',1,'sa','auto','192 ÷ 4 = 48이에요. 이것을 이용하면 19.2 ÷ 0.4의 몫은 얼마인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"192 ÷ 4 = 48이에요. 이것을 이용하면 19.2 ÷ 0.4의 몫은 얼마인가요?","answer":["48"],"explanation":["19.2 ÷ 0.4는 192 ÷ 4의 두 수에 똑같은 수를 곱한 사이예요.","두 수에 같은 수를 곱하면 몫은 그대로예요.","그래서 19.2 ÷ 0.4 = 48이에요."],"asset":{"type":"expr_grid","rows":[["192 ÷ 4","=","48"],["19.2 ÷ 0.4","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#2','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C4',1,'sa','auto','1.92 ÷ 0.04의 몫은 얼마인가요?','{}'::text[],false,'{"seq":2,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"1.92 ÷ 0.04의 몫은 얼마인가요?","answer":["48"],"explanation":["나누는 수 0.04가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","1.92 ÷ 0.04는 192 ÷ 4가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","192 ÷ 4 = 48이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#3','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C3',1,'sa','auto','9.8 ÷ 1.4를 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 98 ÷ 14로 바꾸었어요. 9.8 ÷ 1.4의 몫은 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"9.8 ÷ 1.4를 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 98 ÷ 14로 바꾸었어요. 9.8 ÷ 1.4의 몫은 얼마인가요?","answer":["7"],"explanation":["나누는 수 1.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","9.8 ÷ 1.4는 98 ÷ 14가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","98 ÷ 14 = 7이에요."],"asset":{"type":"ldiv","a":98,"b":14,"hide":["q"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#4','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C4',1,'mc','auto','1.19 ÷ 0.14의 몫은 얼마인가요?',ARRAY['M6-2-u3-X23','M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":4,"concept":"M6-2-u3-C4","difficulty":1,"kind":"mc","stem":"1.19 ÷ 0.14의 몫은 얼마인가요?","options":[{"t":"8.5","correct":true},{"t":"8 … 7","mis":"M6-2-u3-X23"},{"t":"0.85","mis":"M6-2-u3-X03"},{"t":"85","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.14가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","1.19 ÷ 0.14는 119 ÷ 14가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","119 ÷ 14 = 8.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#5','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C5',1,'sa','auto','6.3 ÷ 0.42를 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 630 ÷ 42로 바꾸었어요. 6.3 ÷ 0.42의 몫은 얼마인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"6.3 ÷ 0.42를 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 630 ÷ 42로 바꾸었어요. 6.3 ÷ 0.42의 몫은 얼마인가요?","answer":["15"],"explanation":["나누는 수 0.42가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","6.3 ÷ 0.42는 630 ÷ 42가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","630 ÷ 42 = 15예요."],"asset":{"type":"ldiv","a":630,"b":42,"hide":["q"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#6','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C6',1,'sa','auto','91 ÷ 3.5의 몫은 얼마인가요?','{}'::text[],false,'{"seq":6,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"91 ÷ 3.5의 몫은 얼마인가요?","answer":["26"],"explanation":["91은 91.0과 같아요 — 나누는 수 3.5가 자연수가 되도록 두 수의 소수점을 한 칸씩 옮기고 빈 자리는 0으로 채워요.","91 ÷ 3.5는 910 ÷ 35가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","910 ÷ 35 = 26이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#7','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C7',1,'mc','auto','11 ÷ 3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],false,'{"seq":7,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"11 ÷ 3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.7","correct":true},{"t":"3.6","mis":"M6-2-u3-X11"},{"t":"3.67","mis":"M6-2-u3-X12"},{"t":"4","mis":"M6-2-u3-X12"}],"explanation":["11 ÷ 3 = 3.666…이에요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 6이므로 올려요 — 3.7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#8','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C7',1,'mc','auto','4.3 ÷ 1.7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],false,'{"seq":8,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"4.3 ÷ 1.7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.53","correct":true},{"t":"2.52","mis":"M6-2-u3-X11"},{"t":"2.529","mis":"M6-2-u3-X12"},{"t":"2.5","mis":"M6-2-u3-X12"}],"explanation":["4.3 ÷ 1.7 = 2.5294…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 9이므로 올려요 — 2.53이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#9','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C5',2,'sa','auto','빈칸에 알맞은 수를 구해요. 9.15를 0.5로 나누고, 그 몫을 다시 0.3으로 나누면 얼마인가요?','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C5","difficulty":2,"kind":"sa","stem":"빈칸에 알맞은 수를 구해요. 9.15를 0.5로 나누고, 그 몫을 다시 0.3으로 나누면 얼마인가요?","answer":["61"],"explanation":["9.15 ÷ 0.5 = 91.5 ÷ 5 = 18.3이에요.","18.3 ÷ 0.3 = 183 ÷ 3이에요.","183 ÷ 3 = 61이에요."],"asset":{"type":"expr_grid","rows":[["9.15 ÷ 0.5","=","18.3"],["18.3 ÷ 0.3","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#10','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C3',2,'mc','auto','빵을 만드는 데 밀가루 1.18 kg과 설탕 0.2 kg이 필요해요. 필요한 밀가루의 무게는 설탕의 무게의 몇 배인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],false,'{"seq":10,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"빵을 만드는 데 밀가루 1.18 kg과 설탕 0.2 kg이 필요해요. 필요한 밀가루의 무게는 설탕의 무게의 몇 배인가요?","options":[{"t":"5.9배","correct":true},{"t":"0.59배","mis":"M6-2-u3-X03"},{"t":"59배","mis":"M6-2-u3-X04"},{"t":"0.98배","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 1.18 ÷ 0.2로 구해요.","0.2가 자연수가 되도록 한 칸씩 옮기면 11.8 ÷ 2예요.","11.8 ÷ 2 = 5.9 — 5.9배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#11','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C3',2,'mc','auto','넓이가 19.8 cm²인 직사각형이 있어요. 이 직사각형의 세로가 3.6 cm일 때 가로는 몇 cm인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],false,'{"seq":11,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"넓이가 19.8 cm²인 직사각형이 있어요. 이 직사각형의 세로가 3.6 cm일 때 가로는 몇 cm인가요?","options":[{"t":"5.5 cm","correct":true},{"t":"0.55 cm","mis":"M6-2-u3-X03"},{"t":"55 cm","mis":"M6-2-u3-X04"},{"t":"71.28 cm","mis":"M6-2-u3-X16"}],"explanation":["(직사각형의 넓이) = (가로) × (세로)이므로 가로 = 넓이 ÷ 세로예요.","19.8 ÷ 3.6 = 198 ÷ 36이에요.","198 ÷ 36 = 5.5 — 5.5 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#12','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C6',2,'sa','auto','바삭바삭 과자 집 찾아가기의 출발점 카드예요. 52 ÷ 1.3의 몫은 얼마인가요?','{}'::text[],false,'{"seq":12,"concept":"M6-2-u3-C6","difficulty":2,"kind":"sa","stem":"바삭바삭 과자 집 찾아가기의 출발점 카드예요. 52 ÷ 1.3의 몫은 얼마인가요?","answer":["40"],"explanation":["52는 52.0과 같아요 — 나누는 수 1.3이 자연수가 되도록 두 수의 소수점을 한 칸씩 옮기고 빈 자리는 0으로 채워요.","52 ÷ 1.3은 520 ÷ 13이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","520 ÷ 13 = 40이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#13','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C3',2,'mc','auto','바삭바삭 과자 집 찾아가기의 과자 카드예요. 13.8 ÷ 1.5의 몫은 얼마인가요?',ARRAY['M6-2-u3-X23','M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":13,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"바삭바삭 과자 집 찾아가기의 과자 카드예요. 13.8 ÷ 1.5의 몫은 얼마인가요?","options":[{"t":"9.2","correct":true},{"t":"9 … 3","mis":"M6-2-u3-X23"},{"t":"0.92","mis":"M6-2-u3-X03"},{"t":"92","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 1.5가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","13.8 ÷ 1.5는 138 ÷ 15가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","138 ÷ 15 = 9.2 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#14','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C8',2,'sa','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],false,'{"seq":14,"concept":"M6-2-u3-C8","difficulty":2,"kind":"sa","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["4"],"explanation":["7.8 ÷ 1.8을 계산하면 4.333…이에요.","1.8 L씩 4번 주면 7.2 L — 5번 주려면 9 L가 있어야 해서 모자라요.","그래서 4명에게 나누어 줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#15','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C8',2,'mc','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],false,'{"seq":15,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 4명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.6 L","correct":true},{"t":"0.3 L","mis":"M6-2-u3-X14"},{"t":"7.2 L","mis":"M6-2-u3-X15"},{"t":"1.8 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","7.8 − 7.2 = 0.6 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#16','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C1',2,'mc','auto','192 ÷ 4와 몫이 다른 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X19']::text[],false,'{"seq":16,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"192 ÷ 4와 몫이 다른 나눗셈은 어느 것인가요?","options":[{"t":"19.2 ÷ 4","correct":true},{"t":"19.2 ÷ 0.4","mis":"M6-2-u3-X19"},{"t":"1.92 ÷ 0.04","mis":"M6-2-u3-X19"},{"t":"1920 ÷ 40","mis":"M6-2-u3-X19"}],"explanation":["19.2 ÷ 0.4, 1.92 ÷ 0.04, 1920 ÷ 40은 192 ÷ 4의 두 수에 똑같은 수를 곱한 식이에요.","세 식의 몫은 모두 48이에요.","19.2 ÷ 4는 나누어지는 수만 바뀌어 몫이 4.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#17','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C3',3,'mc','auto','54 ÷ 1.5를 세로로 계산하고 몫을 3.6이라고 썼어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X23','M6-2-u3-X11']::text[],false,'{"seq":17,"concept":"M6-2-u3-C3","difficulty":3,"kind":"mc","stem":"54 ÷ 1.5를 세로로 계산하고 몫을 3.6이라고 썼어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"몫의 소수점의 위치를 잘못 찍어서","correct":true},{"t":"나누는 수만 옮겨서","mis":"M6-2-u3-X01"},{"t":"0을 내리지 않아서","mis":"M6-2-u3-X23"},{"t":"반올림을 하지 않아서","mis":"M6-2-u3-X11"}],"explanation":["54를 54.0으로 보고 두 수를 한 칸씩 옮기면 540 ÷ 15예요.","540 ÷ 15 = 36이에요.","3.6은 몫의 소수점을 잘못 찍은 값이에요 — 바른 몫은 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#18','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C5',3,'mc','auto','수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □.□□의 몫이 가장 작은 나눗셈을 만들려고 해요. □.□□에 알맞은 수는 어느 것인가요?',ARRAY['M6-2-u3-X22','M6-2-u3-X20']::text[],false,'{"seq":18,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □.□□의 몫이 가장 작은 나눗셈을 만들려고 해요. □.□□에 알맞은 수는 어느 것인가요?","options":[{"t":"6.52","correct":true},{"t":"2.56","mis":"M6-2-u3-X22"},{"t":"2.65","mis":"M6-2-u3-X22"},{"t":"6.25","mis":"M6-2-u3-X20"}],"explanation":["나누어지는 수가 같으면 나누는 수가 클수록 몫이 작아요.","만들 수 있는 □.□□ 가운데 가장 큰 수는 6.52예요.","16.3 ÷ 6.52 = 1630 ÷ 652 = 2.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#19','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C6',3,'ox','auto','16 ÷ 0.25의 몫은 16보다 작아요.',ARRAY['M6-2-u3-X09']::text[],false,'{"seq":19,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"16 ÷ 0.25의 몫은 16보다 작아요.","answer":"X","reason_options":[{"t":"0.25는 1보다 작아서 16 안에 16번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["16 ÷ 0.25 = 64예요.","64는 16보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#20','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C2',3,'mc','auto','24.15 ÷ 1.05를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],false,'{"seq":20,"concept":"M6-2-u3-C2","difficulty":3,"kind":"mc","stem":"24.15 ÷ 1.05를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨2415/100⟩ ÷ ⟨105/100⟩","correct":true},{"t":"⟨2415/100⟩ ÷ 1.05","mis":"M6-2-u3-X06"},{"t":"⟨2415/100⟩ ÷ ⟨10/10⟩","mis":"M6-2-u3-X05"},{"t":"24.15 ÷ ⟨105/100⟩","mis":"M6-2-u3-X06"}],"explanation":["24.15는 ⟨2415/100⟩, 1.05는 ⟨105/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨2415/100⟩ ÷ ⟨105/100⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#21','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C7',3,'mc','auto','집에서 호수까지의 거리는 2 km, 집에서 영화관까지의 거리는 0.7 km예요. 집에서 호수까지의 거리는 집에서 영화관까지의 거리의 몇 배인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12','M6-2-u3-X17']::text[],false,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"집에서 호수까지의 거리는 2 km, 집에서 영화관까지의 거리는 0.7 km예요. 집에서 호수까지의 거리는 집에서 영화관까지의 거리의 몇 배인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.86배","correct":true},{"t":"2.85배","mis":"M6-2-u3-X11"},{"t":"2.9배","mis":"M6-2-u3-X12"},{"t":"0.35배","mis":"M6-2-u3-X17"}],"explanation":["2 ÷ 0.7 = 20 ÷ 7 = 2.857…이에요.","소수 셋째 자리 숫자 7을 보고 올려요.","2.86배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#22','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C8',3,'mc','auto','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 양은 어느 것인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X13','M6-2-u3-X21']::text[],false,'{"seq":22,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 양은 어느 것인가요?","options":[{"t":"4명, 0.6 L","correct":true},{"t":"4명, 0.3 L","mis":"M6-2-u3-X14"},{"t":"5명, 0 L","mis":"M6-2-u3-X13"},{"t":"4.3명, 0 L","mis":"M6-2-u3-X21"}],"explanation":["7.8 ÷ 1.8 = 4.333…이므로 4명이에요.","나누어 준 양은 1.8 × 4 = 7.2 (L)예요.","남는 양은 7.8 − 7.2 = 0.6 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#23','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C3',4,'essay','teacher','54 ÷ 1.5를 세로로 계산하고 몫을 3.6이라고 쓴 친구가 있어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M6-2-u3-C3","difficulty":4,"kind":"essay","stem":"54 ÷ 1.5를 세로로 계산하고 몫을 3.6이라고 쓴 친구가 있어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 소수점을 옮겨 540 ÷ 15로 계산했는데 몫의 소수점을 옮긴 위치가 아닌 곳에 찍었다. 몫의 소수점은 옮긴 소수점의 위치에 맞추어 찍어야 하므로 540 ÷ 15 = 36, 바른 몫은 36이다.","scoring_points":["몫의 소수점 위치가 잘못되었음을 썼는가","540 ÷ 15로 바꾸었는가","36을 구했는가"]},"explanation":["54 ÷ 1.5 = 540 ÷ 15예요.","540 ÷ 15 = 36이에요.","몫의 소수점은 옮긴 자리에 맞추어 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#24','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C8',4,'essay','teacher','당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 당근주스의 양을 구하고, 바르게 구했는지 확인해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"당근주스 7.8 L를 한 명에게 1.8 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 당근주스의 양을 구하고, 바르게 구했는지 확인해 보세요.","answer_guide":{"answer":"예: 7.8 ÷ 1.8 = 4.333…이므로 4명에게 나누어 줄 수 있다. 1.8 × 4 = 7.2 (L)이므로 남는 양은 7.8 − 7.2 = 0.6 (L)이다. 확인: 7.2 + 0.6 = 7.8 (L)이다.","scoring_points":["4명을 구했는가","0.6 L를 구했는가","나누어 준 양 + 남는 양으로 확인했는가"]},"explanation":["7.8 ÷ 1.8 = 4.333… — 4명이에요.","7.8 − 7.2 = 0.6 (L)예요.","7.2 + 0.6 = 7.8로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_a#25','math',6,2,'u3','','tb_g6_2_math_u3_review_a','unit_review','M6-2-u3-C5',4,'essay','teacher','수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □.□□의 몫이 가장 작은 나눗셈을 만들고 몫을 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"수 카드 2, 5, 6을 한 번씩만 써서 16.3 ÷ □.□□의 몫이 가장 작은 나눗셈을 만들고 몫을 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 나누어지는 수가 같으면 나누는 수가 클수록 몫이 작다. 수 카드로 만들 수 있는 가장 큰 소수 두 자리 수는 6.52이므로 16.3 ÷ 6.52 = 1630 ÷ 652 = 2.5이다.","scoring_points":["나누는 수가 클수록 몫이 작다는 조건을 썼는가","6.52를 만들었는가","2.5를 구했는가"]},"explanation":["나누는 수가 클수록 몫이 작아요.","가장 큰 □.□□는 6.52예요.","16.3 ÷ 6.52 = 2.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#1','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C1',1,'sa','auto','486 ÷ 6 = 81이에요. 이것을 이용하면 48.6 ÷ 0.6의 몫은 얼마인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"486 ÷ 6 = 81이에요. 이것을 이용하면 48.6 ÷ 0.6의 몫은 얼마인가요?","answer":["81"],"explanation":["48.6 ÷ 0.6은 486 ÷ 6의 두 수에 똑같은 수를 곱한 사이예요.","두 수에 같은 수를 곱하면 몫은 그대로예요.","그래서 48.6 ÷ 0.6 = 81이에요."],"asset":{"type":"expr_grid","rows":[["486 ÷ 6","=","81"],["48.6 ÷ 0.6","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#2','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C4',1,'sa','auto','4.86 ÷ 0.06의 몫은 얼마인가요?','{}'::text[],false,'{"seq":2,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"4.86 ÷ 0.06의 몫은 얼마인가요?","answer":["81"],"explanation":["나누는 수 0.06이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","4.86 ÷ 0.06은 486 ÷ 6이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","486 ÷ 6 = 81이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#3','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C3',1,'sa','auto','15.2 ÷ 1.9를 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 152 ÷ 19로 바꾸었어요. 15.2 ÷ 1.9의 몫은 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"15.2 ÷ 1.9를 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 152 ÷ 19로 바꾸었어요. 15.2 ÷ 1.9의 몫은 얼마인가요?","answer":["8"],"explanation":["나누는 수 1.9가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","15.2 ÷ 1.9는 152 ÷ 19가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","152 ÷ 19 = 8이에요."],"asset":{"type":"ldiv","a":152,"b":19,"hide":["q"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#4','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C4',1,'mc','auto','0.78 ÷ 0.12의 몫은 얼마인가요?',ARRAY['M6-2-u3-X23','M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":4,"concept":"M6-2-u3-C4","difficulty":1,"kind":"mc","stem":"0.78 ÷ 0.12의 몫은 얼마인가요?","options":[{"t":"6.5","correct":true},{"t":"6 … 6","mis":"M6-2-u3-X23"},{"t":"0.65","mis":"M6-2-u3-X03"},{"t":"65","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.12가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.78 ÷ 0.12는 78 ÷ 12가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","78 ÷ 12 = 6.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#5','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C5',1,'sa','auto','7.2 ÷ 0.08을 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 720 ÷ 8로 바꾸었어요. 7.2 ÷ 0.08의 몫은 얼마인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"7.2 ÷ 0.08을 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 720 ÷ 8로 바꾸었어요. 7.2 ÷ 0.08의 몫은 얼마인가요?","answer":["90"],"explanation":["나누는 수 0.08이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","7.2 ÷ 0.08은 720 ÷ 8이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","720 ÷ 8 = 90이에요."],"asset":{"type":"ldiv","a":720,"b":8,"hide":["q"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#6','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C6',1,'sa','auto','9 ÷ 2.25의 몫은 얼마인가요?','{}'::text[],false,'{"seq":6,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"9 ÷ 2.25의 몫은 얼마인가요?","answer":["4"],"explanation":["9는 9.00과 같아요 — 나누는 수 2.25가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 2.25는 900 ÷ 225가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","900 ÷ 225 = 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#7','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C7',1,'mc','auto','16 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],false,'{"seq":7,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"16 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.3","correct":true},{"t":"2.2","mis":"M6-2-u3-X11"},{"t":"2.29","mis":"M6-2-u3-X12"},{"t":"2","mis":"M6-2-u3-X12"}],"explanation":["16 ÷ 7 = 2.285…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 8이므로 올려요 — 2.3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#8','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C7',1,'mc','auto','40 ÷ 22의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],false,'{"seq":8,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"40 ÷ 22의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.82","correct":true},{"t":"1.81","mis":"M6-2-u3-X11"},{"t":"1.818","mis":"M6-2-u3-X12"},{"t":"1.8","mis":"M6-2-u3-X12"}],"explanation":["40 ÷ 22 = 1.8181…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 8이므로 올려요 — 1.82예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#9','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C6',2,'sa','auto','빈칸에 알맞은 수를 구해요. 48을 1.2로 나누고, 그 몫을 다시 2.5로 나누면 얼마인가요?','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C6","difficulty":2,"kind":"sa","stem":"빈칸에 알맞은 수를 구해요. 48을 1.2로 나누고, 그 몫을 다시 2.5로 나누면 얼마인가요?","answer":["16"],"explanation":["48 ÷ 1.2 = 480 ÷ 12 = 40이에요.","40 ÷ 2.5 = 400 ÷ 25예요.","400 ÷ 25 = 16이에요."],"asset":{"type":"expr_grid","rows":[["48 ÷ 1.2","=","40"],["40 ÷ 2.5","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#10','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C3',2,'mc','auto','붓의 길이는 22.8 cm이고 연필의 길이의 2.4배예요. 연필의 길이는 몇 cm인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],false,'{"seq":10,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"붓의 길이는 22.8 cm이고 연필의 길이의 2.4배예요. 연필의 길이는 몇 cm인가요?","options":[{"t":"9.5 cm","correct":true},{"t":"0.95 cm","mis":"M6-2-u3-X03"},{"t":"95 cm","mis":"M6-2-u3-X04"},{"t":"54.72 cm","mis":"M6-2-u3-X16"}],"explanation":["연필의 길이 × 2.4 = 22.8이에요.","연필의 길이는 22.8 ÷ 2.4 = 228 ÷ 24예요.","228 ÷ 24 = 9.5 — 9.5 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#11','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C5',2,'mc','auto','넓이가 49.5 cm²인 평행사변형의 밑변의 길이가 8.25 cm일 때 높이는 몇 cm인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],false,'{"seq":11,"concept":"M6-2-u3-C5","difficulty":2,"kind":"mc","stem":"넓이가 49.5 cm²인 평행사변형의 밑변의 길이가 8.25 cm일 때 높이는 몇 cm인가요?","options":[{"t":"6 cm","correct":true},{"t":"0.6 cm","mis":"M6-2-u3-X03"},{"t":"60 cm","mis":"M6-2-u3-X04"},{"t":"41.25 cm","mis":"M6-2-u3-X16"}],"explanation":["높이 = 넓이 ÷ 밑변의 길이예요.","49.5 ÷ 8.25 = 4950 ÷ 825예요 — 빈 자리는 0으로.","4950 ÷ 825 = 6 — 6 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#12','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C3',2,'sa','auto','바삭바삭 과자 집 찾아가기의 과자 카드예요. 15.4 ÷ 0.2의 몫은 얼마인가요?','{}'::text[],false,'{"seq":12,"concept":"M6-2-u3-C3","difficulty":2,"kind":"sa","stem":"바삭바삭 과자 집 찾아가기의 과자 카드예요. 15.4 ÷ 0.2의 몫은 얼마인가요?","answer":["77"],"explanation":["나누는 수 0.2가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","15.4 ÷ 0.2는 154 ÷ 2가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","154 ÷ 2 = 77이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#13','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C3',2,'mc','auto','바삭바삭 과자 집 찾아가기의 과자 카드예요. 3.12 ÷ 0.4의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":13,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"바삭바삭 과자 집 찾아가기의 과자 카드예요. 3.12 ÷ 0.4의 몫은 얼마인가요?","options":[{"t":"7.8","correct":true},{"t":"0.78","mis":"M6-2-u3-X03"},{"t":"78","mis":"M6-2-u3-X04"},{"t":"0.078","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 0.4가 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","3.12 ÷ 0.4는 31.2 ÷ 4가 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","31.2 ÷ 4 = 7.8 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#14','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C8',2,'sa','auto','당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],false,'{"seq":14,"concept":"M6-2-u3-C8","difficulty":2,"kind":"sa","stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["7"],"explanation":["10.2 ÷ 1.4를 계산하면 7.285…예요.","1.4 L씩 7번 주면 9.8 L — 8번 주려면 11.2 L가 있어야 해서 모자라요.","그래서 7명에게 나누어 줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#15','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C8',2,'mc','auto','당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],false,'{"seq":15,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 7명에게 나누어 주었어요. 나누어 주고 남는 당근주스는 몇 L인가요?","options":[{"t":"0.4 L","correct":true},{"t":"0.2 L","mis":"M6-2-u3-X14"},{"t":"9.8 L","mis":"M6-2-u3-X15"},{"t":"1.4 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","10.2 − 9.8 = 0.4 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#16','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C1',2,'mc','auto','12.42 ÷ 5.4와 몫이 같은 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],false,'{"seq":16,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"12.42 ÷ 5.4와 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"124.2 ÷ 54","correct":true},{"t":"12.42 ÷ 0.54","mis":"M6-2-u3-X01"},{"t":"1242 ÷ 54","mis":"M6-2-u3-X02"},{"t":"124.2 ÷ 5.4","mis":"M6-2-u3-X01"}],"explanation":["124.2 ÷ 54는 12.42 ÷ 5.4의 두 수에 똑같이 10을 곱한 식이에요.","두 수에 같은 수를 곱하면 몫은 그대로예요.","몫은 모두 2.3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#17','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C6',3,'mc','auto','52 ÷ 0.8을 계산하고 몫을 6.5라고 썼어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M6-2-u3-X04','M6-2-u3-X23','M6-2-u3-X11']::text[],false,'{"seq":17,"concept":"M6-2-u3-C6","difficulty":3,"kind":"mc","stem":"52 ÷ 0.8을 계산하고 몫을 6.5라고 썼어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"52의 소수점은 옮기지 않고 0.8만 8로 바꾸어서","correct":true},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"},{"t":"0을 내리지 않아서","mis":"M6-2-u3-X23"},{"t":"반올림을 하지 않아서","mis":"M6-2-u3-X11"}],"explanation":["6.5는 52 ÷ 8의 몫이에요.","52도 52.0으로 보고 한 칸 옮겨 520 ÷ 8이에요.","바른 몫은 65예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#18','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C5',3,'mc','auto','수 카드 4, 8, 1을 한 번씩만 써서 7.4 ÷ □.□의 몫이 가장 큰 나눗셈을 만들려고 해요. □.□에 알맞은 수는 어느 것인가요?',ARRAY['M6-2-u3-X22','M6-2-u3-X20']::text[],false,'{"seq":18,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"수 카드 4, 8, 1을 한 번씩만 써서 7.4 ÷ □.□의 몫이 가장 큰 나눗셈을 만들려고 해요. □.□에 알맞은 수는 어느 것인가요?","options":[{"t":"1.4","correct":true},{"t":"8.4","mis":"M6-2-u3-X22"},{"t":"8.1","mis":"M6-2-u3-X22"},{"t":"1.8","mis":"M6-2-u3-X20"}],"explanation":["나누어지는 수가 같으면 나누는 수가 작을수록 몫이 커요.","수 카드로 만들 수 있는 □.□ 가운데 가장 작은 수는 1.4예요.","그래서 □.□는 1.4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#19','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C6',3,'ox','auto','36 ÷ 0.6의 몫은 36보다 작아요.',ARRAY['M6-2-u3-X09']::text[],false,'{"seq":19,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"36 ÷ 0.6의 몫은 36보다 작아요.","answer":"X","reason_options":[{"t":"0.6은 1보다 작아서 36 안에 36번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["36 ÷ 0.6 = 60이에요.","60은 36보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#20','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C2',3,'mc','auto','1.56 ÷ 0.39를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],false,'{"seq":20,"concept":"M6-2-u3-C2","difficulty":3,"kind":"mc","stem":"1.56 ÷ 0.39를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨156/100⟩ ÷ ⟨39/100⟩","correct":true},{"t":"⟨156/100⟩ ÷ 0.39","mis":"M6-2-u3-X06"},{"t":"⟨156/100⟩ ÷ ⟨3/10⟩","mis":"M6-2-u3-X05"},{"t":"1.56 ÷ ⟨39/100⟩","mis":"M6-2-u3-X06"}],"explanation":["1.56은 ⟨156/100⟩, 0.39는 ⟨39/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨156/100⟩ ÷ ⟨39/100⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#21','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C7',3,'mc','auto','하연이네 집에 쌀은 43 kg, 보리는 6 kg 있어요. 쌀의 양은 보리의 양의 몇 배인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12','M6-2-u3-X17']::text[],false,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"하연이네 집에 쌀은 43 kg, 보리는 6 kg 있어요. 쌀의 양은 보리의 양의 몇 배인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"7.17배","correct":true},{"t":"7.16배","mis":"M6-2-u3-X11"},{"t":"7.2배","mis":"M6-2-u3-X12"},{"t":"0.14배","mis":"M6-2-u3-X17"}],"explanation":["43 ÷ 6 = 7.166…이에요.","소수 셋째 자리 숫자 6을 보고 올려요.","7.17배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#22','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C8',3,'mc','auto','당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 양은 어느 것인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X13','M6-2-u3-X21']::text[],false,'{"seq":22,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 양은 어느 것인가요?","options":[{"t":"7명, 0.4 L","correct":true},{"t":"7명, 0.2 L","mis":"M6-2-u3-X14"},{"t":"8명, 0 L","mis":"M6-2-u3-X13"},{"t":"7.2명, 0 L","mis":"M6-2-u3-X21"}],"explanation":["10.2 ÷ 1.4 = 7.285…이므로 7명이에요.","나누어 준 양은 1.4 × 7 = 9.8 (L)예요.","남는 양은 10.2 − 9.8 = 0.4 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#23','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C6',4,'essay','teacher','52 ÷ 0.8을 계산하고 몫을 6.5라고 쓴 친구가 있어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M6-2-u3-C6","difficulty":4,"kind":"essay","stem":"52 ÷ 0.8을 계산하고 몫을 6.5라고 쓴 친구가 있어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 0.8만 8로 바꾸고 52는 옮기지 않아 52 ÷ 8 = 6.5를 계산했다. 52를 52.0으로 보고 똑같이 한 칸 옮겨 520 ÷ 8 = 65가 바른 몫이다.","scoring_points":["52를 옮기지 않은 잘못을 찾았는가","520 ÷ 8로 바꾸었는가","65를 구했는가"]},"explanation":["6.5는 52 ÷ 8의 몫이에요.","520 ÷ 8 = 65예요.","두 수의 소수점은 똑같이 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#24','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C8',4,'essay','teacher','당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 당근주스의 양을 구하고, 바르게 구했는지 확인해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"당근주스 10.2 L를 한 명에게 1.4 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 당근주스의 양을 구하고, 바르게 구했는지 확인해 보세요.","answer_guide":{"answer":"예: 10.2 ÷ 1.4 = 7.285…이므로 7명에게 나누어 줄 수 있다. 1.4 × 7 = 9.8 (L)이므로 남는 양은 10.2 − 9.8 = 0.4 (L)이다. 확인: 9.8 + 0.4 = 10.2 (L)이다.","scoring_points":["7명을 구했는가","0.4 L를 구했는가","나누어 준 양 + 남는 양으로 확인했는가"]},"explanation":["10.2 ÷ 1.4 = 7.285… — 7명이에요.","10.2 − 9.8 = 0.4 (L)예요.","9.8 + 0.4 = 10.2로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_b#25','math',6,2,'u3','','tb_g6_2_math_u3_review_b','unit_review','M6-2-u3-C5',4,'essay','teacher','수 카드 2, 4, 5, 8을 한 번씩만 써서 몫이 가장 큰 (소수 한 자리 수) ÷ (소수 한 자리 수)를 만들고, 몫을 반올림하여 소수 첫째 자리까지 나타내는 과정을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"수 카드 2, 4, 5, 8을 한 번씩만 써서 몫이 가장 큰 (소수 한 자리 수) ÷ (소수 한 자리 수)를 만들고, 몫을 반올림하여 소수 첫째 자리까지 나타내는 과정을 써 보세요.","answer_guide":{"answer":"예: 몫이 가장 크려면 나누어지는 수는 가장 크게, 나누는 수는 가장 작게 만든다. 2 < 4 < 5 < 8이므로 8.5 ÷ 2.4이고, 8.5 ÷ 2.4 = 3.54…이므로 소수 첫째 자리까지 나타내면 3.5이다.","scoring_points":["8.5 ÷ 2.4를 만들었는가","3.54…를 구했는가","3.5로 나타냈는가"]},"explanation":["가장 큰 수 8.5, 가장 작은 수 2.4예요.","8.5 ÷ 2.4 = 3.541…이에요.","소수 둘째 자리 숫자 4를 버려 3.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#1','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C1',1,'sa','auto','728 ÷ 4 = 182예요. 이것을 이용하면 72.8 ÷ 0.4의 몫은 얼마인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"728 ÷ 4 = 182예요. 이것을 이용하면 72.8 ÷ 0.4의 몫은 얼마인가요?","answer":["182"],"explanation":["72.8 ÷ 0.4는 728 ÷ 4의 두 수에 똑같은 수를 곱한 사이예요.","두 수에 같은 수를 곱하면 몫은 그대로예요.","그래서 72.8 ÷ 0.4 = 182예요."],"asset":{"type":"expr_grid","rows":[["728 ÷ 4","=","182"],["72.8 ÷ 0.4","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#2','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C4',1,'sa','auto','7.28 ÷ 0.04의 몫은 얼마인가요?','{}'::text[],false,'{"seq":2,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"7.28 ÷ 0.04의 몫은 얼마인가요?","answer":["182"],"explanation":["나누는 수 0.04가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","7.28 ÷ 0.04는 728 ÷ 4가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","728 ÷ 4 = 182예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#3','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C3',1,'sa','auto','5.1 ÷ 1.7을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 51 ÷ 17로 바꾸었어요. 5.1 ÷ 1.7의 몫은 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"5.1 ÷ 1.7을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 51 ÷ 17로 바꾸었어요. 5.1 ÷ 1.7의 몫은 얼마인가요?","answer":["3"],"explanation":["나누는 수 1.7이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","5.1 ÷ 1.7은 51 ÷ 17이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","51 ÷ 17 = 3이에요."],"asset":{"type":"ldiv","a":51,"b":17,"hide":["q"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#4','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C4',1,'mc','auto','0.77 ÷ 0.14의 몫은 얼마인가요?',ARRAY['M6-2-u3-X23','M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":4,"concept":"M6-2-u3-C4","difficulty":1,"kind":"mc","stem":"0.77 ÷ 0.14의 몫은 얼마인가요?","options":[{"t":"5.5","correct":true},{"t":"5 … 7","mis":"M6-2-u3-X23"},{"t":"0.55","mis":"M6-2-u3-X03"},{"t":"55","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.14가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.77 ÷ 0.14는 77 ÷ 14가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","77 ÷ 14 = 5.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#5','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',1,'sa','auto','18.3 ÷ 0.3을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 183 ÷ 3으로 바꾸었어요. 18.3 ÷ 0.3의 몫은 얼마인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"18.3 ÷ 0.3을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 183 ÷ 3으로 바꾸었어요. 18.3 ÷ 0.3의 몫은 얼마인가요?","answer":["61"],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","18.3 ÷ 0.3은 183 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","183 ÷ 3 = 61이에요."],"asset":{"type":"ldiv","a":183,"b":3,"hide":["q"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#6','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C6',1,'sa','auto','9 ÷ 0.36의 몫은 얼마인가요?','{}'::text[],false,'{"seq":6,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"9 ÷ 0.36의 몫은 얼마인가요?","answer":["25"],"explanation":["9는 9.00과 같아요 — 나누는 수 0.36이 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","9 ÷ 0.36은 900 ÷ 36이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","900 ÷ 36 = 25예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#7','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C7',1,'mc','auto','17.1 ÷ 2.3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X12']::text[],false,'{"seq":7,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"17.1 ÷ 2.3의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"7.4","correct":true},{"t":"7.43","mis":"M6-2-u3-X12"},{"t":"7","mis":"M6-2-u3-X12"},{"t":"7.434","mis":"M6-2-u3-X12"}],"explanation":["17.1 ÷ 2.3 = 7.434…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 3이므로 버려요 — 7.4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#8','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C7',1,'mc','auto','3.3 ÷ 7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X12']::text[],false,'{"seq":8,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"3.3 ÷ 7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.47","correct":true},{"t":"0.471","mis":"M6-2-u3-X12"},{"t":"0.5","mis":"M6-2-u3-X12"},{"t":"0.4714","mis":"M6-2-u3-X12"}],"explanation":["3.3 ÷ 7 = 0.4714…예요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 1이므로 버려요 — 0.47이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#9','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C6',2,'sa','auto','빈칸에 알맞은 수를 구해요. 96을 1.6으로 나누고, 그 몫을 다시 3.75로 나누면 얼마인가요?','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C6","difficulty":2,"kind":"sa","stem":"빈칸에 알맞은 수를 구해요. 96을 1.6으로 나누고, 그 몫을 다시 3.75로 나누면 얼마인가요?","answer":["16"],"explanation":["96 ÷ 1.6 = 960 ÷ 16 = 60이에요.","60 ÷ 3.75 = 6000 ÷ 375예요.","6000 ÷ 375 = 16이에요."],"asset":{"type":"expr_grid","rows":[["96 ÷ 1.6","=","60"],["60 ÷ 3.75","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#10','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C3',2,'mc','auto','빨간색 테이프의 길이는 7.36 m, 파란색 테이프의 길이는 3.2 m예요. 빨간색 테이프의 길이는 파란색 테이프의 길이의 몇 배인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],false,'{"seq":10,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"빨간색 테이프의 길이는 7.36 m, 파란색 테이프의 길이는 3.2 m예요. 빨간색 테이프의 길이는 파란색 테이프의 길이의 몇 배인가요?","options":[{"t":"2.3배","correct":true},{"t":"0.23배","mis":"M6-2-u3-X03"},{"t":"23배","mis":"M6-2-u3-X04"},{"t":"4.16배","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 7.36 ÷ 3.2로 구해요.","한 칸씩 옮기면 73.6 ÷ 32예요.","73.6 ÷ 32 = 2.3 — 2.3배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#11','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C4',2,'mc','auto','넓이가 4.62 cm²인 직사각형의 가로가 0.66 cm일 때 세로는 몇 cm인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],false,'{"seq":11,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"넓이가 4.62 cm²인 직사각형의 가로가 0.66 cm일 때 세로는 몇 cm인가요?","options":[{"t":"7 cm","correct":true},{"t":"0.7 cm","mis":"M6-2-u3-X03"},{"t":"70 cm","mis":"M6-2-u3-X04"},{"t":"3.96 cm","mis":"M6-2-u3-X16"}],"explanation":["세로 = 넓이 ÷ 가로예요.","4.62 ÷ 0.66 = 462 ÷ 66이에요.","462 ÷ 66 = 7 — 7 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#12','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C4',2,'sa','auto','바삭바삭 과자 집 찾아가기의 과자 카드예요. 0.98 ÷ 0.07의 몫은 얼마인가요?','{}'::text[],false,'{"seq":12,"concept":"M6-2-u3-C4","difficulty":2,"kind":"sa","stem":"바삭바삭 과자 집 찾아가기의 과자 카드예요. 0.98 ÷ 0.07의 몫은 얼마인가요?","answer":["14"],"explanation":["나누는 수 0.07이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.98 ÷ 0.07은 98 ÷ 7이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","98 ÷ 7 = 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#13','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C4',2,'mc','auto','바삭바삭 과자 집 찾아가기의 과자 카드예요. 2.12 ÷ 0.08의 몫은 얼마인가요?',ARRAY['M6-2-u3-X23','M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":13,"concept":"M6-2-u3-C4","difficulty":2,"kind":"mc","stem":"바삭바삭 과자 집 찾아가기의 과자 카드예요. 2.12 ÷ 0.08의 몫은 얼마인가요?","options":[{"t":"26.5","correct":true},{"t":"26 … 4","mis":"M6-2-u3-X23"},{"t":"2.65","mis":"M6-2-u3-X03"},{"t":"265","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.08이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","2.12 ÷ 0.08은 212 ÷ 8이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","212 ÷ 8 = 26.5 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#14','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C8',2,'sa','auto','물 4 L를 한 명에게 1.3 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?','{}'::text[],false,'{"seq":14,"concept":"M6-2-u3-C8","difficulty":2,"kind":"sa","stem":"물 4 L를 한 명에게 1.3 L씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","answer":["3"],"explanation":["4 ÷ 1.3을 계산하면 3.076…이에요.","1.3 L씩 3번 주면 3.9 L — 4번 주려면 5.2 L가 있어야 해서 모자라요.","그래서 3명에게 나누어 줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#15','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C8',2,'mc','auto','물 4 L를 한 명에게 1.3 L씩 3명에게 나누어 주었어요. 나누어 주고 남는 물는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],false,'{"seq":15,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"물 4 L를 한 명에게 1.3 L씩 3명에게 나누어 주었어요. 나누어 주고 남는 물는 몇 L인가요?","options":[{"t":"0.1 L","correct":true},{"t":"0.0 L","mis":"M6-2-u3-X14"},{"t":"3.9 L","mis":"M6-2-u3-X15"},{"t":"1.3 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.3 × 3 = 3.9 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","4 − 3.9 = 0.1 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#16','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C1',2,'mc','auto','30 ÷ 1.2와 몫이 같은 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X08','M6-2-u3-X02','M6-2-u3-X01']::text[],false,'{"seq":16,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"30 ÷ 1.2와 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"300 ÷ 12","correct":true},{"t":"30 ÷ 12","mis":"M6-2-u3-X08"},{"t":"3 ÷ 1200","mis":"M6-2-u3-X02"},{"t":"300 ÷ 1.2","mis":"M6-2-u3-X01"}],"explanation":["300 ÷ 12는 30 ÷ 1.2의 두 수에 똑같이 10을 곱한 식이에요.","두 수에 같은 수를 곱하면 몫은 그대로예요.","몫은 모두 25예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#17','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',3,'mc','auto','3.64 ÷ 2.8을 계산하고 몫을 0.13이라고 썼어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X23','M6-2-u3-X04']::text[],false,'{"seq":17,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"3.64 ÷ 2.8을 계산하고 몫을 0.13이라고 썼어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","correct":true},{"t":"나누는 수만 옮겨서","mis":"M6-2-u3-X01"},{"t":"0을 내리지 않아서","mis":"M6-2-u3-X23"},{"t":"몫의 소수점을 빠뜨려서","mis":"M6-2-u3-X04"}],"explanation":["2.8이 자연수가 되도록 한 칸씩 옮기면 36.4 ÷ 28이에요.","36.4 ÷ 28 = 1.3이에요.","0.13은 1.3보다 10배 작아요 — 바른 몫은 1.3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#18','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',3,'mc','auto','수 카드 2, 4, 5, 8을 한 번씩만 써서 몫이 가장 큰 (소수 한 자리 수) ÷ (소수 한 자리 수)를 만들려고 해요. 알맞은 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X22','M6-2-u3-X20']::text[],false,'{"seq":18,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"수 카드 2, 4, 5, 8을 한 번씩만 써서 몫이 가장 큰 (소수 한 자리 수) ÷ (소수 한 자리 수)를 만들려고 해요. 알맞은 나눗셈은 어느 것인가요?","options":[{"t":"8.5 ÷ 2.4","correct":true},{"t":"2.4 ÷ 8.5","mis":"M6-2-u3-X22"},{"t":"8.5 ÷ 4.2","mis":"M6-2-u3-X22"},{"t":"5.8 ÷ 2.4","mis":"M6-2-u3-X20"}],"explanation":["몫이 가장 크려면 나누어지는 수는 가장 크게, 나누는 수는 가장 작게 만들어요.","가장 큰 수는 8.5, 남은 카드로 만든 가장 작은 수는 2.4예요.","8.5 ÷ 2.4 = 3.54…예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#19','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C6',3,'ox','auto','5 ÷ 0.4의 몫은 5보다 커요.',ARRAY['M6-2-u3-X09']::text[],false,'{"seq":19,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"5 ÷ 0.4의 몫은 5보다 커요.","answer":"O","reason_options":[{"t":"0.4는 1보다 작아서 5 안에 5번보다 더 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["5 ÷ 0.4 = 12.5예요.","12.5는 5보다 커요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#20','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C2',3,'mc','auto','2.58 ÷ 0.43을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],false,'{"seq":20,"concept":"M6-2-u3-C2","difficulty":3,"kind":"mc","stem":"2.58 ÷ 0.43을 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨258/100⟩ ÷ ⟨43/100⟩","correct":true},{"t":"⟨258/100⟩ ÷ 0.43","mis":"M6-2-u3-X06"},{"t":"⟨258/100⟩ ÷ ⟨4/10⟩","mis":"M6-2-u3-X05"},{"t":"2.58 ÷ ⟨43/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.58은 ⟨258/100⟩, 0.43은 ⟨43/100⟩이에요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨258/100⟩ ÷ ⟨43/100⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#21','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C7',3,'mc','auto','집에서 도서관까지 거리는 3.5 km, 집에서 공원까지 거리는 1.7 km예요. 집에서 도서관까지 거리는 집에서 공원까지 거리의 몇 배인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12','M6-2-u3-X17']::text[],false,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"집에서 도서관까지 거리는 3.5 km, 집에서 공원까지 거리는 1.7 km예요. 집에서 도서관까지 거리는 집에서 공원까지 거리의 몇 배인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.06배","correct":true},{"t":"2.05배","mis":"M6-2-u3-X11"},{"t":"2.1배","mis":"M6-2-u3-X12"},{"t":"0.49배","mis":"M6-2-u3-X17"}],"explanation":["3.5 ÷ 1.7 = 2.058…이에요.","소수 셋째 자리 숫자 8을 보고 올려요.","2.06배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#22','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C8',3,'mc','auto','물 4 L를 한 명에게 1.3 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 양은 어느 것인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X13','M6-2-u3-X21']::text[],false,'{"seq":22,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"물 4 L를 한 명에게 1.3 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 양은 어느 것인가요?","options":[{"t":"3명, 0.1 L","correct":true},{"t":"3명, 0.07 L","mis":"M6-2-u3-X14"},{"t":"4명, 0 L","mis":"M6-2-u3-X13"},{"t":"3.07명, 0 L","mis":"M6-2-u3-X21"}],"explanation":["4 ÷ 1.3 = 3.07…이므로 3명이에요.","나누어 준 양은 1.3 × 3 = 3.9 (L)예요.","남는 양은 4 − 3.9 = 0.1 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#23','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',4,'essay','teacher','3.64 ÷ 2.8을 계산하고 몫을 0.13이라고 쓴 친구가 있어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"3.64 ÷ 2.8을 계산하고 몫을 0.13이라고 쓴 친구가 있어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 소수점을 한 칸씩 옮겨 36.4 ÷ 28로 계산했는데 몫의 소수점을 옮긴 자리가 아닌 원래 자리에서 찍었다. 36.4 ÷ 28 = 1.3이 바른 몫이다.","scoring_points":["몫의 소수점 위치가 잘못되었음을 썼는가","36.4 ÷ 28로 바꾸었는가","1.3을 구했는가"]},"explanation":["3.64 ÷ 2.8 = 36.4 ÷ 28이에요.","36.4 ÷ 28 = 1.3이에요.","0.13은 10배 작은 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#24','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C8',4,'essay','teacher','물 4 L를 한 명에게 1.3 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 물의 양을 구하고, 바르게 구했는지 확인해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u3-C8","difficulty":4,"kind":"essay","stem":"물 4 L를 한 명에게 1.3 L씩 나누어 주려고 해요. 나누어 줄 수 있는 사람 수와 남는 물의 양을 구하고, 바르게 구했는지 확인해 보세요.","answer_guide":{"answer":"예: 4 ÷ 1.3 = 3.07…이므로 3명에게 나누어 줄 수 있다. 1.3 × 3 = 3.9 (L)이므로 남는 양은 4 − 3.9 = 0.1 (L)이다. 확인: 3.9 + 0.1 = 4 (L)이다.","scoring_points":["3명을 구했는가","0.1 L를 구했는가","나누어 준 양 + 남는 양으로 확인했는가"]},"explanation":["4 ÷ 1.3 = 3.07… — 3명이에요.","4 − 3.9 = 0.1 (L)예요.","3.9 + 0.1 = 4로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_c#25','math',6,2,'u3','','tb_g6_2_math_u3_review_c','unit_review','M6-2-u3-C5',4,'essay','teacher','9.5 × □ = 30.4예요. □에 알맞은 수를 구하는 과정을 쓰고, 구한 수가 맞는지 확인해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"9.5 × □ = 30.4예요. □에 알맞은 수를 구하는 과정을 쓰고, 구한 수가 맞는지 확인해 보세요.","answer_guide":{"answer":"예: □ = 30.4 ÷ 9.5이다. 두 수의 소수점을 한 칸씩 옮기면 304 ÷ 95 = 3.2이다. 확인: 9.5 × 3.2 = 30.4이다.","scoring_points":["30.4 ÷ 9.5 식을 세웠는가","3.2를 구했는가","곱셈으로 확인했는가"]},"explanation":["□ = 30.4 ÷ 9.5예요.","304 ÷ 95 = 3.2예요.","9.5 × 3.2 = 30.4로 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#1','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C1',1,'sa','auto','63 ÷ 9 = 7이에요. 이것을 이용하면 63 ÷ 0.9의 몫은 얼마인가요?','{}'::text[],false,'{"seq":1,"concept":"M6-2-u3-C1","difficulty":1,"kind":"sa","stem":"63 ÷ 9 = 7이에요. 이것을 이용하면 63 ÷ 0.9의 몫은 얼마인가요?","answer":["70"],"explanation":["63 ÷ 0.9는 63 ÷ 9의 두 수에 똑같은 수를 곱한 사이예요.","두 수에 같은 수를 곱하면 몫은 그대로예요.","그래서 63 ÷ 0.9 = 70이에요."],"asset":{"type":"expr_grid","rows":[["63 ÷ 9","=","7"],["63 ÷ 0.9","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#2','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C4',1,'sa','auto','63 ÷ 0.09의 몫은 얼마인가요?','{}'::text[],false,'{"seq":2,"concept":"M6-2-u3-C4","difficulty":1,"kind":"sa","stem":"63 ÷ 0.09의 몫은 얼마인가요?","answer":["700"],"explanation":["63은 63.00과 같아요 — 나누는 수 0.09가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","63 ÷ 0.09는 6300 ÷ 9가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","6300 ÷ 9 = 700이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#3','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C3',1,'sa','auto','4.2 ÷ 0.3을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 42 ÷ 3으로 바꾸었어요. 4.2 ÷ 0.3의 몫은 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M6-2-u3-C3","difficulty":1,"kind":"sa","stem":"4.2 ÷ 0.3을 세로로 계산하려고 두 수의 소수점을 한 칸씩 옮겨 42 ÷ 3으로 바꾸었어요. 4.2 ÷ 0.3의 몫은 얼마인가요?","answer":["14"],"explanation":["나누는 수 0.3이 자연수가 되도록 두 수의 소수점을 오른쪽으로 한 칸씩 옮겨요.","4.2 ÷ 0.3은 42 ÷ 3이 돼요 — 두 수에 똑같이 10을 곱했으니 몫은 그대로예요.","42 ÷ 3 = 14예요."],"asset":{"type":"ldiv","a":42,"b":3,"hide":["q"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#4','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C4',1,'mc','auto','0.54 ÷ 0.05의 몫은 얼마인가요?',ARRAY['M6-2-u3-X23','M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":4,"concept":"M6-2-u3-C4","difficulty":1,"kind":"mc","stem":"0.54 ÷ 0.05의 몫은 얼마인가요?","options":[{"t":"10.8","correct":true},{"t":"10 … 4","mis":"M6-2-u3-X23"},{"t":"1.08","mis":"M6-2-u3-X03"},{"t":"108","mis":"M6-2-u3-X04"}],"explanation":["나누는 수 0.05가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요.","0.54 ÷ 0.05는 54 ÷ 5가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","54 ÷ 5 = 10.8 — 몫의 소수점은 옮긴 자리에서 올려 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#5','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',1,'sa','auto','4.2 ÷ 0.06을 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 420 ÷ 6으로 바꾸었어요. 4.2 ÷ 0.06의 몫은 얼마인가요?','{}'::text[],false,'{"seq":5,"concept":"M6-2-u3-C5","difficulty":1,"kind":"sa","stem":"4.2 ÷ 0.06을 세로로 계산하려고 두 수의 소수점을 두 칸씩 옮겨 420 ÷ 6으로 바꾸었어요. 4.2 ÷ 0.06의 몫은 얼마인가요?","answer":["70"],"explanation":["나누는 수 0.06이 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","4.2 ÷ 0.06은 420 ÷ 6이 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","420 ÷ 6 = 70이에요."],"asset":{"type":"ldiv","a":420,"b":6,"hide":["q"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#6','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',1,'sa','auto','21 ÷ 0.35의 몫은 얼마인가요?','{}'::text[],false,'{"seq":6,"concept":"M6-2-u3-C6","difficulty":1,"kind":"sa","stem":"21 ÷ 0.35의 몫은 얼마인가요?","answer":["60"],"explanation":["21은 21.00과 같아요 — 나누는 수 0.35가 자연수가 되도록 두 수의 소수점을 두 칸씩 옮기고 빈 자리는 0으로 채워요.","21 ÷ 0.35는 2100 ÷ 35가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","2100 ÷ 35 = 60이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#7','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',1,'mc','auto','4.3 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X12']::text[],false,'{"seq":7,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"4.3 ÷ 7의 몫을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.61","mis":"M6-2-u3-X12"},{"t":"1","mis":"M6-2-u3-X12"},{"t":"0.614","mis":"M6-2-u3-X12"}],"explanation":["4.3 ÷ 7 = 0.614…예요.","소수 첫째 자리까지 나타내려면 소수 둘째 자리 숫자를 봐요.","소수 둘째 자리 숫자가 1이므로 버려요 — 0.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#8','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',1,'mc','auto','2 ÷ 0.7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X11','M6-2-u3-X12']::text[],false,'{"seq":8,"concept":"M6-2-u3-C7","difficulty":1,"kind":"mc","stem":"2 ÷ 0.7의 몫을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"2.86","correct":true},{"t":"2.85","mis":"M6-2-u3-X11"},{"t":"2.857","mis":"M6-2-u3-X12"},{"t":"2.9","mis":"M6-2-u3-X12"}],"explanation":["2 ÷ 0.7 = 2.8571…이에요.","소수 둘째 자리까지 나타내려면 소수 셋째 자리 숫자를 봐요.","소수 셋째 자리 숫자가 7이므로 올려요 — 2.86이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#9','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',2,'sa','auto','1.35 ÷ 0.05 = 27, 13.5 ÷ 0.05 = 270이에요. 135 ÷ 0.05의 몫은 얼마인가요?','{}'::text[],false,'{"seq":9,"concept":"M6-2-u3-C6","difficulty":2,"kind":"sa","stem":"1.35 ÷ 0.05 = 27, 13.5 ÷ 0.05 = 270이에요. 135 ÷ 0.05의 몫은 얼마인가요?","answer":["2700"],"explanation":["나누는 수가 같을 때 나누어지는 수가 10배가 되면 몫도 10배가 돼요.","135는 13.5의 10배예요.","그래서 135 ÷ 0.05 = 2700이에요."],"asset":{"type":"expr_grid","rows":[["1.35 ÷ 0.05","=","27"],["13.5 ÷ 0.05","=","270"],["135 ÷ 0.05","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#10','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C3',2,'mc','auto','양치 컵을 사용하지 않을 때 5.89 L, 사용할 때 0.62 L의 물을 소비해요. 사용하지 않을 때 소비하는 물의 양은 사용할 때의 몇 배인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],false,'{"seq":10,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"양치 컵을 사용하지 않을 때 5.89 L, 사용할 때 0.62 L의 물을 소비해요. 사용하지 않을 때 소비하는 물의 양은 사용할 때의 몇 배인가요?","options":[{"t":"9.5배","correct":true},{"t":"0.95배","mis":"M6-2-u3-X03"},{"t":"95배","mis":"M6-2-u3-X04"},{"t":"5.27배","mis":"M6-2-u3-X16"}],"explanation":["몇 배인지는 5.89 ÷ 0.62로 구해요.","두 칸씩 옮기면 589 ÷ 62예요.","589 ÷ 62 = 9.5 — 9.5배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#11','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',2,'mc','auto','넓이가 37 cm²인 평행사변형의 밑변의 길이가 7.4 cm일 때 높이는 몇 cm인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04','M6-2-u3-X16']::text[],false,'{"seq":11,"concept":"M6-2-u3-C6","difficulty":2,"kind":"mc","stem":"넓이가 37 cm²인 평행사변형의 밑변의 길이가 7.4 cm일 때 높이는 몇 cm인가요?","options":[{"t":"5 cm","correct":true},{"t":"0.5 cm","mis":"M6-2-u3-X03"},{"t":"50 cm","mis":"M6-2-u3-X04"},{"t":"29.6 cm","mis":"M6-2-u3-X16"}],"explanation":["높이 = 넓이 ÷ 밑변의 길이예요.","37 ÷ 7.4 = 370 ÷ 74예요.","370 ÷ 74 = 5 — 5 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#12','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',2,'sa','auto','바삭바삭 과자 집 찾아가기의 마지막 과자 카드예요. 11.1 ÷ 1.85의 몫은 얼마인가요?','{}'::text[],false,'{"seq":12,"concept":"M6-2-u3-C5","difficulty":2,"kind":"sa","stem":"바삭바삭 과자 집 찾아가기의 마지막 과자 카드예요. 11.1 ÷ 1.85의 몫은 얼마인가요?","answer":["6"],"explanation":["나누는 수 1.85가 자연수가 되도록 두 수의 소수점을 오른쪽으로 두 칸씩 옮겨요 — 빈 자리는 0으로 채워요.","11.1 ÷ 1.85는 1110 ÷ 185가 돼요 — 두 수에 똑같이 100을 곱했으니 몫은 그대로예요.","1110 ÷ 185 = 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#13','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C3',2,'mc','auto','바삭바삭 과자 집 찾아가기의 과자 카드예요. 20.9 ÷ 19의 몫은 얼마인가요?',ARRAY['M6-2-u3-X03','M6-2-u3-X04']::text[],false,'{"seq":13,"concept":"M6-2-u3-C3","difficulty":2,"kind":"mc","stem":"바삭바삭 과자 집 찾아가기의 과자 카드예요. 20.9 ÷ 19의 몫은 얼마인가요?","options":[{"t":"1.1","correct":true},{"t":"0.11","mis":"M6-2-u3-X03"},{"t":"11","mis":"M6-2-u3-X04"},{"t":"0.011","mis":"M6-2-u3-X03"}],"explanation":["나누는 수 19가 자연수라 소수점을 옮기지 않아요.","나누어지는 수의 소수점을 그대로 올려 찍어요.","20.9 ÷ 19 = 1.1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#14','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',2,'sa','auto','쌀 7.68 kg을 한 봉지에 0.32 kg씩 담으면 모두 몇 봉지가 되나요?','{}'::text[],false,'{"seq":14,"concept":"M6-2-u3-C8","difficulty":2,"kind":"sa","stem":"쌀 7.68 kg을 한 봉지에 0.32 kg씩 담으면 모두 몇 봉지가 되나요?","answer":["24"],"explanation":["7.68 ÷ 0.32를 계산하면 24예요.","0.32 kg씩 24번 주면 7.68 kg — 꼭 맞게 나누어져요.","그래서 24봉지에게 나누어 줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#15','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',2,'mc','auto','물 4 L를 한 명에게 1.33 L씩 3명에게 나누어 주었어요. 나누어 주고 남는 물는 몇 L인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X15']::text[],false,'{"seq":15,"concept":"M6-2-u3-C8","difficulty":2,"kind":"mc","stem":"물 4 L를 한 명에게 1.33 L씩 3명에게 나누어 주었어요. 나누어 주고 남는 물는 몇 L인가요?","options":[{"t":"0.01 L","correct":true},{"t":"0.0 L","mis":"M6-2-u3-X14"},{"t":"3.99 L","mis":"M6-2-u3-X15"},{"t":"1.33 L","mis":"M6-2-u3-X15"}],"explanation":["나누어 준 양은 1.33 × 3 = 3.99 (L)예요.","남는 양은 전체에서 나누어 준 양을 빼요.","4 − 3.99 = 0.01 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#16','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C1',2,'mc','auto','3.51 ÷ 0.9와 몫이 같은 나눗셈은 어느 것인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X02']::text[],false,'{"seq":16,"concept":"M6-2-u3-C1","difficulty":2,"kind":"mc","stem":"3.51 ÷ 0.9와 몫이 같은 나눗셈은 어느 것인가요?","options":[{"t":"35.1 ÷ 9","correct":true},{"t":"351 ÷ 9","mis":"M6-2-u3-X01"},{"t":"3.51 ÷ 9","mis":"M6-2-u3-X01"},{"t":"35.1 ÷ 0.09","mis":"M6-2-u3-X02"}],"explanation":["35.1 ÷ 9는 3.51 ÷ 0.9의 두 수에 똑같이 10을 곱한 식이에요.","351 ÷ 9는 두 수에 서로 다른 수를 곱한 식이에요.","몫은 3.9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#17','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',3,'mc','auto','3.08 ÷ 1.4를 계산하고 몫을 22라고 썼어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M6-2-u3-X01','M6-2-u3-X23','M6-2-u3-X03']::text[],false,'{"seq":17,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"3.08 ÷ 1.4를 계산하고 몫을 22라고 썼어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"몫의 소수점을 빠뜨려서","correct":true},{"t":"나누는 수만 옮겨서","mis":"M6-2-u3-X01"},{"t":"0을 내리지 않아서","mis":"M6-2-u3-X23"},{"t":"몫의 소수점을 옮기기 전 원래 자리에서 찍어서","mis":"M6-2-u3-X03"}],"explanation":["한 칸씩 옮기면 30.8 ÷ 14예요.","30.8 ÷ 14 = 2.2예요.","22는 몫의 소수점을 빠뜨린 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#18','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',3,'mc','auto','7.3 ÷ 3.65, 4.92 ÷ 1.2, 1.71 ÷ 0.45를 몫이 큰 것부터 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['M6-2-u3-X19','M6-2-u3-X20']::text[],false,'{"seq":18,"concept":"M6-2-u3-C5","difficulty":3,"kind":"mc","stem":"7.3 ÷ 3.65, 4.92 ÷ 1.2, 1.71 ÷ 0.45를 몫이 큰 것부터 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"4.92 ÷ 1.2, 1.71 ÷ 0.45, 7.3 ÷ 3.65","correct":true},{"t":"7.3 ÷ 3.65, 1.71 ÷ 0.45, 4.92 ÷ 1.2","mis":"M6-2-u3-X19"},{"t":"7.3 ÷ 3.65, 4.92 ÷ 1.2, 1.71 ÷ 0.45","mis":"M6-2-u3-X20"},{"t":"1.71 ÷ 0.45, 4.92 ÷ 1.2, 7.3 ÷ 3.65","mis":"M6-2-u3-X20"}],"explanation":["7.3 ÷ 3.65 = 2, 4.92 ÷ 1.2 = 4.1이에요.","1.71 ÷ 0.45 = 3.8이에요.","4.1 > 3.8 > 2 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#19','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C6',3,'ox','auto','52 ÷ 1.3의 몫은 52보다 작아요.',ARRAY['M6-2-u3-X09']::text[],false,'{"seq":19,"concept":"M6-2-u3-C6","difficulty":3,"kind":"ox","stem":"52 ÷ 1.3의 몫은 52보다 작아요.","answer":"O","reason_options":[{"t":"1.3은 1보다 커서 몫이 나누어지는 수보다 작아지기 때문에","correct":true},{"t":"소수로 나누면 몫은 늘 나누어지는 수보다 커지기 때문에","mis":"M6-2-u3-X09"}],"mis":"M6-2-u3-X09","explanation":["52 ÷ 1.3 = 520 ÷ 13 = 40이에요.","40은 52보다 작아요.","1보다 큰 수로 나누면 몫이 작아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#20','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C2',3,'mc','auto','2.32 ÷ 0.29를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M6-2-u3-X06','M6-2-u3-X05']::text[],false,'{"seq":20,"concept":"M6-2-u3-C2","difficulty":3,"kind":"mc","stem":"2.32 ÷ 0.29를 분모가 같은 분수의 나눗셈으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"⟨232/100⟩ ÷ ⟨29/100⟩","correct":true},{"t":"⟨232/100⟩ ÷ 0.29","mis":"M6-2-u3-X06"},{"t":"⟨232/100⟩ ÷ ⟨2/10⟩","mis":"M6-2-u3-X05"},{"t":"2.32 ÷ ⟨29/100⟩","mis":"M6-2-u3-X06"}],"explanation":["2.32는 ⟨232/100⟩, 0.29는 ⟨29/100⟩예요.","두 수를 분모가 100인 분수로 함께 바꿔야 분자끼리 나눌 수 있어요.","그래서 ⟨232/100⟩ ÷ ⟨29/100⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#21','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C7',3,'mc','auto','물 3.3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마실 수 있는 물은 몇 L인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M6-2-u3-X10','M6-2-u3-X12','M6-2-u3-X17']::text[],false,'{"seq":21,"concept":"M6-2-u3-C7","difficulty":3,"kind":"mc","stem":"물 3.3 L를 7명이 똑같이 나누어 마시려고 해요. 한 명이 마실 수 있는 물은 몇 L인지 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.47배","correct":true},{"t":"0.48배","mis":"M6-2-u3-X10"},{"t":"0.5배","mis":"M6-2-u3-X12"},{"t":"2.12배","mis":"M6-2-u3-X17"}],"explanation":["3.3 ÷ 7 = 0.471…이에요.","소수 셋째 자리 숫자 1을 보고 버려요.","0.47이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#22','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C8',3,'mc','auto','물 4 L를 한 명에게 1.33 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 양은 어느 것인가요?',ARRAY['M6-2-u3-X14','M6-2-u3-X13','M6-2-u3-X21']::text[],false,'{"seq":22,"concept":"M6-2-u3-C8","difficulty":3,"kind":"mc","stem":"물 4 L를 한 명에게 1.33 L씩 나누어 주면 나누어 줄 수 있는 사람 수와 남는 양은 어느 것인가요?","options":[{"t":"3명, 0.01 L","correct":true},{"t":"3명, 0.007 L","mis":"M6-2-u3-X14"},{"t":"4명, 0 L","mis":"M6-2-u3-X13"},{"t":"3.007명, 0 L","mis":"M6-2-u3-X21"}],"explanation":["4 ÷ 1.33 = 3.007…이므로 3명이에요.","나누어 준 양은 1.33 × 3 = 3.99 (L)예요.","남는 양은 4 − 3.99 = 0.01 (L)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#23','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',4,'essay','teacher','3.08 ÷ 1.4를 계산하고 몫을 22라고 쓴 친구가 있어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"3.08 ÷ 1.4를 계산하고 몫을 22라고 쓴 친구가 있어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 30.8 ÷ 14로 바꾸어 계산한 뒤 몫의 소수점을 빠뜨렸다. 몫의 소수점은 옮긴 소수점의 위치에서 올려 찍어 30.8 ÷ 14 = 2.2가 바른 몫이다.","scoring_points":["몫의 소수점을 빠뜨렸음을 썼는가","30.8 ÷ 14로 바꾸었는가","2.2를 구했는가"]},"explanation":["3.08 ÷ 1.4 = 30.8 ÷ 14예요.","30.8 ÷ 14 = 2.2예요.","22는 소수점을 빠뜨린 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#24','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',4,'essay','teacher','참기름 19.6 L를 한 병에 0.7 L씩 담으려고 해요. 참기름은 몇 병이 되는지 풀이 과정을 쓰고, 남는 참기름이 있는지 확인해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"참기름 19.6 L를 한 병에 0.7 L씩 담으려고 해요. 참기름은 몇 병이 되는지 풀이 과정을 쓰고, 남는 참기름이 있는지 확인해 보세요.","answer_guide":{"answer":"예: (참기름병의 수) = (전체 참기름의 양) ÷ (한 병에 담는 참기름의 양) = 19.6 ÷ 0.7 = 196 ÷ 7 = 28이므로 28병이 된다. 0.7 × 28 = 19.6 (L)이므로 남는 참기름은 없다.","scoring_points":["19.6 ÷ 0.7 식을 세웠는가","28병을 구했는가","0.7 × 28 = 19.6으로 남는 양이 없음을 확인했는가"]},"explanation":["19.6 ÷ 0.7 = 196 ÷ 7이에요.","196 ÷ 7 = 28 — 28병이에요.","0.7 × 28 = 19.6이라 남지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u3_review_d#25','math',6,2,'u3','','tb_g6_2_math_u3_review_d','unit_review','M6-2-u3-C5',4,'essay','teacher','어떤 수를 2.4로 나누어야 할 것을 잘못하여 곱했더니 34.56이 되었어요. 바르게 계산한 값을 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u3-C5","difficulty":4,"kind":"essay","stem":"어떤 수를 2.4로 나누어야 할 것을 잘못하여 곱했더니 34.56이 되었어요. 바르게 계산한 값을 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 어떤 수 × 2.4 = 34.56이므로 어떤 수 = 34.56 ÷ 2.4 = 14.4이다. 바르게 계산하면 14.4 ÷ 2.4 = 144 ÷ 24 = 6이다.","scoring_points":["어떤 수 = 34.56 ÷ 2.4로 식을 세웠는가","14.4를 구했는가","14.4 ÷ 2.4 = 6을 구했는가"]},"explanation":["어떤 수 = 34.56 ÷ 2.4 = 14.4예요.","바른 계산은 14.4 ÷ 2.4예요.","14.4 ÷ 2.4 = 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
